INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92838, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "错误", "is_correct": true, "explanation": "错误与“没错”意思相反，指事情有错。"}, {"text": "模糊", "is_correct": false, "explanation": "模糊指不清楚，与“没错”无反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "干净指没有污物，与“没错”无反义关系。"}, {"text": "遥远", "is_correct": false, "explanation": "遥远指距离很远，与“没错”无反义关系。"}], "correct_answer": "错误", "explanations": {"错误": "错误与“没错”意思相反，指事情有错。", "模糊": "模糊指不清楚，与“没错”无反义关系。", "干净": "干净指没有污物，与“没错”无反义关系。", "遥远": "遥远指距离很远，与“没错”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92838, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "错误", "is_correct": true, "explanation": "错误与“没错”意思相反，指事情有错。"}, {"text": "安静", "is_correct": false, "explanation": "安静指没有声音，与“没错”无反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮指好看，与“没错”无反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "陡峭指坡度很大，与“没错”无反义关系。"}], "correct_answer": "错误", "explanations": {"错误": "错误与“没错”意思相反，指事情有错。", "安静": "安静指没有声音，与“没错”无反义关系。", "漂亮": "漂亮指好看，与“没错”无反义关系。", "陡峭": "陡峭指坡度很大，与“没错”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92838, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示肯定，意思是对、正确、不会错。", "primary_collocate": null, "pronunciation": "méi cuò", "ipa": "mei³⁵ tsʰuo⁵¹", "syllable_count": 2, "sentences": [{"text": "照地图走，肯定没错。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路没错，我来过。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记得很清楚，地址没错。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听老师的话准没错。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的答案没错，我都检查过了。", "target_word": "没错", "complexity_tier": "T3", "furigana": "nǐ de dá àn méi cuò, wǒ dōu jiǎn chá guò le", "sentence_source": "generated"}, {"text": "他说的时间没错，是八点。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名字我写得没错。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜好吃，选它没错。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话号码没错，可是没人接。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数字都没错，不用再算了。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "表示事情正确、可靠、不会出错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f02719e-3c90-40e7-bbaa-c6aefb6742c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没错", "is_correct": true, "explanation": "没错表示事情正确、不会出错，与“照地图走”的可靠性一致。"}, {"text": "错", "is_correct": false, "explanation": "语义：“错”与“照地图走”的可靠性相反，前后意思矛盾。"}, {"text": "混乱", "is_correct": false, "explanation": "语义：照地图走应当有条理，说“混乱”与句意矛盾。"}, {"text": "危险", "is_correct": false, "explanation": "搭配：“肯定危险”与“照地图走”的前提不搭配，地图指路一般被认为是可靠的。"}], "explanations": {"没错": "没错表示事情正确、不会出错，与“照地图走”的可靠性一致。", "错": "语义：“错”与“照地图走”的可靠性相反，前后意思矛盾。", "混乱": "语义：照地图走应当有条理，说“混乱”与句意矛盾。", "危险": "搭配：“肯定危险”与“照地图走”的前提不搭配，地图指路一般被认为是可靠的。"}, "sentence_index": 0, "correct_answer": "没错"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的判断比我没错。", "explanation": "这里应该用〈正确〉。“没错”表示“不会错”，是非比较性的判断，不能用于比较两人谁更对，比较时要用“正确”。"}, {"text": "这座城市交通没错。", "explanation": "这里应该用〈发达〉。“没错”形容事情做得正确，不用来评价交通、经济等发展水平。"}, {"text": "这个花瓶没错。", "explanation": "这里应该用〈漂亮〉。“没错”说的是事情或做法正确，不用来赞美外观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没错", "is_correct": true, "explanation": "没错表示书写正确，与“这个名字我写得”的语境相符。"}, {"text": "糊涂", "is_correct": false, "explanation": "语义：“糊涂”形容人的头脑不清，不用来形容字迹是否正确。"}, {"text": "阴沉", "is_correct": false, "explanation": "语义：“阴沉”形容天色或神情，不用来描述写名字的样子。"}, {"text": "欢快", "is_correct": false, "explanation": "搭配：“写得欢快”不是自然的搭配，名字的书写不用“欢快”来形容。"}], "explanations": {"没错": "没错表示书写正确，与“这个名字我写得”的语境相符。", "糊涂": "语义：“糊涂”形容人的头脑不清，不用来形容字迹是否正确。", "阴沉": "语义：“阴沉”形容天色或神情，不用来描述写名字的样子。", "欢快": "搭配：“写得欢快”不是自然的搭配，名字的书写不用“欢快”来形容。"}, "sentence_index": 6, "correct_answer": "没错"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛没错。", "explanation": "这里应该用〈精彩〉。“没错”形容事情正确，不用来评价比赛好看与否。"}, {"text": "这个酒店没错。", "explanation": "这里应该用〈豪华〉。“没错”形容事情做得对，不用来形容酒店的档次。"}, {"text": "她的性格没错。", "explanation": "这里应该用〈温柔〉。“没错”指事情或做法正确，不用来评价人的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份计划的时间安排很没错，放心执行吧。", "corrected_sentence": "这份计划的时间安排没错，放心执行吧。", "error_description": "错误：“很没错”，正确：“没错”。“没错”本身已表示正确，不能再受“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的回答不没错，老师点了头。", "corrected_sentence": "他的回答没错，老师点了头。", "error_description": "错误：“不没错”，正确：“没错”。“没错”已是否定式的肯定，前面再加“不”构成双重否定，意思相反。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
