INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92839, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "比起是把两个东西放在一起，看哪个更好。", "primary_collocate": null, "pronunciation": "bǐ qǐ", "ipa": "pi˨˩ tɕʰi˨˩", "syllable_count": 2, "sentences": [{"text": "比起我，你的汉字写得更好。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起这家店，那家店的菜更好吃。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起红色，我觉得蓝色更好看。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起自己做饭，在外面吃更方便。", "target_word": "比起", "complexity_tier": "T3", "furigana": "bǐ qǐ zì jǐ zuò fàn, zài wài miàn chī gèng fāng biàn", "sentence_source": "generated"}, {"text": "比起小明，小红唱歌好听多了。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起旧手机，新手机照相更清楚。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起看书，听音乐让他更放松。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起公交车，地铁快得多。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起走路，骑车省时间。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起这件衣服，那件更适合你。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "比起来", "label": "复合形式"}], "register": "中性", "sense_fingerprint": "把两者放在一起比较，看谁更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92c164eb-a700-4e23-b7c0-fb840f4fdc05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92839, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比起", "is_correct": true, "explanation": "“比起”把两者放在一起，与“你的汉字写得更好”的比较相符。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：“按照”后接的是标准或规定，“按照我”不能表示比较对象。"}, {"text": "通过", "is_correct": false, "explanation": "配价：“通过”需要带动作或途径作宾语，“我”不能充当这一成分。"}, {"text": "被", "is_correct": false, "explanation": "语义：“被”引出施事，“被我”与“你的汉字写得更好”的句意不符。"}], "explanations": {"比起": "“比起”把两者放在一起，与“你的汉字写得更好”的比较相符。", "按照": "搭配：“按照”后接的是标准或规定，“按照我”不能表示比较对象。", "通过": "配价：“通过”需要带动作或途径作宾语，“我”不能充当这一成分。", "被": "语义：“被”引出施事，“被我”与“你的汉字写得更好”的句意不符。"}, "sentence_index": 0, "correct_answer": "比起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比起这本书，我正在看那本书。", "explanation": "这里误把〈比起〉当作普通的话题引入语来用。〈比起〉要把两个对象放在一起判断哪个更好，此句只陈述正在看的书，没有比较优劣，属于用错。"}, {"text": "比起这间屋子，我今天吃了三个包子。", "explanation": "这里误把〈比起〉当作单纯叙述事件的引入语来用。〈比起〉要引进可比的对象并接比较结论，此句只叙述吃包子的事，没有比较，属于用错。"}, {"text": "比起书包，我买了一台电脑。", "explanation": "这里误把〈比起〉当作单纯引出事件的引入语来用。〈比起〉要比较两个可以判断优劣的对象，此句只叙述买电脑的事，没有比较，属于用错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92839, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比起", "is_correct": true, "explanation": "“比起”引进比较对象，与“听音乐让他更放松”的比较相符。"}, {"text": "依靠", "is_correct": false, "explanation": "语义：“依靠”表示依赖，“依靠看书”与句意无关。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，句子并没有目的，“为了看书”不成立。"}, {"text": "凭借", "is_correct": false, "explanation": "配价：“凭借”要求凭以成事的手段作宾语，“看书”不符合这一要求。"}], "explanations": {"比起": "“比起”引进比较对象，与“听音乐让他更放松”的比较相符。", "依靠": "语义：“依靠”表示依赖，“依靠看书”与句意无关。", "为了": "语义：“为了”表示目的，句子并没有目的，“为了看书”不成立。", "凭借": "配价：“凭借”要求凭以成事的手段作宾语，“看书”不符合这一要求。"}, "sentence_index": 6, "correct_answer": "比起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比起老师，我的书包很重。", "explanation": "这里误把〈比起〉当作普通的话题引入语来用。〈比起〉要比较同类对象的优劣，老师与书包之间没有可比的优劣，属于用错。"}, {"text": "比起这个问题，天气是晴天。", "explanation": "这里误把〈比起〉当作普通的话题引入语来用。〈比起〉要把两个可比的对象放在一起评判，问题与天气不可比，属于用错。"}, {"text": "比起这辆车，那个苹果很红。", "explanation": "这里误把〈比起〉当作引出无关事物的连接语来用。〈比起〉要比较同类事物的优劣，车与苹果不可比，属于用错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92839, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比起了走路，我更愿意坐车。", "corrected_sentence": "比起走路，我更愿意坐车。", "error_description": "词性误用：“比起”是介词，后面不能带“了”，应说“比起走路”，不说“比起了走路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92839, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比起很公交车，我更愿意坐地铁。", "corrected_sentence": "比起公交车，我更愿意坐地铁。", "error_description": "位置错误：程度副词“很”不能插在介词“比起”与它的宾语之间，应说“比起公交车”，不说“比起很公交车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
