INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92840, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "引进比较的对象，表示相比之下。", "primary_collocate": null, "pronunciation": "bǐ qǐ", "ipa": "pi˨˩ tɕʰi˨˩", "syllable_count": 2, "sentences": [{"text": "比起北京，上海的夏天更热。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起坐车，我更喜欢走路。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起看电影，他更爱在家看书。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起去年，今年的雨少多了。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起哥哥，弟弟说话慢一些。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起米饭，我更爱吃面条。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起手机，妈妈更喜欢用电脑看新闻。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起冬天，我更喜欢秋天。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起城市，农村的空气好得多。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起上个月，这个月我们忙多了。", "target_word": "比起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "比起来", "label": "复合形式"}], "register": "中性", "sense_fingerprint": "引进比较对象，相比之下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92c164eb-a700-4e23-b7c0-fb840f4fdc05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比起", "is_correct": true, "explanation": "“比起”引进比较对象，与“上海的夏天更热”的比较相符。"}, {"text": "按照", "is_correct": false, "explanation": "语义：“按照”表示依据某种标准，“按照北京”无法引进比较对象。"}, {"text": "根据", "is_correct": false, "explanation": "语义：“根据”表示依据，“根据北京”不能表示与北京相比。"}, {"text": "通过", "is_correct": false, "explanation": "配价：“通过”需要带动作或途径作宾语，“北京”只是地点，不能充当这样的成分。"}], "explanations": {"比起": "“比起”引进比较对象，与“上海的夏天更热”的比较相符。", "按照": "语义：“按照”表示依据某种标准，“按照北京”无法引进比较对象。", "根据": "语义：“根据”表示依据，“根据北京”不能表示与北京相比。", "通过": "配价：“通过”需要带动作或途径作宾语，“北京”只是地点，不能充当这样的成分。"}, "sentence_index": 0, "correct_answer": "比起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比起去年，我的爸爸是医生。", "explanation": "这里误把〈比起〉当作单纯引入时间背景来用。〈比起〉要引进可比的对象并接比较结论，此句只陈述一件事实，没有比较，属于用错。"}, {"text": "比起我，我很喜欢这本书。", "explanation": "这里误把〈比起〉当作单纯的话题引入语来用。〈比起〉引进比较对象，句子的主语与对象都是“我”，没有可比的两方，无法成立。"}, {"text": "比起吃饭，他在吃饭。", "explanation": "这里误把〈比起〉当作单纯陈述正在做的事来用。〈比起〉引进比较对象，后面要有比较结论，此句只说明他在做什么，没有比较，属于用错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比起", "is_correct": true, "explanation": "“比起”引进比较对象，与“妈妈更喜欢用电脑”的比较相符。"}, {"text": "依靠", "is_correct": false, "explanation": "语义：“依靠”表示依赖某人或某物，“依靠手机”与句意无关。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，句子没有目的，“为了手机”不成立。"}, {"text": "凭借", "is_correct": false, "explanation": "配价：“凭借”要求凭以成事的手段或依据作宾语，“手机”不符合这一要求。"}], "explanations": {"比起": "“比起”引进比较对象，与“妈妈更喜欢用电脑”的比较相符。", "依靠": "语义：“依靠”表示依赖某人或某物，“依靠手机”与句意无关。", "为了": "语义：“为了”表示目的，句子没有目的，“为了手机”不成立。", "凭借": "配价：“凭借”要求凭以成事的手段或依据作宾语，“手机”不符合这一要求。"}, "sentence_index": 6, "correct_answer": "比起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比起这件衣服，那辆车在路上跑。", "explanation": "这里误把〈比起〉用来连接不可比的两件事。〈比起〉要比较同类对象的优劣，衣服与车在路上跑的事实之间没有可比性，属于用错。"}, {"text": "比起这件衣服，天气很好。", "explanation": "这里误把〈比起〉当作普通的话题引入语来用。〈比起〉要把两个可比的对象放在一起评判，衣服与天气不可比，属于用错。"}, {"text": "比起这件衣服，我的书很多。", "explanation": "这里误把〈比起〉当作普通的话题引入语来用。〈比起〉要比较同类事物的优劣，衣服与书的数量不可比，属于用错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比起城市来，我很更喜欢农村。", "corrected_sentence": "比起城市来，我更喜欢农村。", "error_description": "副词叠用错误：“很”与“更”都是程度副词，不能同时修饰同一个动词“喜欢”。去掉“很”即正确，应说“比起城市来，我更喜欢农村”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比起很旧车，新车省油得多。", "corrected_sentence": "比起旧车，新车省油得多。", "error_description": "位置错误：程度副词“很”不能插在介词“比起”与它的宾语之间，应说“比起旧车”，不说“比起很旧车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
