INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92846, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生产和生活所需的物质资料。", "primary_collocate": null, "pronunciation": "wù zī", "ipa": "u˥˩ tsɨ˥˥", "syllable_count": 2, "sentences": [{"text": "工厂缺少生产物资。", "target_word": "物资", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "国家正在储备重要物资。", "target_word": "物资", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "战争时期，物资非常缺乏。", "target_word": "物资", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家公司负责运送物资到各个城市。", "target_word": "物资", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洪水来了，政府马上调来大量物资。", "target_word": "物资", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们把生产物资放进了新仓库。", "target_word": "物资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要保证人民生活所需的物资。", "target_word": "物资", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "物资运不进去，城里的人只能等着。", "target_word": "物资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些物资的价格最近涨得很快。", "target_word": "物资", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司买了一批物资，准备送给山区的学校。", "target_word": "物资", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一批物资", "label": "量词"}, {"form": "生产物资", "label": "复合"}, {"form": "战略物资", "label": "复合"}], "register": "中性", "sense_fingerprint": "生产和生活所需的物质资料，多指国家、单位调配储备的物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abcd77a8-dfd0-4884-ad5f-32644d4c808a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92846, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物资", "is_correct": true, "explanation": "物资（wù zī）指生产和生活所需的物质资料，是正确答案。"}, {"text": "舞姿", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）声调不同，舞姿指舞蹈的姿势。"}, {"text": "污渍", "is_correct": false, "explanation": "wū（第一声）与 wù 声调不同，zì（第四声）与 zī（第一声）声调也不同，污渍指污迹。"}, {"text": "物质", "is_correct": false, "explanation": "zhì（第四声）与 zī 声母不同（zh 与 z），声调也不同，物质指构成事物的基本成分。"}, {"text": "误机", "is_correct": false, "explanation": "jī（第一声）与 zī 声母不同（j 与 z），误机指错过航班。"}], "explanations": {"物资": "物资（wù zī）指生产和生活所需的物质资料，是正确答案。", "舞姿": "wǔ（第三声）与 wù（第四声）声调不同，舞姿指舞蹈的姿势。", "污渍": "wū（第一声）与 wù 声调不同，zì（第四声）与 zī（第一声）声调也不同，污渍指污迹。", "物质": "zhì（第四声）与 zī 声母不同（zh 与 z），声调也不同，物质指构成事物的基本成分。", "误机": "jī（第一声）与 zī 声母不同（j 与 z），误机指错过航班。"}, "sentence_index": null, "correct_answer": "物资"}, "level_3": {"options": [{"text": "物资", "is_correct": true, "explanation": "物资指生产和生活所需的物质资料，与“缺少”搭配，符合句意。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不是工厂需要补充的东西，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是工厂可以缺少的生产要素，句意不通。"}, {"text": "面貌", "is_correct": false, "explanation": "搭配：“缺少”的宾语多是具体的东西，“面貌”不说缺少。"}], "explanations": {"物资": "物资指生产和生活所需的物质资料，与“缺少”搭配，符合句意。", "太阳": "语义：太阳不是工厂需要补充的东西，句意不通。", "天空": "语义：天空不是工厂可以缺少的生产要素，句意不通。", "面貌": "搭配：“缺少”的宾语多是具体的东西，“面貌”不说缺少。"}, "sentence_index": 0, "correct_answer": "物资"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司成了城市的物资。", "explanation": "这里把公司当作物资，但物资指生产和生活所需的物质资料，不指企业。"}, {"text": "这家公司负责运送一只物资到各个城市。", "explanation": "这里应该用〈批〉。物资用“批”计量，“只”不能用于物资。"}, {"text": "这座仓库成了山里的物资。", "explanation": "这里把仓库当作物资，但物资指生产和生活所需的物质资料，不指建筑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92846, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "物资", "is_correct": true, "explanation": "物资（wù zī）指生产和生活所需的物质资料，是正确答案。"}, {"text": "五指", "is_correct": false, "explanation": "wǔ（第三声）与 wù 声调不同，zhǐ 与 zī 声母和声调都不同，五指指五根手指。"}, {"text": "路资", "is_correct": false, "explanation": "lù（第四声）与 wù 声母不同（l 与 w），路资指路上的费用。"}, {"text": "误期", "is_correct": false, "explanation": "qī（第一声）与 zī 声母不同（q 与 z），误期指耽误期限。"}], "explanations": {"物资": "物资（wù zī）指生产和生活所需的物质资料，是正确答案。", "五指": "wǔ（第三声）与 wù 声调不同，zhǐ 与 zī 声母和声调都不同，五指指五根手指。", "路资": "lù（第四声）与 wù 声母不同（l 与 w），路资指路上的费用。", "误期": "qī（第一声）与 zī 声母不同（q 与 z），误期指耽误期限。"}, "sentence_index": null, "correct_answer": "物资"}, "level_3": {"options": [{"text": "物资", "is_correct": true, "explanation": "物资指生产和生活所需的物质资料，与“生活所需”搭配，符合句意。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是人，不是国家为保证生活而提供的物质。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是生活所需的物质，句意不通。"}, {"text": "面孔", "is_correct": false, "explanation": "搭配：“保证”的宾语多是权利或生活条件，不说保证面孔。"}], "explanations": {"物资": "物资指生产和生活所需的物质资料，与“生活所需”搭配，符合句意。", "学生": "语义：学生是人，不是国家为保证生活而提供的物质。", "名字": "语义：名字不是生活所需的物质，句意不通。", "面孔": "搭配：“保证”的宾语多是权利或生活条件，不说保证面孔。"}, "sentence_index": 6, "correct_answer": "物资"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个道理成了山区学校的物资。", "explanation": "这里把道理当作物资，但物资指生产和生活所需的物质资料，不指抽象的道理。"}, {"text": "公司买了一颗物资，准备送给山区的学校。", "explanation": "这里应该用〈批〉。物资用“批”计量，“颗”不能用于物资。"}, {"text": "一场大雨成了山区学校的物资。", "explanation": "这里把大雨当作物资，但物资指生产和生活所需的物质资料，不指天气现象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "货车上装着一个物资。", "corrected_sentence": "货车上装着一批物资。", "error_description": "“一个物资”错误，应说“一批物资”。物资应搭配量词“批”，“个”不能用于物资。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把一个物资运到了车站。", "corrected_sentence": "工人们把一批物资运到了车站。", "error_description": "“一个物资”错误，应说“一批物资”。物资应搭配量词“批”，“个”不能用于物资。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92847, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92847, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92847, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海湾是大海伸进陆地的一小片海。", "primary_collocate": null, "pronunciation": "hǎi wān", "ipa": "xaɪ˨˩ wan˥", "syllable_count": 2, "sentences": [{"text": "这个海湾很小，水也很浅。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船停在海湾里。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海湾边看日落。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海湾里的水很平静。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海湾旁边有一个小渔村。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在海湾里玩水。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风大的时候，渔船都躲进海湾。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从山上能看到整个海湾。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个海湾里有很多小鱼。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天海湾边来了很多游客。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个海湾", "label": "量词"}, {"form": "海湾战争", "label": "复合词"}, {"form": "海灣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大海伸进陆地的一小片海", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92c164eb-a700-4e23-b7c0-fb840f4fdc05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92847, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "海湾", "is_correct": true, "explanation": "海湾：大海伸进陆地的一小片海，是本题的正确答案。"}, {"text": "海滩", "is_correct": false, "explanation": "tān 与 wān 声调相同，只是声母不同（t 与 w），意思是海边的沙滩。"}, {"text": "海碗", "is_correct": false, "explanation": "wǎn（第三声）与 wān（第一声）声调不同，意思是大号的碗。"}, {"text": "海关", "is_correct": false, "explanation": "guān 与 wān 声母不同（g 与 w），意思是设在边境的检查机关。"}], "explanations": {"海湾": "海湾：大海伸进陆地的一小片海，是本题的正确答案。", "海滩": "tān 与 wān 声调相同，只是声母不同（t 与 w），意思是海边的沙滩。", "海碗": "wǎn（第三声）与 wān（第一声）声调不同，意思是大号的碗。", "海关": "guān 与 wān 声母不同（g 与 w），意思是设在边境的检查机关。"}, "sentence_index": null, "correct_answer": "海湾"}, "level_3": {"options": [{"text": "海湾", "is_correct": true, "explanation": "海湾：海洋伸入陆地的水域，既可以很小，水也可以很浅，符合句中的描述。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑，不是水域，“水也很浅”说不通。"}, {"text": "海洋", "is_correct": false, "explanation": "体貌：海洋范围极大，不能用“很小”来形容。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，没有水，“水也很浅”无从谈起。"}], "explanations": {"海湾": "海湾：海洋伸入陆地的水域，既可以很小，水也可以很浅，符合句中的描述。", "房子": "语义：房子是建筑，不是水域，“水也很浅”说不通。", "海洋": "体貌：海洋范围极大，不能用“很小”来形容。", "桌子": "语义：桌子是家具，没有水，“水也很浅”无从谈起。"}, "sentence_index": 0, "correct_answer": "海湾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个大陆之间的海湾很狭窄，是船只的重要通道。", "explanation": "这里应该用〈海峡〉。海峡位于两块陆地之间，是连接两片海的狭窄水道；海湾则是伸入同一块陆地内部的水域，不会横亘于两块大陆之间。"}, {"text": "这个海湾四面都是水，周围没有人住。", "explanation": "这里应该用〈岛〉。岛四面环水，海湾则三面环陆，“四面都是水”只能形容岛。"}, {"text": "我们乘船去了那只海湾，风景很美。", "explanation": "这里应该用量词〈个〉。海湾用“个”计量，不用“只”（“只”多用于动物等）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92847, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海湾", "is_correct": true, "explanation": "海湾：有陆地遮挡、可以避风的水域，渔船能躲进去。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：渔船不能“躲进房间”，“渔船”与“房间”搭配不当。"}, {"text": "森林", "is_correct": false, "explanation": "语义：森林是陆地上的树林，渔船无法躲进去。"}, {"text": "山谷", "is_correct": false, "explanation": "语义：山谷是陆地上的低地，不是水域，渔船进不去。"}], "explanations": {"海湾": "海湾：有陆地遮挡、可以避风的水域，渔船能躲进去。", "房间": "搭配：渔船不能“躲进房间”，“渔船”与“房间”搭配不当。", "森林": "语义：森林是陆地上的树林，渔船无法躲进去。", "山谷": "语义：山谷是陆地上的低地，不是水域，渔船进不去。"}, "sentence_index": 6, "correct_answer": "海湾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海湾三面环海，只有一面与陆地相连。", "explanation": "这里应该用〈半岛〉。半岛是三面环海的陆地；海湾是三面环陆的海水，两者正好相反。"}, {"text": "海湾伸进大海，像一只手。", "explanation": "这里应该用〈海岬〉。海岬是陆地伸入海中的部分；海湾是海伸入陆地，方向正好相反。"}, {"text": "海湾弯弯曲曲地流向大海。", "explanation": "这里应该用〈河流〉。河流才会弯弯曲曲地流向大海；海湾是大海的一部分，不会流向大海。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92847, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只海湾边有一座灯塔。", "corrected_sentence": "那个海湾边有一座灯塔。", "error_description": "量词错误：“海湾”应搭配量词“个”，应说“那个海湾”。“只”多用于动物等，不用于海湾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92847, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔民们每天早上都去海湾的捕鱼。", "corrected_sentence": "渔民们每天早上都去海湾捕鱼。", "error_description": "助词错误：“去”带处所宾语后直接接动词，中间不加“的”。应说“去海湾捕鱼”，不说“去海湾的捕鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
