INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92848, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海洋伸入陆地、三面被陆地环绕的水域。", "primary_collocate": null, "pronunciation": "hǎi wān", "ipa": "xaɪ˨˩ wan˥", "syllable_count": 2, "sentences": [{"text": "海湾三面是山，只有一面对着大海。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个海湾三面都是陆地。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上能看到那个大海湾。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家在海湾的北边。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海湾深入陆地，风浪比外海小。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市建在一个海湾旁。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船开进海湾，海面一下子安静了。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在地图上指着海湾，讲它的样子。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海湾的形状像一只张开的手。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海湾的口很窄，里面却很宽。", "target_word": "海湾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个海湾", "label": "量词"}, {"form": "海湾战争", "label": "复合词"}, {"form": "海灣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "海洋伸入陆地、三面环陆的水域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92c164eb-a700-4e23-b7c0-fb840f4fdc05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92848, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "海湾", "is_correct": true, "explanation": "海湾：海洋伸入陆地、三面被陆地环绕的水域，是本题的正确答案。"}, {"text": "海滩", "is_correct": false, "explanation": "tān 与 wān 声调相同，只是声母不同（t 与 w），意思是海边的沙滩。"}, {"text": "海碗", "is_correct": false, "explanation": "wǎn（第三声）与 wān（第一声）声调不同，意思是大号的碗。"}, {"text": "海关", "is_correct": false, "explanation": "guān 与 wān 声母不同（g 与 w），意思是设在边境的检查机关。"}], "explanations": {"海湾": "海湾：海洋伸入陆地、三面被陆地环绕的水域，是本题的正确答案。", "海滩": "tān 与 wān 声调相同，只是声母不同（t 与 w），意思是海边的沙滩。", "海碗": "wǎn（第三声）与 wān（第一声）声调不同，意思是大号的碗。", "海关": "guān 与 wān 声母不同（g 与 w），意思是设在边境的检查机关。"}, "sentence_index": null, "correct_answer": "海湾"}, "level_3": {"options": [{"text": "海湾", "is_correct": true, "explanation": "海湾：海洋伸入陆地、三面被陆地环绕的水域，正符合“三面是山”的描述。"}, {"text": "海洋", "is_correct": false, "explanation": "体貌：海洋范围极大，不可能三面是山，也不会只有一面对着大海。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是地形，不能三面是山。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是建筑内的房间，不是地形，不会“三面是山”。"}], "explanations": {"海湾": "海湾：海洋伸入陆地、三面被陆地环绕的水域，正符合“三面是山”的描述。", "海洋": "体貌：海洋范围极大，不可能三面是山，也不会只有一面对着大海。", "桌子": "语义：桌子是家具，不是地形，不能三面是山。", "教室": "语义：教室是建筑内的房间，不是地形，不会“三面是山”。"}, "sentence_index": 0, "correct_answer": "海湾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海湾的三面都是海水，只有一面连着陆地。", "explanation": "这里应该用〈半岛〉。半岛是三面环海、一面连陆的陆地；海湾是三面环陆的海水，两者正好相反。"}, {"text": "这个海湾的四周全是水，没有一块陆地。", "explanation": "这里应该用〈岛〉。岛四面环水；海湾三面环陆，“四周全是水”说的是岛。"}, {"text": "海湾沿着山谷一路流向大海。", "explanation": "这里应该用〈河流〉。河流才会沿山谷流向大海；海湾是大海伸入陆地的水域，不会流向大海。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92848, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海湾", "is_correct": true, "explanation": "海湾：海洋伸入陆地的水域，船可以开进去，海面也会因此变得平静。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：船不能开进房间，“船”与“房间”搭配不当。"}, {"text": "森林", "is_correct": false, "explanation": "语义：森林在陆地上，船无法开进，与“海面”也对不上。"}, {"text": "田野", "is_correct": false, "explanation": "语义：田野是陆地，船无法开进，句中的“海面”也无从谈起。"}], "explanations": {"海湾": "海湾：海洋伸入陆地的水域，船可以开进去，海面也会因此变得平静。", "房间": "搭配：船不能开进房间，“船”与“房间”搭配不当。", "森林": "语义：森林在陆地上，船无法开进，与“海面”也对不上。", "田野": "语义：田野是陆地，船无法开进，句中的“海面”也无从谈起。"}, "sentence_index": 6, "correct_answer": "海湾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海湾向大海伸出一个尖角。", "explanation": "这里应该用〈海岬〉。海岬是陆地伸入海中的尖角；海湾是海伸入陆地，方向正好相反。"}, {"text": "海湾露出水面，水鸟在上面休息。", "explanation": "这里应该用〈沙洲〉。沙洲是露出水面的陆地；海湾是海水伸入陆地形成的水域，说它“露出水面”等于把水域说成了陆地，概念混淆。"}, {"text": "海湾是一条狭窄的水道，两端都通向大洋。", "explanation": "这里应该用〈海峡〉。海峡是连接两片海的狭窄水道；海湾三面环陆，只有一个口通向外海，不能“两端都通向大洋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92848, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只海湾三面都是高山。", "corrected_sentence": "那个海湾三面都是高山。", "error_description": "量词错误：“海湾”应搭配量词“个”，应说“那个海湾”。“只”多用于动物等，不用于海湾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92848, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "游船缓缓地把开进了海湾。", "corrected_sentence": "游船缓缓地开进了海湾。", "error_description": "把字句错误：“把”后必须接宾语，不能直接接动词“开进”。去掉“把”即正确，应说“游船缓缓地开进了海湾”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
