INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92866, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "动物（如鸟、兽、鱼）躯干的后部，与肚子相对的一面。", "primary_collocate": null, "pronunciation": "bèi", "ipa": "pei˥˩", "syllable_count": 1, "sentences": [{"text": "小鸟的背是灰色的。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只骆驼的背上放着很多东西。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩骑在大象的背上笑着。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条鱼的背是黑色的，肚子是白色的。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫一生气，背就弯得高高的。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乌龟的背上有一个硬壳。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的背上落了很多雪。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛的背上站着一只小鸟。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青蛙的背是绿色的。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎的背上有黑色的条纹。", "target_word": "背", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "背部", "label": "复合"}, {"form": "驼背", "label": "复合"}], "register": "中性", "sense_fingerprint": "动物躯干的后部（背上、背是某种颜色）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9536ccae-044a-44e6-b63c-3b9235ea771b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92866, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "背", "is_correct": true, "explanation": "正确答案：背（bèi），指人或动物躯干的后部。"}, {"text": "北", "is_correct": false, "explanation": "běi（第三声）与 bèi（第四声）只有声调不同，意思是北方。"}, {"text": "配", "is_correct": false, "explanation": "pèi 与 bèi 只有声母不同（p 送气，b 不送气），意思是配合、搭配。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 bèi 只有韵母不同（-ai 与 -ei），意思是拜访、行礼。"}, {"text": "悲", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）只有声调不同，意思是伤心、悲伤。"}], "explanations": {"背": "正确答案：背（bèi），指人或动物躯干的后部。", "北": "běi（第三声）与 bèi（第四声）只有声调不同，意思是北方。", "配": "pèi 与 bèi 只有声母不同（p 送气，b 不送气），意思是配合、搭配。", "拜": "bài 与 bèi 只有韵母不同（-ai 与 -ei），意思是拜访、行礼。", "悲": "bēi（第一声）与 bèi（第四声）只有声调不同，意思是伤心、悲伤。"}, "sentence_index": null, "correct_answer": "背"}, "level_3": {"options": [{"text": "背", "is_correct": true, "explanation": "正确答案：背，指小鸟身体的后部，颜色可以是灰色的。"}, {"text": "道理", "is_correct": false, "explanation": "语义：道理是抽象的事理，没有颜色，“小鸟的道理是灰色的”说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指体型，不能用颜色来描述，这里说不通。"}, {"text": "头发", "is_correct": false, "explanation": "搭配：“灰色”多用于羽毛等，不能说小鸟的“头发是灰色的”。"}], "explanations": {"背": "正确答案：背，指小鸟身体的后部，颜色可以是灰色的。", "道理": "语义：道理是抽象的事理，没有颜色，“小鸟的道理是灰色的”说不通。", "身材": "体貌：身材指体型，不能用颜色来描述，这里说不通。", "头发": "搭配：“灰色”多用于羽毛等，不能说小鸟的“头发是灰色的”。"}, "sentence_index": 0, "correct_answer": "背"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小鸟张开背，飞上了天空。", "explanation": "这里应该用〈翅膀〉。背是躯干后部，不能张开；鸟飞要张开的是翅膀。"}, {"text": "小狗高兴地摇着背，跑来跑去。", "explanation": "这里应该用〈尾巴〉。摇动的是尾巴，尾巴在身体末端，不是躯干后部。"}, {"text": "小猪吃得太饱，背鼓得像个皮球。", "explanation": "这里应该用〈肚子〉。背与肚子在躯干两侧，吃饱后鼓起来的是肚子，不能说背鼓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92866, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "背", "is_correct": true, "explanation": "正确答案：背（bèi），指人或动物躯干的后部。"}, {"text": "杯", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）只有声调不同，意思是杯子。"}, {"text": "妹", "is_correct": false, "explanation": "mèi 与 bèi 只有声母不同（m 与 b），意思是妹妹。"}, {"text": "笨", "is_correct": false, "explanation": "bèn 与 bèi 只有韵母不同（-en 与 -ei），意思是不聪明、笨拙。"}, {"text": "费", "is_correct": false, "explanation": "fèi 与 bèi 只有声母不同（f 与 b），意思是花费、费用。"}], "explanations": {"背": "正确答案：背（bèi），指人或动物躯干的后部。", "杯": "bēi（第一声）与 bèi（第四声）只有声调不同，意思是杯子。", "妹": "mèi 与 bèi 只有声母不同（m 与 b），意思是妹妹。", "笨": "bèn 与 bèi 只有韵母不同（-en 与 -ei），意思是不聪明、笨拙。", "费": "fèi 与 bèi 只有声母不同（f 与 b），意思是花费、费用。"}, "sentence_index": null, "correct_answer": "背"}, "level_3": {"options": [{"text": "背", "is_correct": true, "explanation": "正确答案：背，指小狗身体的后部，雪可以落在上面。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光线形成的暗影，不能积雪，“小狗的影子上落了很多雪”说不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是抽象的称呼，不会有雪落在上面。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“落”指雪、灰尘等落在实体上，“颜色”不能承接积雪。"}], "explanations": {"背": "正确答案：背，指小狗身体的后部，雪可以落在上面。", "影子": "语义：影子是光线形成的暗影，不能积雪，“小狗的影子上落了很多雪”说不通。", "名字": "语义：名字是抽象的称呼，不会有雪落在上面。", "颜色": "搭配：“落”指雪、灰尘等落在实体上，“颜色”不能承接积雪。"}, "sentence_index": 6, "correct_answer": "背"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用背看清了远处的山。", "explanation": "这里应该用〈眼睛〉。看东西要用眼睛，背是身体后部，不能用来看。"}, {"text": "小狗把背张开，汪汪地叫了起来。", "explanation": "这里应该用〈嘴〉。汪汪叫要张嘴，背不能张开叫。"}, {"text": "小鸟用背闻了闻花的香味。", "explanation": "这里应该用〈鼻子〉。闻气味要用鼻子，背不能用来闻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小猫被吓到以后，背弓高高的。", "corrected_sentence": "小猫被吓到以后，背弓得高高的。", "error_description": "错误：“背弓高高的”；正确：“背弓得高高的”。动词后接表示程度或结果的补语时要用“得”，不能直接接形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只狮子的背金黄色的。", "corrected_sentence": "这只狮子的背是金黄色的。", "error_description": "错误：“背金黄色的”；正确：“背是金黄色的”。描述事物的颜色时，主语后要用“是”连接，漏掉“是”句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92869, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "实施", "is_correct": true, "explanation": "实施：开始执行封锁，与“解除封锁”的意思相反。"}, {"text": "聆听", "is_correct": false, "explanation": "聆听：指认真地听，与“解除封锁”没有反义关系。"}, {"text": "修复", "is_correct": false, "explanation": "修复：指把坏的东西修好，与“解除封锁”不构成反义。"}, {"text": "翻开", "is_correct": false, "explanation": "翻开：指把书或本子打开，与“解除封锁”没有反义关系。"}], "correct_answer": "实施", "explanations": {"实施": "实施：开始执行封锁，与“解除封锁”的意思相反。", "聆听": "聆听：指认真地听，与“解除封锁”没有反义关系。", "修复": "修复：指把坏的东西修好，与“解除封锁”不构成反义。", "翻开": "翻开：指把书或本子打开，与“解除封锁”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92869, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "施加", "is_correct": true, "explanation": "施加：对事物加以限制，与“解除限制”的意思相反。"}, {"text": "研磨", "is_correct": false, "explanation": "研磨：指把东西磨成粉，与“解除限制”没有反义关系。"}, {"text": "播放", "is_correct": false, "explanation": "播放：指放出声音或影像，与“解除限制”不构成反义。"}, {"text": "整理", "is_correct": false, "explanation": "整理：指把东西归置好，与“解除限制”没有反义关系。"}], "correct_answer": "施加", "explanations": {"施加": "施加：对事物加以限制，与“解除限制”的意思相反。", "研磨": "研磨：指把东西磨成粉，与“解除限制”没有反义关系。", "播放": "播放：指放出声音或影像，与“解除限制”不构成反义。", "整理": "整理：指把东西归置好，与“解除限制”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92869, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "解除是把原来有的限制去掉。", "primary_collocate": null, "pronunciation": "jiě chú", "ipa": "tɕjɛ˨˩ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "政府解除了旅行的限制。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长解除了手机的禁令。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校解除了学生晚上外出的限制。", "target_word": "解除", "complexity_tier": "T3", "furigana": "xué xiào jiě chú le xué shēng wǎn shàng wài chū de xiàn zhì", "sentence_source": "generated"}, {"text": "城市的封锁今天解除了。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈解除了对我的限制，我能晚点回家。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周一，这条路的交通管制就解除了。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师解除了不能说话的规定。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，对球员的禁赛解除了。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板解除了员工周末加班的限制。", "target_word": "解除", "complexity_tier": "T3", "furigana": "lǎo bǎn jiě chú le yuán gōng zhōu mò jiā bān de xiàn zhì", "sentence_source": "generated"}, {"text": "国家解除了对这种水果的进口限制。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解除了", "label": "体标（了）"}, {"form": "解除过", "label": "体标（过）"}, {"form": "解除禁令", "label": "复合"}], "register": "书面", "sense_fingerprint": "把原有的限制、禁令、管制等去掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f02719e-3c90-40e7-bbaa-c6aefb6742c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92869, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "解除", "is_correct": true, "explanation": "正确答案：解除（jiěchú）。"}, {"text": "戒除", "is_correct": false, "explanation": "戒除 jièchú 与 解除 jiěchú 只有第一个音节声调不同（jiè 为第四声，jiě 为第三声），意思是戒掉。"}, {"text": "接触", "is_correct": false, "explanation": "接触 jiēchù 与 解除 jiěchú 两个音节的声调都不同，意思是碰到、联系。"}, {"text": "解出", "is_correct": false, "explanation": "解出 jiěchū 与 解除 jiěchú 只有第二个音节声调不同（chū 为第一声），意思是算出、解答出来。"}, {"text": "借出", "is_correct": false, "explanation": "借出 jièchū 与 解除 jiěchú 两个音节的声调都不同，意思是借给别人。"}], "explanations": {"解除": "正确答案：解除（jiěchú）。", "戒除": "戒除 jièchú 与 解除 jiěchú 只有第一个音节声调不同（jiè 为第四声，jiě 为第三声），意思是戒掉。", "接触": "接触 jiēchù 与 解除 jiěchú 两个音节的声调都不同，意思是碰到、联系。", "解出": "解出 jiěchū 与 解除 jiěchú 只有第二个音节声调不同（chū 为第一声），意思是算出、解答出来。", "借出": "借出 jièchū 与 解除 jiěchú 两个音节的声调都不同，意思是借给别人。"}, "sentence_index": null, "correct_answer": "解除"}, "level_3": {"options": [{"text": "解除", "is_correct": true, "explanation": "解除：去掉政府对旅行的限制，与句意相合。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”多搭配生活、待遇，不说享受限制。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”的对象是艺术、风景，限制不能被欣赏。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车、船、飞机，不说驾驶限制。"}], "explanations": {"解除": "解除：去掉政府对旅行的限制，与句意相合。", "享受": "搭配：“享受”多搭配生活、待遇，不说享受限制。", "欣赏": "语义：“欣赏”的对象是艺术、风景，限制不能被欣赏。", "驾驶": "搭配：“驾驶”的对象是车、船、飞机，不说驾驶限制。"}, "sentence_index": 0, "correct_answer": "解除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个航班终于解除了。", "explanation": "这里应该用〈取消〉。解除用于限制、危险、约定等，航班不再飞要用取消。"}, {"text": "他解除了背包。", "explanation": "这里应该用〈解开〉。解除指消除抽象的限制，把背包的带子打开要用解开。"}, {"text": "这场比赛解除了。", "explanation": "这里应该用〈结束〉。解除用于限制、危险、约定等，比赛完了要用结束。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92869, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解除", "is_correct": true, "explanation": "解除：取消老师不能说话的规定，与句意相合。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”多搭配食物，不说品尝规定。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：“修剪”指剪掉多余的枝叶，规定不能被修剪。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”指用火加热食物，规定不能被烤。"}], "explanations": {"解除": "解除：取消老师不能说话的规定，与句意相合。", "品尝": "搭配：“品尝”多搭配食物，不说品尝规定。", "修剪": "语义：“修剪”指剪掉多余的枝叶，规定不能被修剪。", "烤": "语义：“烤”指用火加热食物，规定不能被烤。"}, "sentence_index": 6, "correct_answer": "解除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法院解除了这项判决。", "explanation": "这里应该用〈撤销〉。解除用于限制、危险、约定等，推翻判决要用撤销。"}, {"text": "医生解除了他的阑尾。", "explanation": "这里应该用〈摘除〉。解除不用于切除器官，切除阑尾要用摘除。"}, {"text": "公司解除了这个团队。", "explanation": "这里应该用〈解散〉。解除不用于团队，团体散掉要用解散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们终于解除在对出境的限制。", "corrected_sentence": "他们终于解除了对出境的限制。", "error_description": "“在”误用：“解除”后面接“了”表示完成，不能接“在”，应说“解除了对出境的限制”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92869, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们没解除了对夜间营业的限制。", "corrected_sentence": "他们没解除对夜间营业的限制。", "error_description": "错误：“没解除了”，正确：“没解除”。“没”否定尚未发生或未完成的动作时，句末不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92870, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "发布", "is_correct": true, "explanation": "发布：指发出警报，与“解除警报”的意思相反。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运：指把东西从一处移到另一处，与“解除警报”没有反义关系。"}, {"text": "观看", "is_correct": false, "explanation": "观看：指用眼睛看，与“解除警报”没有反义关系。"}, {"text": "修改", "is_correct": false, "explanation": "修改：指改动内容，与“解除警报”不构成反义。"}], "correct_answer": "发布", "explanations": {"发布": "发布：指发出警报，与“解除警报”的意思相反。", "搬运": "搬运：指把东西从一处移到另一处，与“解除警报”没有反义关系。", "观看": "观看：指用眼睛看，与“解除警报”没有反义关系。", "修改": "修改：指改动内容，与“解除警报”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92870, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "设置", "is_correct": true, "explanation": "设置：设立警戒，与“解除警戒”的意思相反。"}, {"text": "清洗", "is_correct": false, "explanation": "清洗：指把脏东西洗干净，与“解除警戒”没有反义关系。"}, {"text": "欣赏", "is_correct": false, "explanation": "欣赏：指觉得美而观看，与“解除警戒”不构成反义。"}, {"text": "翻译", "is_correct": false, "explanation": "翻译：指转换语言，与“解除警戒”没有反义关系。"}], "correct_answer": "设置", "explanations": {"设置": "设置：设立警戒，与“解除警戒”的意思相反。", "清洗": "清洗：指把脏东西洗干净，与“解除警戒”没有反义关系。", "欣赏": "欣赏：指觉得美而观看，与“解除警戒”不构成反义。", "翻译": "翻译：指转换语言，与“解除警戒”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92870, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "消除；去掉（限制、危险、约定等）。", "primary_collocate": null, "pronunciation": "jiě chú", "ipa": "tɕjɛ˨˩ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "公司和他解除了合同。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，他的危险已经解除了。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了她的话，我的误会解除了。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警报终于解除了，大家回家了。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板和他解除了约定。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了这种药，他的痛苦解除了。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要解除他的职务。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隔离解除后，他马上去看奶奶。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药能解除你的疲劳。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停后，山上的警戒解除了。", "target_word": "解除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解除了", "label": "体标（了）"}, {"form": "解除过", "label": "体标（过）"}, {"form": "解除合同", "label": "复合"}], "register": "书面", "sense_fingerprint": "消除或去掉限制、危险、约定、误会等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f02719e-3c90-40e7-bbaa-c6aefb6742c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92870, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "解除", "is_correct": true, "explanation": "正确答案：解除（jiěchú）。"}, {"text": "戒除", "is_correct": false, "explanation": "戒除 jièchú 与 解除 jiěchú 只有第一个音节声调不同（jiè 为第四声，jiě 为第三声），意思是戒掉（习惯）。"}, {"text": "接触", "is_correct": false, "explanation": "接触 jiēchù 与 解除 jiěchú 两个音节的声调都不同（jiē 为第一声，chù 为第四声），意思是碰到、联系。"}, {"text": "解出", "is_correct": false, "explanation": "解出 jiěchū 与 解除 jiěchú 只有第二个音节声调不同（chū 为第一声），意思是算出、解答出来。"}, {"text": "借出", "is_correct": false, "explanation": "借出 jièchū 与 解除 jiěchú 两个音节的声调都不同，意思是借给别人。"}], "explanations": {"解除": "正确答案：解除（jiěchú）。", "戒除": "戒除 jièchú 与 解除 jiěchú 只有第一个音节声调不同（jiè 为第四声，jiě 为第三声），意思是戒掉（习惯）。", "接触": "接触 jiēchù 与 解除 jiěchú 两个音节的声调都不同（jiē 为第一声，chù 为第四声），意思是碰到、联系。", "解出": "解出 jiěchū 与 解除 jiěchú 只有第二个音节声调不同（chū 为第一声），意思是算出、解答出来。", "借出": "借出 jièchū 与 解除 jiěchú 两个音节的声调都不同，意思是借给别人。"}, "sentence_index": null, "correct_answer": "解除"}, "level_3": {"options": [{"text": "解除", "is_correct": true, "explanation": "解除：消除合同的约束，与句意相合。"}, {"text": "设立", "is_correct": false, "explanation": "搭配：“设立”多搭配机构、制度，不说设立合同。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”的对象是场所、展览等，合同不能被参观。"}, {"text": "享用", "is_correct": false, "explanation": "搭配：“享用”多搭配食物、待遇，不说享用合同。"}], "explanations": {"解除": "解除：消除合同的约束，与句意相合。", "设立": "搭配：“设立”多搭配机构、制度，不说设立合同。", "参观": "语义：“参观”的对象是场所、展览等，合同不能被参观。", "享用": "搭配：“享用”多搭配食物、待遇，不说享用合同。"}, "sentence_index": 0, "correct_answer": "解除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛因为大雨解除了。", "explanation": "这里应该用〈取消〉。解除用于限制、危险、约定等，比赛不再举行要用取消。"}, {"text": "法院解除了这项判决。", "explanation": "这里应该用〈撤销〉。解除多用于限制、危险、约定等，推翻判决要用撤销。"}, {"text": "他解除了鞋带。", "explanation": "这里应该用〈解开〉。解除指消除限制、危险等抽象的东西，把鞋带的结打开要用解开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解除", "is_correct": true, "explanation": "解除：免去职务，符合句意。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：“烘焙”指做面包、点心的动作，职务不能被烘焙。"}, {"text": "浇灌", "is_correct": false, "explanation": "语义：“浇灌”用于植物或土地，与职务无关。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车、船、飞机，不说驾驶职务。"}], "explanations": {"解除": "解除：免去职务，符合句意。", "烘焙": "语义：“烘焙”指做面包、点心的动作，职务不能被烘焙。", "浇灌": "语义：“浇灌”用于植物或土地，与职务无关。", "驾驶": "搭配：“驾驶”的对象是车、船、飞机，不说驾驶职务。"}, "sentence_index": 6, "correct_answer": "解除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "垃圾终于解除了。", "explanation": "这里应该用〈清除〉。解除用于消除限制、危险、约定等，垃圾被清走要用清除。"}, {"text": "这个社团解除了。", "explanation": "这里应该用〈解散〉。解除针对限制、危险、约定等，社团解体、不再存在要用解散。"}, {"text": "士兵解除了阵地。", "explanation": "这里应该用〈撤离〉。解除针对限制或封锁，士兵离开阵地是转移，要用撤离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她终于解除在心里的顾虑。", "corrected_sentence": "她终于解除了心里的顾虑。", "error_description": "“在”误用：“解除”后面接“了”表示完成，不能接“在”，应说“解除了心里的顾虑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的疑虑还没有解除了。", "corrected_sentence": "他的疑虑还没有解除。", "error_description": "“了”误用：“还没有”否定尚未发生的动作，句末不能加“了”，应说“还没有解除”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
