INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92874, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预先计划好并杀害他人。", "primary_collocate": null, "pronunciation": "móu shā", "ipa": "mou̯˧˥ ʂa˥", "syllable_count": 2, "sentences": [{"text": "他为了钱计划谋杀富人。", "target_word": "谋杀", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "法院说，他谋杀了自己的邻居。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个坏人想谋杀证人，不让他说话。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察没有证据，说不清谁谋杀了他。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小说里的医生偷偷谋杀病人。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他曾经谋杀过一个人，所以进了监狱。", "target_word": "谋杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人想在飞机上谋杀这位歌手。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他先买了刀，再去谋杀那个老师。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们商量着怎样谋杀那位老人。", "target_word": "谋杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察怀疑他谋杀了自己的哥哥。", "target_word": "谋杀", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "谋杀了", "label": "体标（了）"}, {"form": "谋杀过", "label": "体标（过）"}, {"form": "谋杀案", "label": "复合词"}, {"form": "谋杀犯", "label": "复合词"}], "register": "中性", "sense_fingerprint": "预谋并杀害他人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a27985d7-ed1e-45a0-89a0-5af58ad339f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92874, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谋杀", "is_correct": true, "explanation": "谋杀：预先计划好并杀害他人，与“为了钱计划”和“富人”的语境相符，是本题正确答案。"}, {"text": "拍卖", "is_correct": false, "explanation": "搭配：“拍卖”的对象是物品，不能说拍卖富人。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，不能用来指对人的行为。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：“粉刷”用于墙面等表面，不能说粉刷富人。"}], "explanations": {"谋杀": "谋杀：预先计划好并杀害他人，与“为了钱计划”和“富人”的语境相符，是本题正确答案。", "拍卖": "搭配：“拍卖”的对象是物品，不能说拍卖富人。", "翻译": "语义：“翻译”指转换语言，不能用来指对人的行为。", "粉刷": "搭配：“粉刷”用于墙面等表面，不能说粉刷富人。"}, "sentence_index": 0, "correct_answer": "谋杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一时失手，谋杀了一个同事。", "explanation": "这里应该用〈误杀〉。谋杀指事先计划好的杀人，“一时失手”属于过失，不能说谋杀。"}, {"text": "法院依法谋杀了那个罪犯。", "explanation": "这里应该用〈处死〉。谋杀是非法且事先计划的杀人，依法执行死刑不能说谋杀。"}, {"text": "他因为太痛苦，谋杀了自己。", "explanation": "这里应该用〈自杀〉。谋杀的对象必须是别人，不能指杀害自己。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92874, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谋杀", "is_correct": true, "explanation": "谋杀：预先计划好并杀害他人，与“有人想在飞机上”和“这位歌手”的语境相符，是本题正确答案。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是交通工具，不能说驾驶这位歌手。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：“缝补”的对象是衣物等，不能说缝补这位歌手。"}, {"text": "冷藏", "is_correct": false, "explanation": "语义：“冷藏”指保存食物，不能用于人。"}], "explanations": {"谋杀": "谋杀：预先计划好并杀害他人，与“有人想在飞机上”和“这位歌手”的语境相符，是本题正确答案。", "驾驶": "搭配：“驾驶”的对象是交通工具，不能说驾驶这位歌手。", "缝补": "搭配：“缝补”的对象是衣物等，不能说缝补这位歌手。", "冷藏": "语义：“冷藏”指保存食物，不能用于人。"}, "sentence_index": 6, "correct_answer": "谋杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店主在抢劫中谋杀了一个抢匪。", "explanation": "这里应该用〈打死〉。谋杀是事先计划的杀害，在抢劫中为自卫打死抢匪不能说谋杀。"}, {"text": "他一时气愤，谋杀了妻子。", "explanation": "这里应该用〈伤害〉。谋杀必须事先计划，“一时气愤”是临时起意，不能说谋杀。"}, {"text": "战斗中，士兵谋杀了三个敌人。", "explanation": "这里应该用〈杀敌〉。谋杀是非法、事先计划的杀人，战斗中的杀敌不属于谋杀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他计划在下个月谋杀了那位富商。", "corrected_sentence": "他计划在下个月谋杀那位富商。", "error_description": "“谋杀”指计划中的未来行为，前面有“在下个月”，不能加“了”，应说“计划在下个月谋杀那位富商”，不能说“谋杀了那位富商”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他谋杀了过哥哥，后来被判刑。", "corrected_sentence": "他谋杀过哥哥，后来被判刑。", "error_description": "“谋杀”后面不能同时带“了”和“过”，应去掉“了”，说“谋杀过”，不能说“谋杀了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92876, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92876, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92876, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "眼睛的神态，目光所流露的神情。", "primary_collocate": null, "pronunciation": "yǎn shén", "ipa": "jɛn˨˩˦ ʂən˧˥", "syllable_count": 2, "sentences": [{"text": "她的眼神很温柔。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从他的眼神里，我看出他很难过。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的眼神又干净又明亮。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的眼神里有很多故事。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼神突然变得很害怕。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的眼神里有一点点高兴。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着妈妈的眼神，我什么也不想说了。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只小狗的眼神好像在说话。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的眼神让我觉得很安心。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼神很坚定，我相信他会做到。", "target_word": "眼神", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个眼神", "label": "量词"}, {"form": "眼神交流", "label": "复合词"}], "register": "中性", "sense_fingerprint": "眼睛里流露出来的心情和神态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30465e8-a764-427e-9db7-903b0f509c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92876, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "眼神", "is_correct": true, "explanation": "正确答案。眼神指眼睛的神态，目光所流露的神情。"}, {"text": "养神", "is_correct": false, "explanation": "yǎng（第三声）与 yǎn（第三声）只有韵母不同：ang 与 an。养神意思是调养精神、闭目休息，不是眼睛的神态。"}, {"text": "眼生", "is_correct": false, "explanation": "shēng（第一声）与 shén（第二声）韵母 eng 与 en 不同，声调也不同。眼生意思是面孔陌生、不熟悉。"}, {"text": "延伸", "is_correct": false, "explanation": "yán（第二声）与 yǎn（第三声）、shēn（第一声）与 shén（第二声）声调都不同。延伸意思是向外伸展。"}], "explanations": {"眼神": "正确答案。眼神指眼睛的神态，目光所流露的神情。", "养神": "yǎng（第三声）与 yǎn（第三声）只有韵母不同：ang 与 an。养神意思是调养精神、闭目休息，不是眼睛的神态。", "眼生": "shēng（第一声）与 shén（第二声）韵母 eng 与 en 不同，声调也不同。眼生意思是面孔陌生、不熟悉。", "延伸": "yán（第二声）与 yǎn（第三声）、shēn（第一声）与 shén（第二声）声调都不同。延伸意思是向外伸展。"}, "sentence_index": null, "correct_answer": "眼神"}, "level_3": {"options": [{"text": "眼神", "is_correct": true, "explanation": "正确答案。眼神是眼睛流露的神态，可以用“温柔”来形容。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑，不能用“温柔”形容。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指身体的体形，不是神态，不能说“温柔”。"}, {"text": "酒量", "is_correct": false, "explanation": "搭配：“酒量”只说大小，不与“温柔”搭配。"}], "explanations": {"眼神": "正确答案。眼神是眼睛流露的神态，可以用“温柔”来形容。", "房子": "语义：房子是建筑，不能用“温柔”形容。", "身材": "体貌：身材指身体的体形，不是神态，不能说“温柔”。", "酒量": "搭配：“酒量”只说大小，不与“温柔”搭配。"}, "sentence_index": 0, "correct_answer": "眼神"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他哭了一整夜，眼神又红又肿。", "explanation": "这里应该用〈眼睛〉。“又红又肿”说的是眼睛这个器官，眼神指眼睛流露的神态，不能红肿。"}, {"text": "她的眼神哑了，说不出话。", "explanation": "这里应该用〈嗓子〉。“哑”说的是嗓子发不出声，眼神是眼睛的神态，不能说哑。"}, {"text": "他眼神发白，像是生病了。", "explanation": "这里应该用〈脸色〉。脸色指脸部的气色，可以发白；眼神只指眼睛的神态，不能说“发白”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼神", "is_correct": true, "explanation": "正确答案。“看着”的对象是眼神，可以说“看着妈妈的眼神”。"}, {"text": "声音", "is_correct": false, "explanation": "配价：“看”的对象要能被看见，“声音”只能听，不能看。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”是嗅觉或味觉的对象，不能用眼睛“看”。"}, {"text": "笑声", "is_correct": false, "explanation": "配价：“笑声”能听见，不能被“看”，与“看着”搭配不通。"}], "explanations": {"眼神": "正确答案。“看着”的对象是眼神，可以说“看着妈妈的眼神”。", "声音": "配价：“看”的对象要能被看见，“声音”只能听，不能看。", "味道": "语义：“味道”是嗅觉或味觉的对象，不能用眼睛“看”。", "笑声": "配价：“笑声”能听见，不能被“看”，与“看着”搭配不通。"}, "sentence_index": 6, "correct_answer": "眼神"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的眼神很结实，坐上去很稳。", "explanation": "这里应该用〈质量〉。“结实”和“坐上去很稳”说的是东西的质量；眼神指眼睛的神态，不能用来形容椅子。"}, {"text": "她的眼神很好听，让人想多听一会儿。", "explanation": "这里应该用〈声音〉。“好听”“想多听”说的是声音，眼神指眼睛的神态，不能用来形容声音。"}, {"text": "这碗汤的眼神很咸，你少放点盐吧。", "explanation": "这里应该用〈味道〉。“咸”说的是味道，眼神不能用来形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她温柔眼神让人难忘。", "corrected_sentence": "她温柔的眼神让人难忘。", "error_description": "错误：“温柔”修饰名词“眼神”时，中间要加“的”。错误形式是“温柔眼神”，正确形式是“温柔的眼神”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她朝我投来一只眼神，我立刻明白了。", "corrected_sentence": "她朝我投来一个眼神，我立刻明白了。", "error_description": "错误：“眼神”的量词用错，应该用“个”，不能用“只”。“只”多用于动物或成对的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
