INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92881, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92881, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "近日是最近的这几天。", "primary_collocate": null, "pronunciation": "jìn rì", "ipa": "tɕin˥˩ ʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "近日我很忙，没有时间看书。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他近日常常头疼，晚上睡不好。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近日来，这里的人越来越多。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近日，小王搬到了新家。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近日大家都在说这件事。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我近日读完了一本颇为有趣的书。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路近日在修，车很难过去。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近日她情绪低落，不愿与朋友相见。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近日，网上出现了一张奇怪的照片。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师近日去外地开会了，下周才回来。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "说话时刚过去的最近几天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9536ccae-044a-44e6-b63c-3b9235ea771b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92881, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当天", "is_correct": false, "explanation": "语义：“当天”需要前文提到的具体某天作依托，句中没有这样的所指。"}, {"text": "近日", "is_correct": true, "explanation": "正确：“近日”指说话时刚过去的最近几天，与“很忙，没有时间看书”相合。"}, {"text": "那天", "is_correct": false, "explanation": "语义：“那天”同样需要前文所指的日子，句中找不到可指的对象。"}, {"text": "去年", "is_correct": false, "explanation": "时间：“去年”指整年前，超出“近日”最近几天的范围。"}], "explanations": {"当天": "语义：“当天”需要前文提到的具体某天作依托，句中没有这样的所指。", "近日": "正确：“近日”指说话时刚过去的最近几天，与“很忙，没有时间看书”相合。", "那天": "语义：“那天”同样需要前文所指的日子，句中找不到可指的对象。", "去年": "时间：“去年”指整年前，超出“近日”最近几天的范围。"}, "sentence_index": 0, "correct_answer": "近日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的弟弟近日出生，现在已经上小学了。", "explanation": "“近日”指刚过去的几天，“近日出生”意味着刚出生，而“现在已经上小学了”表示已经长大，二者时间矛盾。"}, {"text": "小王在十年前的近日搬到了新家。", "explanation": "“近日”指说话时刚过去的几天，不能用于十年前这样的远期时间。"}, {"text": "小王近日搬了十年家。", "explanation": "“近日”只指很短的一段时间，不能与“十年”这样的长时段搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92881, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当时", "is_correct": false, "explanation": "语义：“当时”需要前文所指的时间，句中没有可指的时刻。"}, {"text": "那时", "is_correct": false, "explanation": "语义：“那时”同样需要前文的指称，句中找不到对应的时间。"}, {"text": "近日", "is_correct": true, "explanation": "正确：“近日”指说话时刚过去的最近几天，与“这条路在修，车很难过去”的情况相合。"}, {"text": "去年", "is_correct": false, "explanation": "时间：“去年”指整年前，超出“近日”刚过去几天的范围，与“在修”的现状不符。"}], "explanations": {"当时": "语义：“当时”需要前文所指的时间，句中没有可指的时刻。", "那时": "语义：“那时”同样需要前文的指称，句中找不到对应的时间。", "近日": "正确：“近日”指说话时刚过去的最近几天，与“这条路在修，车很难过去”的情况相合。", "去年": "时间：“去年”指整年前，超出“近日”刚过去几天的范围，与“在修”的现状不符。"}, "sentence_index": 6, "correct_answer": "近日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师近日去外地开会了，去年才回来。", "explanation": "“近日”指说话时刚过去的几天，与“去年才回来”的时间相矛盾。"}, {"text": "老师在3月5日近日去外地开会了。", "explanation": "“近日”不能与具体的日期搭配，它表示较模糊的近期时间。"}, {"text": "老师近日去外地开会，那次会议很久以前就结束了。", "explanation": "“近日”指最近几天，不能用来说很久以前结束的会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92881, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我近日的没去上班，身体不舒服。", "corrected_sentence": "我近日没去上班，身体不舒服。", "error_description": "错误形式是“近日的没去上班”，正确形式是“近日没去上班”。“近日”作时间状语，后面不能加“的”，直接放在主语之后、否定词“没”之前即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92881, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师近日了一直在办公室。", "corrected_sentence": "老师近日一直在办公室。", "error_description": "错误形式是“近日了一直在办公室”，正确形式是“近日一直在办公室”。“近日”是时间词，后面不能加动态助词“了”，应直接接“一直在办公室”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
