INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92882, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "最近几天；不久前或不久后的一段日子。", "primary_collocate": null, "pronunciation": "jìn rì", "ipa": "tɕin˥˩ ʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "近日，这个城市连续下了几场大雨。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近日天气变冷，请大家多穿衣服。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司近日宣布了一个新计划。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个产品近日将在市场上出售。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校近日会通知大家考试的时间。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他近日一直在医院照顾生病的父亲。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近日，很多游客来到这座小城参观。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新书近日就要出版了，请大家等一等。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他近日身体不太好，需要休息。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府近日发出通知，提醒大家注意安全。", "target_word": "近日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "不久前或不久后的几天（可指过去也可指将来）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9536ccae-044a-44e6-b63c-3b9235ea771b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92882, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明天", "is_correct": false, "explanation": "体貌：句中“下了”表示已经发生的动作，而“明天”指尚未到来的日子，二者冲突。"}, {"text": "近日", "is_correct": true, "explanation": "正确：“近日”指最近几天，与“连续下了几场大雨”的时段相合。"}, {"text": "此刻", "is_correct": false, "explanation": "语义：“此刻”指眼下的一瞬间，与“连续下了几场大雨”这种持续一段时间的情况矛盾。"}, {"text": "明年", "is_correct": false, "explanation": "体貌：“明年”尚未到来，不能与表示已完成的“下了”搭配。"}], "explanations": {"明天": "体貌：句中“下了”表示已经发生的动作，而“明天”指尚未到来的日子，二者冲突。", "近日": "正确：“近日”指最近几天，与“连续下了几场大雨”的时段相合。", "此刻": "语义：“此刻”指眼下的一瞬间，与“连续下了几场大雨”这种持续一段时间的情况矛盾。", "明年": "体貌：“明年”尚未到来，不能与表示已完成的“下了”搭配。"}, "sentence_index": 0, "correct_answer": "近日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车是我近日买的，已经开了十年了。", "explanation": "“近日”指最近几天，与“已经开了十年”的长时段相矛盾，不能用来说很久以前买的车。"}, {"text": "我们近日分开了三年。", "explanation": "“近日”只指较短的一段时间，不能与“三年”这样的长时段搭配。"}, {"text": "他是我近日的一位老同学。", "explanation": "“近日”指最近几天，与“老同学”所表示的长久关系相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92882, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三年前", "is_correct": false, "explanation": "时间：“三年前”指很久以前，超出“近日”不久前或不久后几天的范围。"}, {"text": "近日", "is_correct": true, "explanation": "正确：“近日”指最近几天，与句中“很多游客来到”的时间相合。"}, {"text": "去年", "is_correct": false, "explanation": "时间：“去年”指整年前，超出“近日”不久前或不久后几天的范围。"}, {"text": "十年前", "is_correct": false, "explanation": "时间：“十年前”指很久以前，超出“近日”不久前或不久后几天的范围。"}], "explanations": {"三年前": "时间：“三年前”指很久以前，超出“近日”不久前或不久后几天的范围。", "近日": "正确：“近日”指最近几天，与句中“很多游客来到”的时间相合。", "去年": "时间：“去年”指整年前，超出“近日”不久前或不久后几天的范围。", "十年前": "时间：“十年前”指很久以前，超出“近日”不久前或不久后几天的范围。"}, "sentence_index": 6, "correct_answer": "近日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在2010年近日搬进了这栋楼。", "explanation": "“近日”指说话前后不久的几天，不能与“2010年”这样的具体年份搭配。"}, {"text": "这份通知是三十年前近日发出的。", "explanation": "“近日”指不久前的几天，与“三十年前”的时间跨度矛盾。"}, {"text": "市政府近日那次通知，早在很久以前就已经发出了。", "explanation": "“近日”指最近几天，与“早在很久以前”的说法矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校的图书馆近日的关门了。", "corrected_sentence": "学校的图书馆近日关门了。", "error_description": "错误形式是“近日的关门了”，正确形式是“近日关门了”。“近日”作时间状语，直接放在动词“关门”前，后面不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家医院近日的增加了护士。", "corrected_sentence": "这家医院近日增加了护士。", "error_description": "错误形式是“近日的增加了护士”，正确形式是“近日增加了护士”。“近日”作时间状语，直接放在动词“增加”前，后面不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92883, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "细", "is_correct": true, "explanation": "与“粗”互为反义，指圆形或条状物直径小、不粗。"}, {"text": "短", "is_correct": false, "explanation": "“短”说长度，与“粗”指直径大小不构成反义关系。"}, {"text": "窄", "is_correct": false, "explanation": "“窄”说宽度，与“粗”没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "“轻”说重量，与“粗”的直径义无关。"}], "correct_answer": "细", "explanations": {"细": "与“粗”互为反义，指圆形或条状物直径小、不粗。", "短": "“短”说长度，与“粗”指直径大小不构成反义关系。", "窄": "“窄”说宽度，与“粗”没有反义关系。", "轻": "“轻”说重量，与“粗”的直径义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92883, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "细", "is_correct": true, "explanation": "与“粗”互为反义，指圆形或条状物直径小、不粗。"}, {"text": "薄", "is_correct": false, "explanation": "“薄”说扁平物的厚度小，与“粗”没有反义关系。"}, {"text": "宽", "is_correct": false, "explanation": "“宽”说宽度，与“粗”的直径义无反义关系。"}, {"text": "软", "is_correct": false, "explanation": "“软”说质地柔软，与“粗”没有反义关系。"}], "correct_answer": "细", "explanations": {"细": "与“粗”互为反义，指圆形或条状物直径小、不粗。", "薄": "“薄”说扁平物的厚度小，与“粗”没有反义关系。", "宽": "“宽”说宽度，与“粗”的直径义无反义关系。", "软": "“软”说质地柔软，与“粗”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92883, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "粗是东西圆圆的，中间很宽，不细。", "primary_collocate": null, "pronunciation": "cū", "ipa": "tsʰu˥", "syllable_count": 1, "sentences": [{"text": "这棵树很粗，三个人才抱得住。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手指又短又粗。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一根粗一点的绳子。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根水管太粗了，放不进墙里。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象的腿又粗又壮。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着一支很粗的笔写大字。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的胳膊比我的粗多了。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根竹子不粗，也不细。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树干那么粗，一把小斧子砍不断。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把粗的那根棍子递给我。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "粗细", "label": "复合"}], "register": "中性", "sense_fingerprint": "圆形物体直径大、不细", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3f55f56-4259-4abb-912d-1e43b9d9f8b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92883, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "粗", "is_correct": true, "explanation": "粗（cū，第一声）指圆形物体直径大、不细，是本题要听出的词。"}, {"text": "醋", "is_correct": false, "explanation": "cù（第四声）与 cū（第一声）声调不同，意思是醋。"}, {"text": "初", "is_correct": false, "explanation": "chū 与 cū 声母不同（ch 与 c），意思是开始、第一。"}, {"text": "出", "is_correct": false, "explanation": "chū 与 cū 声母不同（ch 与 c），意思是出来、出去。"}, {"text": "猪", "is_correct": false, "explanation": "zhū 与 cū 声母不同（zh 与 c），意思是猪。"}, {"text": "促", "is_correct": false, "explanation": "cù（第四声）与 cū（第一声）声调不同，意思是促使、推动。"}], "explanations": {"粗": "粗（cū，第一声）指圆形物体直径大、不细，是本题要听出的词。", "醋": "cù（第四声）与 cū（第一声）声调不同，意思是醋。", "初": "chū 与 cū 声母不同（ch 与 c），意思是开始、第一。", "出": "chū 与 cū 声母不同（ch 与 c），意思是出来、出去。", "猪": "zhū 与 cū 声母不同（zh 与 c），意思是猪。", "促": "cù（第四声）与 cū（第一声）声调不同，意思是促使、推动。"}, "sentence_index": null, "correct_answer": "粗"}, "level_3": {"options": [{"text": "粗", "is_correct": true, "explanation": "“粗”描述树干直径大，与“三个人才抱得住”相符。"}, {"text": "细", "is_correct": false, "explanation": "语义：“细”指直径小，与“三个人才抱得住”矛盾，细树不需要三个人合抱。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”说高度，与“三个人才抱得住”描述的粗细无关。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”说质地，不用来形容树干的粗细。"}], "explanations": {"粗": "“粗”描述树干直径大，与“三个人才抱得住”相符。", "细": "语义：“细”指直径小，与“三个人才抱得住”矛盾，细树不需要三个人合抱。", "高": "语义：“高”说高度，与“三个人才抱得住”描述的粗细无关。", "软": "搭配：“软”说质地，不用来形容树干的粗细。"}, "sentence_index": 0, "correct_answer": "粗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块木板很粗，能承受很重的东西。", "explanation": "这里应该用〈厚〉。粗指圆柱形或条状物的直径大；木板等扁平物的厚薄要用厚。"}, {"text": "这条马路很粗，两辆卡车可以并排开过去。", "explanation": "这里应该用〈宽〉。粗指条状物直径大，马路的宽窄要用宽。"}, {"text": "这根绳子很粗，能从教室拉到操场。", "explanation": "这里应该用〈长〉。粗指条状物横截面大，绳子的长短要用长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92883, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "粗", "is_correct": true, "explanation": "粗（cū，第一声）指圆形物体直径大、不细，是本题要听出的词。"}, {"text": "苏", "is_correct": false, "explanation": "sū 与 cū 声母不同（s 与 c），意思是苏醒、江苏。"}, {"text": "租", "is_correct": false, "explanation": "zū 与 cū 声母不同（z 与 c），声调相同，意思是出租、租用。"}, {"text": "初", "is_correct": false, "explanation": "chū 与 cū 声母不同（ch 与 c），声调相同，意思是开始、第一。"}, {"text": "簇", "is_correct": false, "explanation": "cù（第四声）与 cū（第一声）声调不同，意思是丛、聚集，如“一簇花”。"}], "explanations": {"粗": "粗（cū，第一声）指圆形物体直径大、不细，是本题要听出的词。", "苏": "sū 与 cū 声母不同（s 与 c），意思是苏醒、江苏。", "租": "zū 与 cū 声母不同（z 与 c），声调相同，意思是出租、租用。", "初": "chū 与 cū 声母不同（ch 与 c），声调相同，意思是开始、第一。", "簇": "cù（第四声）与 cū（第一声）声调不同，意思是丛、聚集，如“一簇花”。"}, "sentence_index": null, "correct_answer": "粗"}, "level_3": {"options": [{"text": "粗", "is_correct": true, "explanation": "“粗”说胳膊的粗细，与“比我的……多了”相符。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”说高度，不用来比较胳膊的粗细。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线或颜色，与胳膊的粗细无关。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说速度，与胳膊的粗细无关。"}], "explanations": {"粗": "“粗”说胳膊的粗细，与“比我的……多了”相符。", "矮": "搭配：“矮”说高度，不用来比较胳膊的粗细。", "亮": "语义：“亮”说光线或颜色，与胳膊的粗细无关。", "慢": "语义：“慢”说速度，与胳膊的粗细无关。"}, "sentence_index": 6, "correct_answer": "粗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间很粗，能放下两张床。", "explanation": "这里应该用〈大〉。粗指条状物直径大，房间的大小要用大。"}, {"text": "这只猫很粗，一眨眼就跑没影了。", "explanation": "这里应该用〈快〉。粗指条状物直径大，猫跑得快要用快。"}, {"text": "这座楼很粗，有三十层。", "explanation": "这里应该用〈高〉。粗指条状物横截面大，楼的高低要用高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_v