INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根木柱粗要两个人才能抱住。", "corrected_sentence": "这根木柱粗得要两个人才能抱住。", "error_description": "错误形式“粗要两个人才能抱住”，正确形式“粗得要两个人才能抱住”。“粗”作谓语后接结果或程度补语时要用“得”，漏掉“得”，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
