INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92884, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（条状物）横截面大；不细。", "primary_collocate": null, "pronunciation": "cū", "ipa": "tsʰu˥", "syllable_count": 1, "sentences": [{"text": "这根电线太粗，插头放不进去。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的头发又黑又粗。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种面条比较粗，要多煮一会儿。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用粗铁丝把门绑住了。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毛衣的线很粗，穿起来很暖和。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眉毛又粗又黑。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支铅笔的笔芯太粗了，写不出小字。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钓鱼线别买太粗的，鱼会看见。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条绳子粗得像手腕。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根线太粗了，穿不进针眼里。", "target_word": "粗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "粗细", "label": "复合"}], "register": "中性", "sense_fingerprint": "条状物横截面大、不细", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3f55f56-4259-4abb-912d-1e43b9d9f8b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92884, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "粗", "is_correct": true, "explanation": "粗（cū，第一声）指条状物横截面大、不细，是本题要听出的词。"}, {"text": "醋", "is_correct": false, "explanation": "cù（第四声）与 cū（第一声）声调不同，意思是醋。"}, {"text": "初", "is_correct": false, "explanation": "chū 与 cū 声母不同（ch 与 c），意思是开始、第一。"}, {"text": "出", "is_correct": false, "explanation": "chū 与 cū 声母不同（ch 与 c），意思是出来、出去。"}, {"text": "猪", "is_correct": false, "explanation": "zhū 与 cū 声母不同（zh 与 c），意思是猪。"}, {"text": "促", "is_correct": false, "explanation": "cù（第四声）与 cū（第一声）声调不同，意思是促使、推动。"}], "explanations": {"粗": "粗（cū，第一声）指条状物横截面大、不细，是本题要听出的词。", "醋": "cù（第四声）与 cū（第一声）声调不同，意思是醋。", "初": "chū 与 cū 声母不同（ch 与 c），意思是开始、第一。", "出": "chū 与 cū 声母不同（ch 与 c），意思是出来、出去。", "猪": "zhū 与 cū 声母不同（zh 与 c），意思是猪。", "促": "cù（第四声）与 cū（第一声）声调不同，意思是促使、推动。"}, "sentence_index": null, "correct_answer": "粗"}, "level_3": {"options": [{"text": "粗", "is_correct": true, "explanation": "“粗”说电线的横截面大，与“插头放不进去”的原因相符。"}, {"text": "热", "is_correct": false, "explanation": "语义：“热”说温度，与插头能否放进去无关，句子不通。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说高度，不用来形容电线的粗细。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”说颜色，与插头能否放进去无关。"}], "explanations": {"粗": "“粗”说电线的横截面大，与“插头放不进去”的原因相符。", "热": "语义：“热”说温度，与插头能否放进去无关，句子不通。", "高": "搭配：“高”说高度，不用来形容电线的粗细。", "白": "语义：“白”说颜色，与插头能否放进去无关。"}, "sentence_index": 0, "correct_answer": "粗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书很粗，有上千页。", "explanation": "这里应该用〈厚〉。粗指条状物横截面大；书、本子等扁平物的厚薄要用厚。"}, {"text": "这条河很粗，船能开过去。", "explanation": "这里应该用〈宽〉。粗指条状物直径大，河面的宽窄要用宽。"}, {"text": "这块玻璃很粗，能从门口铺到楼梯。", "explanation": "这里应该用〈长〉。粗指条状物横截面大，玻璃的长短要用长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE 