INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92891, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "经济学家是专门研究钱怎么赚、怎么花的人。", "primary_collocate": null, "pronunciation": "jīng jì xué jiā", "ipa": "tɕiŋ˥ tɕi˥˩ ɕɥe˧˥ tɕja˥", "syllable_count": 4, "sentences": [{"text": "经济学家专门研究人们怎么赚钱、怎么花钱。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想长大以后当经济学家。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学家告诉我们，买东西前要先想想价格。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学了四年经济，现在是一名经济学家。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学家说，存钱比乱花钱好。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位经济学家在电视上教大家怎么省钱。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学家看着价格表，慢慢写下了数字。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题要问经济学家，他们最懂钱。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的妈妈是经济学家，常常跟他讲钱的事。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学家发现，很多人一发工资就买东西。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "經濟學家", "label": "繁体"}], "register": "中性", "sense_fingerprint": "专门研究赚钱与花钱的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3f55f56-4259-4abb-912d-1e43b9d9f8b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92891, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经济学家", "is_correct": true, "explanation": "正确：经济学家专门研究赚钱和花钱，符合句意。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手以唱歌为业，不研究人们怎么赚钱、怎么花钱。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能进行研究。"}, {"text": "胖子", "is_correct": false, "explanation": "体貌：“胖子”描述身材，不指职业，无法“专门研究”。"}], "explanations": {"经济学家": "正确：经济学家专门研究赚钱和花钱，符合句意。", "歌手": "语义：歌手以唱歌为业，不研究人们怎么赚钱、怎么花钱。", "桌子": "语义：桌子是家具，不能进行研究。", "胖子": "体貌：“胖子”描述身材，不指职业，无法“专门研究”。"}, "sentence_index": 0, "correct_answer": "经济学家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大学学的是经济学家。", "explanation": "这里应该用〈经济学〉。“学的是”后接学科名称，经济学家指人。"}, {"text": "他是一名经济学家，每天在医院给病人看病。", "explanation": "这里应该用〈医生〉。在医院给病人看病是医生的工作，经济学家研究经济，不能这样用。"}, {"text": "她是一名经济学家，每天在法庭上为客户辩护。", "explanation": "这里应该用〈律师〉。在法庭上为客户辩护是律师的工作，经济学家研究经济，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92891, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经济学家", "is_correct": true, "explanation": "正确：经济学家能够看价格表、写数字，符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不能看价格表、写数字。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠是动物，不能看价格表、写下数字。"}, {"text": "瞎子", "is_correct": false, "explanation": "体貌：“瞎子”指视力障碍，与“看着价格表”相矛盾。"}], "explanations": {"经济学家": "正确：经济学家能够看价格表、写数字，符合句意。", "厨房": "语义：厨房是场所，不能看价格表、写数字。", "老鼠": "语义：老鼠是动物，不能看价格表、写下数字。", "瞎子": "体貌：“瞎子”指视力障碍，与“看着价格表”相矛盾。"}, "sentence_index": 6, "correct_answer": "经济学家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一名经济学家，每天在公交车上负责售票。", "explanation": "这里应该用〈售票员〉。在公交车上售票是售票员的工作，经济学家研究经济，不能这样用。"}, {"text": "我的专业是经济学家，将来想进银行。", "explanation": "这里应该用〈经济学〉。“专业是”后接学科名称，“经济学家”指人，学科要用“经济学”。"}, {"text": "这位经济学家每天在餐厅做菜。", "explanation": "这里应该用〈厨师〉。在餐厅做菜是厨师的工作，经济学家研究经济，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92891, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的理想是成为一经济学家。", "corrected_sentence": "他的理想是成为一名经济学家。", "error_description": "量词“名”缺失，“一经济学家”应为“一名经济学家”。“经济学家”指人，数词后要加量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92891, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的父亲以前当过一只经济学家。", "corrected_sentence": "他的父亲以前当过一名经济学家。", "error_description": "量词错误：“经济学家”指人，量词应用“名”或“位”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
