INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "研究经济现象及其规律的专家。", "primary_collocate": null, "pronunciation": "jīng jì xué jiā", "ipa": "tɕiŋ˥ tɕi˥˩ ɕɥe˧˥ tɕja˥", "syllable_count": 4, "sentences": [{"text": "这位经济学家研究了二十年经济问题。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学家说，明年的物价可能会上涨。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位有名的经济学家，常在电视上讲话。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学家写了一本关于市场的书。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位经济学家在大学里教过经济课。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学家们正在开会，讨论国家的经济。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的爸爸是经济学家，每天都看数据。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学家认为，利率下降会让人多花钱。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸请了一位经济学家分析今年的经济。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位经济学家去过很多国家做研究。", "target_word": "经济学家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "經濟學家", "label": "繁体"}], "register": "中性", "sense_fingerprint": "研究经济现象与规律的专业人士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3f55f56-4259-4abb-912d-1e43b9d9f8b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经济学家", "is_correct": true, "explanation": "正确：经济学家是研究经济现象的专家，符合“研究了二十年经济问题”的语境。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师以做饭为业，不研究经济问题，与句中的研究内容不符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能修饰“石头”。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机以驾驶为业，不研究经济问题，句子不通。"}], "explanations": {"经济学家": "正确：经济学家是研究经济现象的专家，符合“研究了二十年经济问题”的语境。", "厨师": "语义：厨师以做饭为业，不研究经济问题，与句中的研究内容不符。", "石头": "搭配：量词“位”只用于人，不能修饰“石头”。", "司机": "语义：司机以驾驶为业，不研究经济问题，句子不通。"}, "sentence_index": 0, "correct_answer": "经济学家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大学学的专业是经济学家。", "explanation": "这里应该用〈经济学〉。经济学家指研究经济的人，专业名称要用“经济学”。"}, {"text": "这位经济学家给病人看了二十年病。", "explanation": "这里应该用〈医生〉。给病人看病是医生的工作，经济学家研究经济，不能这样用。"}, {"text": "这位经济学家帮客户打了一场官司。", "explanation": "这里应该用〈律师〉。打官司是律师的工作，经济学家研究经济，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经济学家", "is_correct": true, "explanation": "正确：经济学家的职业与“每天都看数据”相符，符合句意。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：“我的爸爸”指人，不能是小狗。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物体，不能作为爸爸的身份。"}, {"text": "蜡烛", "is_correct": false, "explanation": "语义：蜡烛是物品，不能作为爸爸的身份。"}], "explanations": {"经济学家": "正确：经济学家的职业与“每天都看数据”相符，符合句意。", "小狗": "语义：“我的爸爸”指人，不能是小狗。", "窗户": "语义：窗户是物体，不能作为爸爸的身份。", "蜡烛": "语义：蜡烛是物品，不能作为爸爸的身份。"}, "sentence_index": 6, "correct_answer": "经济学家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一位经济学家，每天在工地上搬砖。", "explanation": "这里应该用〈工人〉。在工地上搬砖是工人的工作，经济学家研究经济，不能这样用。"}, {"text": "这位同学学的是经济学家，很想进银行工作。", "explanation": "这里应该用〈经济学〉。“学的是”后接学科名称，“经济学家”指人，学科要用“经济学”。"}, {"text": "这位经济学家每天在路口指挥交通。", "explanation": "这里应该用〈警察〉。在路口指挥交通是警察的工作，经济学家研究经济，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两经济学家常在报纸上写文章。", "corrected_sentence": "两位经济学家常在报纸上写文章。", "error_description": "“两经济学家”缺少量词，应为“两位经济学家”。“经济学家”指人，数量词后要加“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只经济学家去过很多城市调查物价。", "corrected_sentence": "这位经济学家去过很多城市调查物价。", "error_description": "量词错误：“经济学家”指人，量词应用“位”或“名”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
