INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92894, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92894, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "靠近国界的地区。", "primary_collocate": null, "pronunciation": "biān jìng", "ipa": "pjɛn˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他在边境地区当了二十年老师。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边境的冬天又长又冷。", "target_word": "边境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个边境小镇很安静。", "target_word": "边境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府给边境的学校送去了新书。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边境地区的人常常去对面买东西。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生每年去边境给农民看病。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边境的山上住着很多少数民族。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人日夜守卫边境，保护国家安全。", "target_word": "边境", "complexity_tier": "T3", "furigana": "jūn rén rì yè shǒu wèi biān jìng, bǎo hù guó jiā ān quán。", "sentence_source": "generated"}, {"text": "边境的路不好走，车开得很慢。", "target_word": "边境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近几年，边境的生活变好了。", "target_word": "边境", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "靠近国界的一片地区，强调地区的生活、环境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f97b0b77-31da-4084-a328-b98e8987af04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是室内空间，不能作为一个“地区”，句子不成立。"}, {"text": "边境", "is_correct": true, "explanation": "“边境”指靠近国界的地区，“他在边境地区当了二十年老师”符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是地区，人不能在天空里当老师，与句意矛盾。"}, {"text": "卧室", "is_correct": false, "explanation": "搭配：“地区”一般不与“卧室”搭配，“卧室地区”不成词组。"}], "explanations": {"厨房": "语义：“厨房”是室内空间，不能作为一个“地区”，句子不成立。", "边境": "“边境”指靠近国界的地区，“他在边境地区当了二十年老师”符合句意。", "天空": "语义：“天空”不是地区，人不能在天空里当老师，与句意矛盾。", "卧室": "搭配：“地区”一般不与“卧室”搭配，“卧室地区”不成词组。"}, "sentence_index": 0, "correct_answer": "边境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的边境有很多高楼。", "explanation": "这里应该用〈边缘〉。“边境”指两国交界的地区，城市的外围不说“边境”。"}, {"text": "他的汉语已经到了很高的边境。", "explanation": "这里应该用〈水平〉。“边境”不能表示能力达到的程度。"}, {"text": "我在一颗边境住了二十年。", "explanation": "量词“颗”用于圆形的小东西，不能用来修饰“边境”，这里的量词搭配错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "语义：海洋中没有“山上”，“海洋的山上住着很多少数民族”与常识矛盾。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是室内空间，不能有“山上”，句意不成立。"}, {"text": "边境", "is_correct": true, "explanation": "“边境”指靠近国界的地区，“边境的山上住着很多少数民族”符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”不能与“的山上”搭配，句子的修饰关系不成立。"}], "explanations": {"海洋": "语义：海洋中没有“山上”，“海洋的山上住着很多少数民族”与常识矛盾。", "教室": "语义：“教室”是室内空间，不能有“山上”，句意不成立。", "边境": "“边境”指靠近国界的地区，“边境的山上住着很多少数民族”符合句意。", "冰箱": "搭配：“冰箱”不能与“的山上”搭配，句子的修饰关系不成立。"}, "sentence_index": 6, "correct_answer": "边境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块木板的边境刮破了我的手。", "explanation": "这里应该用〈边沿〉。“边境”指靠近国界的地区，木板的边沿不能说“边境”。"}, {"text": "他把两家的边境划得很清楚。", "explanation": "这里应该用〈界限〉。“边境”指地区，不指抽象的界限。"}, {"text": "这个小区的边境很安静。", "explanation": "这里应该用〈外围〉。“边境”指靠近国界的地区，小区的外围不说“边境”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在一颗边境待了一个月。", "corrected_sentence": "我们在一带边境待了一个月。", "error_description": "量词错误：“边境”指一片地区，应说“一带边境”，“颗”多用于圆形的小东西，不能用来修饰“边境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每年都去边境去采访。", "corrected_sentence": "我们每年都去边境采访。", "error_description": "多余的“去”：“去边境”作状语后，动词“采访”前面不能再加“去”，应说“去边境采访”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
