INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92906, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示共同、一起。", "primary_collocate": null, "pronunciation": "yì tóng", "ipa": "i˥˩ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "两国领导人一同出席了会议。", "target_word": "一同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师和学生一同参加了比赛。", "target_word": "一同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全家人一同庆祝他的生日。", "target_word": "一同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一同迎接新的一年。", "target_word": "一同", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "同事们一同讨论了这个计划。", "target_word": "一同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他与朋友一同创办了公司。", "target_word": "一同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请大家一同欢迎新同学。", "target_word": "一同", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "村民们一同修好了那座桥。", "target_word": "一同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他和妻子一同回国。", "target_word": "一同", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家一同为她鼓掌。", "target_word": "一同", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一同：书面色彩的副词，表示共同参加、共同进行，多用于会议、庆祝、创办等较正式的场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf42e3e0-3aa5-4213-89fd-9bc9b80dff5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92906, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一同", "is_correct": true, "explanation": "正确。「一同」指几个人一起做同一件事，读 yì tóng。"}, {"text": "一通", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）声调不同，「一通」指一阵或一番，意思与「一同」不符。"}, {"text": "一桶", "is_correct": false, "explanation": "tóng（第二声）与 tǒng（第三声）声调不同，「一桶」指一个桶的量，意思不同。"}, {"text": "一头", "is_correct": false, "explanation": "tóng 与 tóu 韵母不同（-ong 与 -ou），「一头」表示一下子、径直，意思不同。"}], "explanations": {"一同": "正确。「一同」指几个人一起做同一件事，读 yì tóng。", "一通": "tóng（第二声）与 tōng（第一声）声调不同，「一通」指一阵或一番，意思与「一同」不符。", "一桶": "tóng（第二声）与 tǒng（第三声）声调不同，「一桶」指一个桶的量，意思不同。", "一头": "tóng 与 tóu 韵母不同（-ong 与 -ou），「一头」表示一下子、径直，意思不同。"}, "sentence_index": null, "correct_answer": "一同"}, "level_3": {"options": [{"text": "一同", "is_correct": true, "explanation": "正确。「一同」表示几位领导人一起出席，与会议语境相符。"}, {"text": "很", "is_correct": false, "explanation": "搭配：「很」修饰形容词，不能直接放在动作动词「出席」前。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：「非常」修饰形容词或心理动词，不能修饰「出席」这样的动作。"}, {"text": "独自", "is_correct": false, "explanation": "语义：「独自」指一个人去做，与主语「两国领导人」的复数不符。"}], "explanations": {"一同": "正确。「一同」表示几位领导人一起出席，与会议语境相符。", "很": "搭配：「很」修饰形容词，不能直接放在动作动词「出席」前。", "非常": "搭配：「非常」修饰形容词或心理动词，不能修饰「出席」这样的动作。", "独自": "语义：「独自」指一个人去做，与主语「两国领导人」的复数不符。"}, "sentence_index": 0, "correct_answer": "一同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她一同独自走进了房间。", "explanation": "这里应该用「单独」。「一同」指几个人一起做，与「独自」矛盾。"}, {"text": "他一同出席了这次会议。", "explanation": "这里应该用「单独」。「一同」要求几个人一起做，主语只有「他」一人时不能用，应说「他单独出席了这次会议」。"}, {"text": "我们一同完成了这份报告，但只有他一个人在做。", "explanation": "「一同」要求多人共同做，与后句「只有他一个人在做」矛盾；若想表示他一人完成，应说「他单独完成了这份报告」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一同", "is_correct": true, "explanation": "正确。「一同」表示大家共同做「欢迎」这件事，与祈使句相符。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：「曾经」指过去的事，与表示请求的「请」所表达的当下或将来不符。"}, {"text": "已经", "is_correct": false, "explanation": "语义：「已经」表示动作已完成，与「请大家……」的祈使语气冲突。"}, {"text": "亲手", "is_correct": false, "explanation": "搭配：「亲手」强调用手做，不能修饰「欢迎」这类言语或情感上的动作。"}], "explanations": {"一同": "正确。「一同」表示大家共同做「欢迎」这件事，与祈使句相符。", "曾经": "语义：「曾经」指过去的事，与表示请求的「请」所表达的当下或将来不符。", "已经": "语义：「已经」表示动作已完成，与「请大家……」的祈使语气冲突。", "亲手": "搭配：「亲手」强调用手做，不能修饰「欢迎」这类言语或情感上的动作。"}, "sentence_index": 6, "correct_answer": "一同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家一同分别为她鼓掌。", "explanation": "这里应该用「各自」。「一同」表示共同，与「分别」矛盾。"}, {"text": "我们一同各自去了超市。", "explanation": "这里应该用「分别」。「一同」指共同做，与「各自」矛盾。"}, {"text": "他们俩一同分开站着，各自朝不同的方向。", "explanation": "这里应该用「分别」。「一同」指共同做，与「分开站着」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国领导人一同一起访问了日本。", "corrected_sentence": "两国领导人一同访问了日本。", "error_description": "错误在于「一同」和「一起」意思相同，句中叠用了。应只用其一，正确说法是「两国领导人一同访问了日本」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国代表一同了参加谈判。", "corrected_sentence": "两国代表一同参加谈判。", "error_description": "错误在于「了」放在了「一同」后面。「一同」是副词，后面不能直接加「了」，「了」应放在动词之后，正确说法是「两国代表一同参加谈判」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
