INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92909, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "主流是最多人选的、最主要的那一种。", "primary_collocate": null, "pronunciation": "zhǔ liú", "ipa": "ʈʂu˨˩˦ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "现在手机的主流是大屏幕的。", "target_word": "主流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种音乐不是主流，听的人不多。", "target_word": "主流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个城市，骑自行车上班已经不是主流了。", "target_word": "主流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电动汽车慢慢成了市场的主流。", "target_word": "主流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法和主流不一样。", "target_word": "主流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人中的主流看法是工作要快乐。", "target_word": "主流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们公司，用电脑办公是主流。", "target_word": "主流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢的歌手都不是主流。", "target_word": "主流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店卖的主流是三十元左右的衣服。", "target_word": "主流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买手机时，大家都选主流的。", "target_word": "主流", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "多数人选择的最主要的一种做法、款式或观点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f97b0b77-31da-4084-a328-b98e8987af04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92909, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主流", "is_correct": true, "explanation": "正确：主流指多数人选的最主要款式，“现在手机的主流是大屏幕的”符合语境。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史指过去的事情，与句中的“现在”冲突。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能说“是大屏幕的”，搭配不当。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”一般说“是……色的”，不能用“大屏幕的”来描述。"}], "explanations": {"主流": "正确：主流指多数人选的最主要款式，“现在手机的主流是大屏幕的”符合语境。", "历史": "语义：历史指过去的事情，与句中的“现在”冲突。", "价格": "搭配：“价格”不能说“是大屏幕的”，搭配不当。", "颜色": "搭配：“颜色”一般说“是……色的”，不能用“大屏幕的”来描述。"}, "sentence_index": 0, "correct_answer": "主流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支球队的主流是两名新队员。", "explanation": "这里应该用〈主力〉。主力指队伍中起主要作用的人，主流不用来指人。"}, {"text": "这种主流的手机，买的人很少。", "explanation": "这里应该用〈冷门〉。主流指最多人选的，买的人很少时不能说主流；少人选的应说“冷门”。"}, {"text": "这部电影的主流是一个年轻女孩。", "explanation": "这里应该用〈主角〉。主角指故事中的主要人物，主流不指人物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92909, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主流", "is_correct": true, "explanation": "正确：主流指多数人选的办公方式，“用电脑办公是主流”符合语境。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事指叙述的内容，与办公方式无关。"}, {"text": "人数", "is_correct": false, "explanation": "语义：人数指人的数目，不能说明办公方式。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”不能作“办公”的谓语，“是工资”搭配不当。"}], "explanations": {"主流": "正确：主流指多数人选的办公方式，“用电脑办公是主流”符合语境。", "故事": "语义：故事指叙述的内容，与办公方式无关。", "人数": "语义：人数指人的数目，不能说明办公方式。", "工资": "搭配：“工资”不能作“办公”的谓语，“是工资”搭配不当。"}, "sentence_index": 6, "correct_answer": "主流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议的主流是王老师。", "explanation": "这里应该用〈主席〉。主席指会议的领导者，主流不用来指人。"}, {"text": "这首歌很主流，听的人没几个。", "explanation": "这里应该用〈冷门〉。主流指最多人选的，听的人没几个时不能说主流；少人听的应说“冷门”。"}, {"text": "这只狗的主流很温柔。", "explanation": "这里应该用〈性格〉。主流指最多人选的一种，不用来形容狗的脾气；说狗的脾气应用“性格”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "直播购物已经成了主流着。", "corrected_sentence": "直播购物已经成了主流。", "error_description": "错误：“主流”后面不能加“着”。“成了主流”表示变化的结果，“着”表示状态持续，二者不搭配，正确是“成了主流”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种做法在年轻人中已经成了的主流。", "corrected_sentence": "这种做法在年轻人中已经成了主流。", "error_description": "错误：“成了”与“主流”之间多了“的”，“的”不能直接接在动词后面。正确是“成了主流”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
