INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92913, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "书面语助词，用在形容词后，表示程度达到极点。", "primary_collocate": null, "pronunciation": "zhī zhì", "ipa": "ʈʂɻ̩˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "见到您，我高兴之至。", "target_word": "之至", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次旅行辛苦之至，大家都累坏了。", "target_word": "之至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收到您的礼物，我感动之至。", "target_word": "之至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对我的态度冷淡之至。", "target_word": "之至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事麻烦之至，我不想再管了。", "target_word": "之至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的风景美丽之至。", "target_word": "之至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里脏乱之至，没法住人。", "target_word": "之至", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得知他平安回来，全家欣慰之至。", "target_word": "之至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的天气出门，实在是难受之至。", "target_word": "之至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您能来参加，我们光荣之至。", "target_word": "之至", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "放在形容词后面，表示非常非常，语气正式，多用于表达感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f97b0b77-31da-4084-a328-b98e8987af04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92913, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "之至", "is_correct": true, "explanation": "之至（zhī zhì）是书面语助词，附在形容词后面，表示程度达到极点。这是本题的正确答案。"}, {"text": "直至", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，直至的意思是一直到某个时间或地点。"}, {"text": "资质", "is_correct": false, "explanation": "zī 与 zhī 声母不同（z 与 zh），资质的意思是天资或素质。"}, {"text": "机制", "is_correct": false, "explanation": "jī 与 zhī 声母不同（j 与 zh），机制的意思是事物内部的工作方式。"}, {"text": "芝士", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），芝士的意思是奶酪。"}], "explanations": {"之至": "之至（zhī zhì）是书面语助词，附在形容词后面，表示程度达到极点。这是本题的正确答案。", "直至": "zhí（第二声）与 zhī（第一声）声调不同，直至的意思是一直到某个时间或地点。", "资质": "zī 与 zhī 声母不同（z 与 zh），资质的意思是天资或素质。", "机制": "jī 与 zhī 声母不同（j 与 zh），机制的意思是事物内部的工作方式。", "芝士": "shì 与 zhì 声母不同（sh 与 zh），芝士的意思是奶酪。"}, "sentence_index": null, "correct_answer": "之至"}, "level_3": {"options": [{"text": "的", "is_correct": false, "explanation": "语义：“的”标示定语，后面没有中心名词，“高兴的”句末不成立，表达不了程度。"}, {"text": "之至", "is_correct": true, "explanation": "“之至”附在“高兴”后面，表示程度达到极点，与句意相合。"}, {"text": "地", "is_correct": false, "explanation": "配价：“地”引出修饰动词的状语，“高兴地”后面没有动词，句子不成立。"}, {"text": "得", "is_correct": false, "explanation": "搭配：“得”引出补语，“高兴得”后面要接程度或结果，句末不成立。"}], "explanations": {"的": "语义：“的”标示定语，后面没有中心名词，“高兴的”句末不成立，表达不了程度。", "之至": "“之至”附在“高兴”后面，表示程度达到极点，与句意相合。", "地": "配价：“地”引出修饰动词的状语，“高兴地”后面没有动词，句子不成立。", "得": "搭配：“得”引出补语，“高兴得”后面要接程度或结果，句末不成立。"}, "sentence_index": 0, "correct_answer": "之至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影有点好看之至。", "explanation": "“之至”表示程度达到极点，与“有点”所表示的轻微程度互相矛盾，不能这样搭配。"}, {"text": "他一点儿也不着急之至。", "explanation": "“之至”表示程度达到极点，与“一点儿也不”的否定程度互相矛盾，这里不能用。"}, {"text": "这片海水蓝之至。", "explanation": "“之至”只接表示感受或评价的形容词，“蓝”描述颜色，不能用“之至”；删去“之至”，说“这片海水蔚蓝”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92913, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "之至", "is_correct": true, "explanation": "之至（zhī zhì）是书面语助词，附在形容词后面，表示程度达到极点。这是本题的正确答案。"}, {"text": "低至", "is_correct": false, "explanation": "dī 与 zhī 声母不同（d 与 zh），低至的意思是低到某个程度，如“低至五折”。"}, {"text": "机智", "is_correct": false, "explanation": "jī 与 zhī 声母不同（j 与 zh），机智的意思是反应快、善于应变。"}, {"text": "失智", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh 与 zh），失智指记忆、判断等智力功能下降。"}, {"text": "基质", "is_correct": false, "explanation": "jī 与 zhī 声母不同（j 与 zh），基质指某些物质赖以存在或发生作用的基础物质。"}], "explanations": {"之至": "之至（zhī zhì）是书面语助词，附在形容词后面，表示程度达到极点。这是本题的正确答案。", "低至": "dī 与 zhī 声母不同（d 与 zh），低至的意思是低到某个程度，如“低至五折”。", "机智": "jī 与 zhī 声母不同（j 与 zh），机智的意思是反应快、善于应变。", "失智": "shī 与 zhī 声母不同（sh 与 zh），失智指记忆、判断等智力功能下降。", "基质": "jī 与 zhī 声母不同（j 与 zh），基质指某些物质赖以存在或发生作用的基础物质。"}, "sentence_index": null, "correct_answer": "之至"}, "level_3": {"options": [{"text": "吗", "is_correct": false, "explanation": "语义：“吗”用于疑问句，这里是陈述，“脏乱吗”不能表示程度极高。"}, {"text": "之至", "is_correct": true, "explanation": "“之至”附在“脏乱”后面，表示程度达到极点，与句意相合。"}, {"text": "而", "is_correct": false, "explanation": "连词：“而”要连接并列的成分，“脏乱而”后面没有可连接的成分，句子不成立。"}, {"text": "地", "is_correct": false, "explanation": "配价：“地”引出修饰动词的状语，“脏乱地”后面没有动词，句子不成立。"}], "explanations": {"吗": "语义：“吗”用于疑问句，这里是陈述，“脏乱吗”不能表示程度极高。", "之至": "“之至”附在“脏乱”后面，表示程度达到极点，与句意相合。", "而": "连词：“而”要连接并列的成分，“脏乱而”后面没有可连接的成分，句子不成立。", "地": "配价：“地”引出修饰动词的状语，“脏乱地”后面没有动词，句子不成立。"}, "sentence_index": 6, "correct_answer": "之至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议比上次更冷清之至。", "explanation": "“之至”表示程度达到极点，与“比……更”的比较义互相矛盾，这里不能这样用。"}, {"text": "我对这件事一点儿也不在意之至。", "explanation": "“之至”表示程度达到极点，与“一点儿也不”的否定程度互相矛盾，这里不能用。"}, {"text": "这次旅行比去年更糟之至。", "explanation": "“之至”已表示程度达到极点，与“比……更”的比较义重复冲突，这里不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92913, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场雨下了三天，大家都烦闷的之至。", "corrected_sentence": "这场雨下了三天，大家都烦闷之至。", "error_description": "多余的“的”：“之至”直接附在形容词后面，前面不能加“的”，应说“烦闷之至”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
