INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92918, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92918, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示在一定范围内做到最大限度。", "primary_collocate": null, "pronunciation": "jǐn liàng", "ipa": "tɕin˨˩ ljaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "请你尽量早一点儿来。", "target_word": "尽量", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天有考试，今晚尽量早点睡。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他尽量不让妈妈知道这件事。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你说话时尽量慢一点，我听不懂。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我会尽量帮你，但是不能保证。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说这几天尽量别吃太辣的东西。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到了图书馆，请尽量小声说话。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上堵车，所以我们尽量早点出门。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师要我们尽量用汉语回答问题。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气太热，大家尽量待在家里。", "target_word": "尽量", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "副词：在能力或条件范围内尽可能做到，放在动词前，读jǐnliàng", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbe7cc2-5e9e-40b7-aa24-1c71bcda64ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尽量", "is_correct": true, "explanation": "正确：「尽量」表示在能力范围内做到最大限度，与「请你……早一点儿来」的请求相符。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：「竟然」表示出乎意料，与请人早点来的语境矛盾。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：「已经」表示动作已经完成，与祈使句里尚未发生的「来」不符。"}, {"text": "突然", "is_correct": false, "explanation": "语义：「突然」表示事情忽然发生，与有计划地请人早点来不合。"}], "explanations": {"尽量": "正确：「尽量」表示在能力范围内做到最大限度，与「请你……早一点儿来」的请求相符。", "竟然": "语义：「竟然」表示出乎意料，与请人早点来的语境矛盾。", "已经": "体貌：「已经」表示动作已经完成，与祈使句里尚未发生的「来」不符。", "突然": "语义：「突然」表示事情忽然发生，与有计划地请人早点来不合。"}, "sentence_index": 0, "correct_answer": "尽量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子尽量大，所以我们很喜欢它。", "explanation": "这里应该用〈很〉。「很大」只说屋子的大小，「尽量」只表示人尽力做到最多，不能用来形容屋子的性质。"}, {"text": "他尽量摔倒了，所以膝盖受伤了。", "explanation": "这里应该用〈不小心〉。「不小心」表示无意中发生；「尽量」表示人尽力去做，摔倒不是可以尽力去做的事。"}, {"text": "他尽量比我大三岁，所以他是哥哥。", "explanation": "这里应该用〈正好〉。「他正好比我大三岁」是自然的说法；「尽量」只表示尽力做到最多，不能用于已经确定的年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尽量", "is_correct": true, "explanation": "正确：「尽量」表示尽力做到最好，与「请……小声说话」的要求相符。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：「曾经」表示过去有过的经历，与祈使句的要求不合。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：「正在」表示动作正在进行，不能与祈使句「请……」搭配。"}, {"text": "果然", "is_correct": false, "explanation": "语义：「果然」表示与预期相符，此处没有任何预期，句意不通。"}], "explanations": {"尽量": "正确：「尽量」表示尽力做到最好，与「请……小声说话」的要求相符。", "曾经": "体貌：「曾经」表示过去有过的经历，与祈使句的要求不合。", "正在": "体貌：「正在」表示动作正在进行，不能与祈使句「请……」搭配。", "果然": "语义：「果然」表示与预期相符，此处没有任何预期，句意不通。"}, "sentence_index": 6, "correct_answer": "尽量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服尽量贵，但我还是买了它。", "explanation": "这里应该用〈挺〉。「挺贵」描述事物的性质；「尽量」只修饰人能尽力去做的事，不能用来形容衣服的价格。"}, {"text": "明天要去郊游，天气尽量晴一点吧。", "explanation": "这里应该用〈希望〉。「尽量」只修饰人能尽力做到的事，天气晴不晴不能靠努力决定；表示期盼要用「希望」。"}, {"text": "他昨天尽量生病了，所以没来上课。", "explanation": "这里应该用〈突然〉。「突然」表示事情忽然发生；「尽量」表示人尽力去做，生病不是可以尽力去做的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末的会议很重要，大家尽量的早点到。", "corrected_sentence": "周末的会议很重要，大家尽量早点到。", "error_description": "「尽量」是副词，修饰动词「到」时后面不能加「的」，应直接写「尽量早点到」。这里误加了「的」，多余。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场比赛很重要，选手们尽量了准时到达。", "corrected_sentence": "这场比赛很重要，选手们尽量准时到达。", "error_description": "「了」不能直接放在副词「尽量」后面，它应该放在动词之后。这里「了」被放在「尽量」后面，属于体标用错位置。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
