INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92923, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92923, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "评为是大家看了比一比，选出来当作某个样子。", "primary_collocate": null, "pronunciation": "píng wéi", "ipa": "pʰiŋ˧˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "大家都把小明评为班里最爱笑的人。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们把她评为我们班最热心的人。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们看完照片，把这张评为最美的一张。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家投票后，把小王评为最会做饭的人。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都把这家小店评为全城最好吃的店。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们把老张评为我们楼里最好的人。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们尝了三种蛋糕，把妈妈做的评为第一。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家看了几张画，把小红的评为最好看的。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把这首歌评为今年最好听的歌。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比完以后，大家把他评为最有礼貌的学生。", "target_word": "评为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "评为了", "label": "体标（了）"}, {"form": "评为过", "label": "体标（过）"}, {"form": "被评为", "label": "被动"}], "register": "中性", "sense_fingerprint": "大家比较之后，选出某人或某物，把他（它）当作某种样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e983dcc6-3418-42fd-ac27-a2db7eba3cd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92923, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "评为", "is_correct": true, "explanation": "正确答案：评为（píng wéi）。"}, {"text": "评委", "is_correct": false, "explanation": "wěi（第三声）与 wéi（第二声）声调不同，意思是评审人员。"}, {"text": "行为", "is_correct": false, "explanation": "xíng 与 píng 声母不同（x 与 p），意思是行动、举止。"}, {"text": "名为", "is_correct": false, "explanation": "míng 与 píng 声母不同（m 与 p），意思是名义上是。"}], "explanations": {"评为": "正确答案：评为（píng wéi）。", "评委": "wěi（第三声）与 wéi（第二声）声调不同，意思是评审人员。", "行为": "xíng 与 píng 声母不同（x 与 p），意思是行动、举止。", "名为": "míng 与 píng 声母不同（m 与 p），意思是名义上是。"}, "sentence_index": null, "correct_answer": "评为"}, "level_3": {"options": [{"text": "评为", "is_correct": true, "explanation": "正确答案：评为，指大家比较后选出某人，当作某种样子。"}, {"text": "判为", "is_correct": false, "explanation": "语义：“判为”指依据证据或规定作出结论，不用于评选人物。"}, {"text": "装扮为", "is_correct": false, "explanation": "体貌：“装扮为”指打扮成某种角色的外形，与大家的评选无关。"}, {"text": "任为", "is_correct": false, "explanation": "搭配：“任为”后只接职务，如“任为班长”，不能接“班里最爱笑的人”。"}], "explanations": {"评为": "正确答案：评为，指大家比较后选出某人，当作某种样子。", "判为": "语义：“判为”指依据证据或规定作出结论，不用于评选人物。", "装扮为": "体貌：“装扮为”指打扮成某种角色的外形，与大家的评选无关。", "任为": "搭配：“任为”后只接职务，如“任为班长”，不能接“班里最爱笑的人”。"}, "sentence_index": 0, "correct_answer": "评为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警方把他评为嫌疑人。", "explanation": "这里应该用〈认定〉。评为指经评议、比较后确定称号或等级，嫌疑人要由司法机关依证据认定，不用评为。"}, {"text": "他把这只小狗评为小白。", "explanation": "这里应该用〈命名〉。评为指经评议确定称号或等级，给小狗取名要用命名。"}, {"text": "他把失败评为人生的财富。", "explanation": "这里应该用〈视为〉。视为表示看作、当成，失败不是经评议确定的称号或等级，不能用评为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92923, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "评为", "is_correct": true, "explanation": "正确答案：评为，指比较后确定名次。"}, {"text": "考", "is_correct": false, "explanation": "语义：“考”指参加考试，与“妈妈做的蛋糕”不搭。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能表示名次，“吃第一”不成立。"}, {"text": "拍", "is_correct": false, "explanation": "语义：“拍”指拍照或拍打，不能表示名次。"}], "explanations": {"评为": "正确答案：评为，指比较后确定名次。", "考": "语义：“考”指参加考试，与“妈妈做的蛋糕”不搭。", "吃": "搭配：“吃”不能表示名次，“吃第一”不成立。", "拍": "语义：“拍”指拍照或拍打，不能表示名次。"}, "sentence_index": 6, "correct_answer": "评为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "裁判把他评为犯规。", "explanation": "这里应该用〈判定〉。判定指依规则作出裁决，评为指比较后选出，不用于违规认定。"}, {"text": "他把我评为朋友。", "explanation": "这里应该用〈认作〉。认作指认定为某种关系或身份，评为指比较后选出，不用于结交朋友。"}, {"text": "皇帝把他评为王。", "explanation": "这里应该用〈封〉。封指帝王授予爵位，评为指比较后选出，不用于授爵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92923, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "投票结束后，大家把她评为着最乐于助人的同学。", "corrected_sentence": "投票结束后，大家把她评为最乐于助人的同学。", "error_description": "体标错误：“评为”后不能加“着”，应去掉“着”，即“大家把她评为最乐于助人的同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92923, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比完以后，大家评为最守时的同学。", "corrected_sentence": "比完以后，大家把小华评为最守时的同学。", "error_description": "缺宾语：“评为”前要说明被评的人，应加“把小华”，即“大家把小华评为最守时的同学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
