INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92928, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表明事物已经发生或将要发生的隐约现象。", "primary_collocate": null, "pronunciation": "jì xiàng", "ipa": "tɕi˥˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这些迹象表明，他昨晚没有回家。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济出现了好转的迹象。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说病人没有恢复的迹象。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在房间里发现了有人来过的迹象。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的脚印是有人进来的迹象。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房价有下降的迹象。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这些迹象看，他们早就认识。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脸上没有一点高兴的迹象。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市似乎有发展的迹象。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说公司没有变好的迹象。", "target_word": "迹象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "表明事物已经或将要发生的隐约现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30465e8-a764-427e-9db7-903b0f509c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92928, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "迹象", "is_correct": true, "explanation": "正确答案。迹象指表明事物已经发生或将要发生的隐约现象。"}, {"text": "气象", "is_correct": false, "explanation": "qì（第四声）与 jì（第四声）声母不同，j 与 q 相混。气象意思是天气和气候的状况。"}, {"text": "几项", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同。几项意思是几个项目。"}, {"text": "吉祥", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）、xiáng（第二声）与 xiàng（第四声）声调都不同。吉祥意思是吉利、好运。"}], "explanations": {"迹象": "正确答案。迹象指表明事物已经发生或将要发生的隐约现象。", "气象": "qì（第四声）与 jì（第四声）声母不同，j 与 q 相混。气象意思是天气和气候的状况。", "几项": "jǐ（第三声）与 jì（第四声）声调不同。几项意思是几个项目。", "吉祥": "jí（第二声）与 jì（第四声）、xiáng（第二声）与 xiàng（第四声）声调都不同。吉祥意思是吉利、好运。"}, "sentence_index": null, "correct_answer": "迹象"}, "level_3": {"options": [{"text": "迹象", "is_correct": true, "explanation": "正确答案。“这些迹象表明”指这些隐约的现象说明了事情。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：“大楼”是建筑，不能用来表明他的行踪。"}, {"text": "口味", "is_correct": false, "explanation": "语义：“口味”指对食物的喜好，不能“表明”他昨晚的行踪。"}, {"text": "体型", "is_correct": false, "explanation": "体貌：“体型”说身形，不能作“表明”的主语。"}], "explanations": {"迹象": "正确答案。“这些迹象表明”指这些隐约的现象说明了事情。", "大楼": "语义：“大楼”是建筑，不能用来表明他的行踪。", "口味": "语义：“口味”指对食物的喜好，不能“表明”他昨晚的行踪。", "体型": "体貌：“体型”说身形，不能作“表明”的主语。"}, "sentence_index": 0, "correct_answer": "迹象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这锅菜的迹象很咸，你少放点盐吧。", "explanation": "这里应该用〈味道〉。“咸”说的是味道，迹象指表明事物已经或将要发生的隐约现象，不能用来形容味道。"}, {"text": "山顶的迹象美得让人说不出话。", "explanation": "这里应该用〈景象〉。景象指眼前看到的景色，“美得让人说不出话”说的是景色；迹象不指景色。"}, {"text": "他在老师心中的迹象很好。", "explanation": "这里应该用〈形象〉。“心中的形象”指别人对他的印象，要用形象；迹象指事情将要发生的征兆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迹象", "is_correct": true, "explanation": "正确答案。“从这些迹象看”指根据隐约的现象来推断。"}, {"text": "硬币", "is_correct": false, "explanation": "语义：“硬币”是钱币，不能作为推断的依据来“看”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”是嗅觉或味觉的对象，不能用来推断他们的关系。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”说身体的高矮，不能用来推断他们早就认识。"}], "explanations": {"迹象": "正确答案。“从这些迹象看”指根据隐约的现象来推断。", "硬币": "语义：“硬币”是钱币，不能作为推断的依据来“看”。", "味道": "语义：“味道”是嗅觉或味觉的对象，不能用来推断他们的关系。", "身高": "体貌：“身高”说身体的高矮，不能用来推断他们早就认识。"}, "sentence_index": 6, "correct_answer": "迹象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的迹象很安静，从不大声说话。", "explanation": "这里应该用〈性格〉。“很安静”“从不大声说话”说的是性格；迹象指表明事物发生的隐约现象，不能用来形容人。"}, {"text": "这一带的迹象一年四季都很潮湿。", "explanation": "这里应该用〈气候〉。气候指一个地区长期的天气状况，“一年四季很潮湿”说的是气候；迹象不指气候。"}, {"text": "湖边的迹象很美，我们坐了一下午。", "explanation": "这里应该用〈景色〉。景色指眼前的自然风景，“湖边很美”说的是风景；迹象不指风景。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口好像有一只刚下过雨的迹象。", "corrected_sentence": "门口好像有一种刚下过雨的迹象。", "error_description": "错误：“迹象”的量词用错，应该用“种”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司的生意有回升迹象。", "corrected_sentence": "公司的生意有回升的迹象。", "error_description": "错误：“回升”修饰名词“迹象”时要加“的”。错误形式是“回升迹象”，正确形式是“回升的迹象”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92935, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "面对", "is_correct": true, "explanation": "反义。逃避是躲开，面对是正视、直接应对，二者意思相反。"}, {"text": "完成", "is_correct": false, "explanation": "同为动词，但与逃避没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "同为动词，但与逃避没有反义关系，指悠闲地走路。"}, {"text": "购买", "is_correct": false, "explanation": "同为动词，但与逃避没有反义关系，指买东西。"}], "correct_answer": "面对", "explanations": {"面对": "反义。逃避是躲开，面对是正视、直接应对，二者意思相反。", "完成": "同为动词，但与逃避没有反义关系。", "散步": "同为动词，但与逃避没有反义关系，指悠闲地走路。", "购买": "同为动词，但与逃避没有反义关系，指买东西。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92935, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "面对", "is_correct": true, "explanation": "反义。逃避是躲开，面对是正视、直接应对，二者意思相反。"}, {"text": "阅读", "is_correct": false, "explanation": "同为动词，但与逃避没有反义关系，指看书报。"}, {"text": "修理", "is_correct": false, "explanation": "同为动词，但与逃避没有反义关系，指把坏的东西弄好。"}, {"text": "打扫", "is_correct": false, "explanation": "同为动词，但与逃避没有反义关系，指清除垃圾和灰尘。"}], "correct_answer": "面对", "explanations": {"面对": "反义。逃避是躲开，面对是正视、直接应对，二者意思相反。", "阅读": "同为动词，但与逃避没有反义关系，指看书报。", "修理": "同为动词，但与逃避没有反义关系，指把坏的东西弄好。", "打扫": "同为动词，但与逃避没有反义关系，指清除垃圾和灰尘。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92935, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "逃避是遇到不想做的事，就躲开不去面对。", "primary_collocate": null, "pronunciation": "táo bì", "ipa": "tʰɑʊ̯˧˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "他怕考试，所以逃避复习。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别总是逃避做家务。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟一听写作业就逃避。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直逃避和老板见面。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到难题，不要逃避。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在逃避给妈妈打电话。", "target_word": "逃避", "complexity_tier": "T3", "furigana": "tā yī zhí zài táo bì gěi mā ma dǎ diàn huà。", "sentence_source": "generated"}, {"text": "小明为了逃避洗碗，说自己头疼。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想再逃避了，今天就去说。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他逃避跟朋友见面，因为怕借钱。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥逃避工作，整天在家玩游戏。", "target_word": "逃避", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逃避了", "label": "体标"}, {"form": "逃避过", "label": "体标"}, {"form": "逃避着", "label": "体标"}], "register": "中性", "sense_fingerprint": "遇到不想做的具体事情就躲开不做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3f55f56-4259-4abb-912d-1e43b9d9f8b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92935, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "逃避", "is_correct": true, "explanation": "正确。逃避（táo bì）：遇到不想做的事就躲开不做。"}, {"text": "投币", "is_correct": false, "explanation": "投币（tóu bì）与逃避（táo bì）第一个音节韵母不同（ao 与 ou），意思是投入硬币。"}, {"text": "倒闭", "is_correct": false, "explanation": "倒闭（dǎo bì）第一个音节声母 d 与 t 不同，且声调为第三声，意思是企业停业破产。"}, {"text": "淘米", "is_correct": false, "explanation": "淘米（táo mǐ）第二个音节声母 m 与 b 不同，且声调为第三声，意思是用水洗米。"}, {"text": "逃逸", "is_correct": false, "explanation": "逃逸（táo yì）第二个音节少了声母 b，读 yì，意思是逃跑、溜走。"}], "explanations": {"逃避": "正确。逃避（táo bì）：遇到不想做的事就躲开不做。", "投币": "投币（tóu bì）与逃避（táo bì）第一个音节韵母不同（ao 与 ou），意思是投入硬币。", "倒闭": "倒闭（dǎo bì）第一个音节声母 d 与 t 不同，且声调为第三声，意思是企业停业破产。", "淘米": "淘米（táo mǐ）第二个音节声母 m 与 b 不同，且声调为第三声，意思是用水洗米。", "逃逸": "逃逸（táo yì）第二个音节少了声母 b，读 yì，意思是逃跑、溜走。"}, "sentence_index": null, "correct_answer": "逃避"}, "level_3": {"options": [{"text": "逃避", "is_correct": true, "explanation": "正确。“他怕考试，所以逃避复习”：因为怕考试而躲开复习，语义通顺。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”表示乐在其中，与“怕考试”的因果关系相矛盾，句子不通。"}, {"text": "迎接", "is_correct": false, "explanation": "搭配：“迎接”多接挑战、客人，不能说“迎接复习”。"}, {"text": "嘲笑", "is_correct": false, "explanation": "搭配：“嘲笑”接的是人或言行，“嘲笑复习”不成立，与“怕考试”的因果也不通，句子不通。"}], "explanations": {"逃避": "正确。“他怕考试，所以逃避复习”：因为怕考试而躲开复习，语义通顺。", "享受": "语义：“享受”表示乐在其中，与“怕考试”的因果关系相矛盾，句子不通。", "迎接": "搭配：“迎接”多接挑战、客人，不能说“迎接复习”。", "嘲笑": "搭配：“嘲笑”接的是人或言行，“嘲笑复习”不成立，与“怕考试”的因果也不通，句子不通。"}, "sentence_index": 0, "correct_answer": "逃避"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们应该勇敢地逃避困难。", "explanation": "这里应该用〈面对〉。逃避表示躲开不愿做的事，与“勇敢地”矛盾；面对困难才用“面对”。"}, {"text": "我每周都积极逃避班级活动。", "explanation": "这里应该用〈参加〉。逃避用于躲开不愿做的事，不能用来说主动投入的班级活动。"}, {"text": "他迅速逃避迎面飞来的礼物。", "explanation": "这里应该用〈接住〉。逃避表示躲开不愿面对的事，人们不会躲开想要的礼物，应说“接住”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92935, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "逃避", "is_correct": true, "explanation": "正确。逃避（táo bì）：遇到不想做的事就躲开不做。"}, {"text": "淘洗", "is_correct": false, "explanation": "淘洗（táo xǐ）第二个音节声母 x 与 b 不同，且声调为第三声，意思是用水冲洗并筛去杂质。"}, {"text": "台币", "is_correct": false, "explanation": "台币（tái bì）第一个音节韵母为 ai，与 ao 不同，意思是台湾地区的货币。"}, {"text": "逃匿", "is_correct": false, "explanation": "逃匿（táo nì）第二个音节声母 n 与 b 不同，意思是逃跑并隐藏。"}, {"text": "桃李", "is_correct": false, "explanation": "桃李（táo lǐ）第二个音节声母 l 与 b 不同，且声调为第三声，意思是桃树和李树。"}], "explanations": {"逃避": "正确。逃避（táo bì）：遇到不想做的事就躲开不做。", "淘洗": "淘洗（táo xǐ）第二个音节声母 x 与 b 不同，且声调为第三声，意思是用水冲洗并筛去杂质。", "台币": "台币（tái bì）第一个音节韵母为 ai，与 ao 不同，意思是台湾地区的货币。", "逃匿": "逃匿（táo nì）第二个音节声母 n 与 b 不同，意思是逃跑并隐藏。", "桃李": "桃李（táo lǐ）第二个音节声母 l 与 b 不同，且声调为第三声，意思是桃树和李树。"}, "sentence_index": null, "correct_answer": "逃避"}, "level_3": {"options": [{"text": "逃避", "is_correct": true, "explanation": "正确。“小明为了逃避洗碗，说自己头疼”：找借口躲开洗碗这件事，动机与行为相符，语义通顺。"}, {"text": "热爱", "is_correct": false, "explanation": "语义：“小明为了热爱洗碗，说自己头疼”动机自相矛盾，句子不通。"}, {"text": "咨询", "is_correct": false, "explanation": "搭配：“咨询”多接问题、意见，不能说“咨询洗碗”。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”接的是场所、展品，不能说“参观洗碗”。"}], "explanations": {"逃避": "正确。“小明为了逃避洗碗，说自己头疼”：找借口躲开洗碗这件事，动机与行为相符，语义通顺。", "热爱": "语义：“小明为了热爱洗碗，说自己头疼”动机自相矛盾，句子不通。", "咨询": "搭配：“咨询”多接问题、意见，不能说“咨询洗碗”。", "参观": "搭配：“参观”接的是场所、展品，不能说“参观洗碗”。"}, "sentence_index": 6, "correct_answer": "逃避"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家热情地逃避远道而来的客人。", "explanation": "这里应该用〈迎接〉。逃避是躲开不愿面对的事，不能用来描述热情欢迎客人。"}, {"text": "大家在广场上逃避胜利。", "explanation": "这里应该用〈庆祝〉。逃避表示躲开，不能用于值得高兴的胜利。"}, {"text": "我们要逃避时间。", "explanation": "这里应该用〈珍惜〉。逃避不能用于时间这类躲不开的对象，应说“珍惜时间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92935, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直逃避得这件事。", "corrected_sentence": "他一直逃避这件事。", "error_description": "错误形式“逃避得这件事”，多出了“得”。正确形式“逃避这件事”。“得”只用于动词后接补语，“逃避”直接带宾语时不加“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92935, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不敢逃避了责任。", "corrected_sentence": "他不敢逃避责任。", "error_description": "错误形式：“不敢逃避了责任”，在动词后多加了“了”。正确形式：“不敢逃避责任”。原因：“不敢”是否定的能愿动词，表示没有胆量去做，与表示完成的“了”不能搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
