INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92939, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "钢是又硬又结实的金属。", "primary_collocate": null, "pronunciation": "gāng", "ipa": "kɑŋ˥", "syllable_count": 1, "sentences": [{"text": "钢比木头硬多了。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把勺子是钢做的。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子是钢做的，很结实。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子用钢做，不怕摔。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一块钢，想做小刀。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢不像纸，用手弯不动。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇门是钢做的，小偷打不开。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢放在雨里，时间长了也会生锈。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用钢做了一把椅子。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥用钢做成，走几十年也没事。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块钢", "label": "量词"}, {"form": "一吨钢", "label": "量词"}, {"form": "钢材", "label": "复合"}, {"form": "钢铁", "label": "复合"}, {"form": "鋼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日常所见又硬又结实的金属材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3f55f56-4259-4abb-912d-1e43b9d9f8b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92939, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "钢", "is_correct": true, "explanation": "正确。钢（gāng）：又硬又结实的金属。"}, {"text": "工", "is_correct": false, "explanation": "工（gōng）韵母为 ong，与 ang 不同，意思是工作、工业。"}, {"text": "港", "is_correct": false, "explanation": "港（gǎng）声调为第三声，与第一声不同，意思是港口。"}, {"text": "高", "is_correct": false, "explanation": "高（gāo）韵尾由 ng 变为 o，意思是高矮的高。"}, {"text": "汤", "is_correct": false, "explanation": "汤（tāng）声母为 t，与 g 不同，意思是汤水。"}], "explanations": {"钢": "正确。钢（gāng）：又硬又结实的金属。", "工": "工（gōng）韵母为 ong，与 ang 不同，意思是工作、工业。", "港": "港（gǎng）声调为第三声，与第一声不同，意思是港口。", "高": "高（gāo）韵尾由 ng 变为 o，意思是高矮的高。", "汤": "汤（tāng）声母为 t，与 g 不同，意思是汤水。"}, "sentence_index": null, "correct_answer": "钢"}, "level_3": {"options": [{"text": "钢", "is_correct": true, "explanation": "正确。“钢比木头硬多了”：钢比木头硬，语义通顺。"}, {"text": "雾", "is_correct": false, "explanation": "搭配：“硬”用于形容固体，不能用来形容雾。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸比木头软，与“硬多了”的比较结果相反。"}, {"text": "木头", "is_correct": false, "explanation": "语义：比较双方都是木头，“木头比木头硬多了”不成立。"}], "explanations": {"钢": "正确。“钢比木头硬多了”：钢比木头硬，语义通顺。", "雾": "搭配：“硬”用于形容固体，不能用来形容雾。", "纸": "语义：纸比木头软，与“硬多了”的比较结果相反。", "木头": "语义：比较双方都是木头，“木头比木头硬多了”不成立。"}, "sentence_index": 0, "correct_answer": "钢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一棵钢。", "explanation": "这里应该用〈块〉。“棵”用于树木，不能用于钢这种材料。"}, {"text": "他每天弹钢。", "explanation": "这里应该用〈钢琴〉。钢是材料，不能用“弹”。"}, {"text": "工厂里有一座钢。", "explanation": "这里应该用〈块〉。“座”用于山、房屋等大型固定物，不用于钢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92939, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "钢", "is_correct": true, "explanation": "正确。钢（gāng）：又硬又结实的金属。"}, {"text": "当", "is_correct": false, "explanation": "当（dāng）声母为 d，与 g 不同，意思是担任、应当。"}, {"text": "干", "is_correct": false, "explanation": "干（gān）韵尾为 n，与 ng 不同，意思是干燥、做。"}, {"text": "方", "is_correct": false, "explanation": "方（fāng）声母为 f，与 g 不同，意思是方形、方向。"}, {"text": "康", "is_correct": false, "explanation": "康（kāng）声母为 k，与 g 不同，意思是健康、安康。"}], "explanations": {"钢": "正确。钢（gāng）：又硬又结实的金属。", "当": "当（dāng）声母为 d，与 g 不同，意思是担任、应当。", "干": "干（gān）韵尾为 n，与 ng 不同，意思是干燥、做。", "方": "方（fāng）声母为 f，与 g 不同，意思是方形、方向。", "康": "康（kāng）声母为 k，与 g 不同，意思是健康、安康。"}, "sentence_index": null, "correct_answer": "钢"}, "level_3": {"options": [{"text": "钢", "is_correct": true, "explanation": "正确。“这扇门是钢做的，小偷打不开”：钢门坚固，语义通顺。"}, {"text": "豆腐", "is_correct": false, "explanation": "语义：豆腐太软，做不成门，“豆腐做的门，小偷打不开”不合常理。"}, {"text": "棉花", "is_correct": false, "explanation": "语义：棉花做不成门，句子中“小偷打不开”的说法与之矛盾。"}, {"text": "泡沫", "is_correct": false, "explanation": "搭配：做门的材料多说木、铁等硬材料，不说泡沫做的门。"}], "explanations": {"钢": "正确。“这扇门是钢做的，小偷打不开”：钢门坚固，语义通顺。", "豆腐": "语义：豆腐太软，做不成门，“豆腐做的门，小偷打不开”不合常理。", "棉花": "语义：棉花做不成门，句子中“小偷打不开”的说法与之矛盾。", "泡沫": "搭配：做门的材料多说木、铁等硬材料，不说泡沫做的门。"}, "sentence_index": 6, "correct_answer": "钢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一朵钢。", "explanation": "这里应该用〈块〉。“朵”用于花，不能用于钢。"}, {"text": "他用钢写字。", "explanation": "这里应该用〈钢笔〉。钢是金属材料，不能直接用来写字。"}, {"text": "他每天喝一杯钢。", "explanation": "这里应该用〈水〉。钢是金属，不能喝；饮品才用“杯”计量，如“喝一杯水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92939, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人买了三本钢。", "corrected_sentence": "工人买了三块钢。", "error_description": "错误形式：“三本钢”，量词“本”用于书册。正确形式：“三块钢”。原因：钢作为材料应使用“块”计量，量词要与名词类别匹配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92939, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一只钢。", "corrected_sentence": "我买了一块钢。", "error_description": "错误形式：“一只钢”，量词“只”用于动物或成对的东西，不能用于钢。正确形式：“一块钢”，钢作为材料用“块”计量。原因：量词要与名词类别匹配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
