INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92940, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "含碳量较低、坚硬而有韧性的铁碳合金。", "primary_collocate": null, "pronunciation": "gāng", "ipa": "kɑŋ˥", "syllable_count": 1, "sentences": [{"text": "钢里的含碳量比生铁低。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把铁水炼成了钢。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每年生产五百万吨钢。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢又硬又有韧性，所以能做桥。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢含碳少，比生铁更结实。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用铁和碳炼出了好钢。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刀要用好钢来做才不容易断。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批钢的质量很好。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大楼用了很多钢。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的钢卖到了很多国家。", "target_word": "钢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一吨钢", "label": "量词"}, {"form": "一块钢", "label": "量词"}, {"form": "钢材", "label": "复合"}, {"form": "钢铁", "label": "复合"}, {"form": "鋼", "label": "繁体"}], "register": "书面", "sense_fingerprint": "由铁炼成、含碳量较低的合金材料（工业用）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3f55f56-4259-4abb-912d-1e43b9d9f8b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92940, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "钢", "is_correct": true, "explanation": "正确。钢（gāng）：含碳量较低、坚硬而有韧性的铁碳合金。"}, {"text": "工", "is_correct": false, "explanation": "工（gōng）韵母为 ong，与 ang 不同，意思是工作、工业。"}, {"text": "当", "is_correct": false, "explanation": "当（dāng）声母为 d，与 g 不同，意思是担任、应当。"}, {"text": "港", "is_correct": false, "explanation": "港（gǎng）声调为第三声，与第一声不同，意思是港口。"}, {"text": "干", "is_correct": false, "explanation": "干（gān）韵尾为 n，与 ng 不同，意思是干燥、做。"}], "explanations": {"钢": "正确。钢（gāng）：含碳量较低、坚硬而有韧性的铁碳合金。", "工": "工（gōng）韵母为 ong，与 ang 不同，意思是工作、工业。", "当": "当（dāng）声母为 d，与 g 不同，意思是担任、应当。", "港": "港（gǎng）声调为第三声，与第一声不同，意思是港口。", "干": "干（gān）韵尾为 n，与 ng 不同，意思是干燥、做。"}, "sentence_index": null, "correct_answer": "钢"}, "level_3": {"options": [{"text": "钢", "is_correct": true, "explanation": "正确。“钢里的含碳量比生铁低”：钢的含碳量低于生铁，语义通顺。"}, {"text": "生铁", "is_correct": false, "explanation": "语义：句子用“生铁”作比较对象，主语也是生铁，自相矛盾。"}, {"text": "碳", "is_correct": false, "explanation": "语义：碳本身是单质，“碳里的含碳量比生铁低”不合常理。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“含碳量”多用于说合金，不能用来说玻璃。"}], "explanations": {"钢": "正确。“钢里的含碳量比生铁低”：钢的含碳量低于生铁，语义通顺。", "生铁": "语义：句子用“生铁”作比较对象，主语也是生铁，自相矛盾。", "碳": "语义：碳本身是单质，“碳里的含碳量比生铁低”不合常理。", "玻璃": "搭配：“含碳量”多用于说合金，不能用来说玻璃。"}, "sentence_index": 0, "correct_answer": "钢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只钢。", "explanation": "这里应该用〈块〉。钢是材料，量词用“块”或“吨”，“只”多用于动物。"}, {"text": "他用钢写字。", "explanation": "这里应该用〈钢笔〉。钢是金属材料，不能直接用来写字。"}, {"text": "工厂生产了一朵钢。", "explanation": "这里应该用〈吨〉。钢按重量计量，“朵”用于花，不能用于钢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92940, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "钢", "is_correct": true, "explanation": "正确。钢（gāng）：含碳量较低、坚硬而有韧性的铁碳合金。"}, {"text": "方", "is_correct": false, "explanation": "方（fāng）声母为 f，与 g 不同，意思是方形、方向。"}, {"text": "汤", "is_correct": false, "explanation": "汤（tāng）声母为 t，与 g 不同，意思是汤水。"}, {"text": "高", "is_correct": false, "explanation": "高（gāo）韵尾由 ng 变为 o，意思是高矮的高。"}, {"text": "康", "is_correct": false, "explanation": "康（kāng）声母为 k，与 g 不同，意思是健康、安康。"}], "explanations": {"钢": "正确。钢（gāng）：含碳量较低、坚硬而有韧性的铁碳合金。", "方": "方（fāng）声母为 f，与 g 不同，意思是方形、方向。", "汤": "汤（tāng）声母为 t，与 g 不同，意思是汤水。", "高": "高（gāo）韵尾由 ng 变为 o，意思是高矮的高。", "康": "康（kāng）声母为 k，与 g 不同，意思是健康、安康。"}, "sentence_index": null, "correct_answer": "钢"}, "level_3": {"options": [{"text": "钢", "is_correct": true, "explanation": "正确。“刀要用好钢来做才不容易断”：好钢做刀不易断，语义通顺。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸不能用来做刀，“刀要用好纸来做”说不通。"}, {"text": "面粉", "is_correct": false, "explanation": "搭配：做刀的材料多说金属、钢铁，不说用面粉做刀。"}, {"text": "木炭", "is_correct": false, "explanation": "语义：木炭不能做刀，句子说的是用好材料做刀，木炭不符合。"}], "explanations": {"钢": "正确。“刀要用好钢来做才不容易断”：好钢做刀不易断，语义通顺。", "纸": "语义：纸不能用来做刀，“刀要用好纸来做”说不通。", "面粉": "搭配：做刀的材料多说金属、钢铁，不说用面粉做刀。", "木炭": "语义：木炭不能做刀，句子说的是用好材料做刀，木炭不符合。"}, "sentence_index": 6, "correct_answer": "钢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一棵钢。", "explanation": "这里应该用〈块〉。“棵”用于树木，不能用于钢这种材料。"}, {"text": "他每天弹钢。", "explanation": "这里应该用〈钢琴〉。钢是材料，不能用“弹”。"}, {"text": "工厂里有一座钢。", "explanation": "这里应该用〈块〉。“座”用于山、房屋等大型固定物，不用于钢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了两本钢。", "corrected_sentence": "他买了两块钢。", "error_description": "错误形式：“两本钢”，量词“本”用于书册。正确形式：“两块钢”，钢作为材料用“块”计量。原因：量词要与名词类别匹配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们卖掉了一只钢。", "corrected_sentence": "我们卖掉了一块钢。", "error_description": "错误形式：“一只钢”，量词“只”用于动物或成对的东西，不能用于钢。正确形式：“一块钢”。原因：钢作为材料用“块”计量，量词要与名词类别匹配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c96c5e13-fac7-47d7-bfcd-0659a31f095d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92941, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92941, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92941, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "商是买东西、卖东西的事。", "primary_collocate": null, "pronunciation": "shāng", "ipa": "ʂɑŋ˥", "syllable_count": 1, "sentences": [{"text": "古代人重农轻商。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放弃工作，改行从商。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲从商，母亲教书。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想当官，只想从商。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家世代为商，很有钱。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士农工商是古代的说法。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学了法律，后来改行从商。", "target_word": "商", "complexity_tier": "T3", "furigana": "tā xué le fǎlǜ hòulái gǎi háng cóng shāng", "sentence_source": "generated"}, {"text": "他先当老师，三年后改为从商。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在古代，商不受人重视。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从政不容易，从商也不容易。", "target_word": "商", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "商业", "label": "复合"}, {"form": "商人", "label": "复合"}], "register": "书面", "sense_fingerprint": "买卖东西这件事，与农、工、政相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f02719e-3c90-40e7-bbaa-c6aefb6742c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92941, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "商", "is_correct": true, "explanation": "商（shāng）指买卖、商业，是正确答案。"}, {"text": "上", "is_correct": false, "explanation": "上（shàng，第四声）与 shāng 声调不同，意思是上面。"}, {"text": "赏", "is_correct": false, "explanation": "赏（shǎng，第三声）与 shāng 声调不同，意思是欣赏或赏赐。"}, {"text": "山", "is_correct": false, "explanation": "山（shān）与 shāng 韵母不同（an 与 ang），意思是山。"}, {"text": "桑", "is_correct": false, "explanation": "桑（sāng）与 shāng 声母不同（s 与 sh），意思是桑树。"}], "explanations": {"商": "商（shāng）指买卖、商业，是正确答案。", "上": "上（shàng，第四声）与 shāng 声调不同，意思是上面。", "赏": "赏（shǎng，第三声）与 shāng 声调不同，意思是欣赏或赏赐。", "山": "山（shān）与 shāng 韵母不同（an 与 ang），意思是山。", "桑": "桑（sāng）与 shāng 声母不同（s 与 sh），意思是桑树。"}, "sentence_index": null, "correct_answer": "商"}, "level_3": {"options": [{"text": "树", "is_correct": false, "explanation": "语义：“重农轻”后接的是与“农”相对的行业，“树”不属于这一类。"}, {"text": "商", "is_correct": true, "explanation": "商指买卖的事，与“农”相对，“重农轻商”是古代的说法。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是行业或事务，与“重农轻”的意思不合。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“重…轻…”后接的是行业或事务，“花”不能这样搭配。"}], "explanations": {"树": "语义：“重农轻”后接的是与“农”相对的行业，“树”不属于这一类。", "商": "商指买卖的事，与“农”相对，“重农轻商”是古代的说法。", "石头": "语义：石头不是行业或事务，与“重农轻”的意思不合。", "花": "搭配：“重…轻…”后接的是行业或事务，“花”不能这样搭配。"}, "sentence_index": 0, "correct_answer": "商"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我感冒了，今天在医院从商。", "explanation": "这里应该用〈看病〉。“从商”指做买卖，在医院看病不能说“从商”。"}, {"text": "他在工地从商，负责砌墙。", "explanation": "这里应该用〈做工〉。“从商”指做买卖，砌墙是工人的工作，不能用“从商”。"}, {"text": "我每天早上去学校从商。", "explanation": "这里应该用〈上课〉。“从商”指做买卖，去学校上课不能用“从商”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92941, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "商", "is_correct": true, "explanation": "商（shāng）指买卖、商业，是正确答案。"}, {"text": "张", "is_correct": false, "explanation": "张（zhāng）与 shāng 声母不同（zh 与 sh），是量词。"}, {"text": "香", "is_correct": false, "explanation": "香（xiāng）与 shāng 声母不同（x 与 sh），意思是香气。"}, {"text": "尚", "is_correct": false, "explanation": "尚（shàng，第四声）与 shāng 声调不同，意思是还、尚且。"}, {"text": "生", "is_correct": false, "explanation": "生（shēng）与 shāng 韵母不同（eng 与 ang），意思是生活或出生。"}], "explanations": {"商": "商（shāng）指买卖、商业，是正确答案。", "张": "张（zhāng）与 shāng 声母不同（zh 与 sh），是量词。", "香": "香（xiāng）与 shāng 声母不同（x 与 sh），意思是香气。", "尚": "尚（shàng，第四声）与 shāng 声调不同，意思是还、尚且。", "生": "生（shēng）与 shāng 韵母不同（eng 与 ang），意思是生活或出生。"}, "sentence_index": null, "correct_answer": "商"}, "level_3": {"options": [{"text": "山", "is_correct": false, "explanation": "语义：“改行从”后接的是行业或职业，“山”不是职业。"}, {"text": "商", "is_correct": true, "explanation": "商指买卖，“改行从商”指转去做买卖，符合句意。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不是行业，“改行从水”的说法不通。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“从”后接的是行业或职业，“雨”不能这样搭配。"}], "explanations": {"山": "语义：“改行从”后接的是行业或职业，“山”不是职业。", "商": "商指买卖，“改行从商”指转去做买卖，符合句意。", "水": "语义：水不是行业，“改行从水”的说法不通。", "雨": "搭配：“从”后接的是行业或职业，“雨”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "商"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她从商多年，每天在学校里给学生上数学课。", "explanation": "这里应该用〈教书〉。“从商”指做买卖，给学生上课要说“教书”。"}, {"text": "他在山上从商，每天放羊。", "explanation": "这里应该用〈放羊〉。“从商”指做买卖，不能用来指放羊的工作。"}, {"text": "他从商后去医院做医生，治病救人。", "explanation": "这里应该用〈行医〉。“从商”指做买卖，做医生要说“行医”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他毕业以后做商十年了。", "corrected_sentence": "他毕业以后从商十年了。", "error_description": "错误：“做商”，正确：“从商”。“从商”是固定说法，指从事买卖，“商”不能和“做”搭配，应说“从商”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年才商从，现在开了一家店。", "corrected_sentence": "他去年才从商，现在开了一家店。", "error_description": "错误：“商从”，语序颠倒，应为“从商”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
