INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92957, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "客是到你家来玩的人。", "primary_collocate": null, "pronunciation": "kè", "ipa": "kʰɤ˥˩", "syllable_count": 1, "sentences": [{"text": "家里来客了，妈妈在做饭。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天家里有客，别太吵。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客来了，请他坐在这里。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸给客倒了一杯茶。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把客送到门口。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家来了一位客。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客坐了一会儿就走了。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客一进门，小狗就叫了。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，有客来要先倒茶。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客走以后，我们一起洗杯子。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "客人", "label": "复合"}], "register": "中性", "sense_fingerprint": "来家里做客、拜访的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f02719e-3c90-40e7-bbaa-c6aefb6742c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92957, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "客", "is_correct": true, "explanation": "客（kè）指来家里做客的人，是正确答案。"}, {"text": "渴", "is_correct": false, "explanation": "渴（kě，第三声）与 kè（第四声）声调不同，意思是口渴。"}, {"text": "科", "is_correct": false, "explanation": "科（kē，第一声）与 kè 声调不同，意思是学科、科目。"}, {"text": "个", "is_correct": false, "explanation": "个（gè）与 kè 声母不同（g 与 k），是常用量词。"}, {"text": "咳", "is_correct": false, "explanation": "咳（ké，第二声）与 kè（第四声）声调不同，意思是咳嗽。"}], "explanations": {"客": "客（kè）指来家里做客的人，是正确答案。", "渴": "渴（kě，第三声）与 kè（第四声）声调不同，意思是口渴。", "科": "科（kē，第一声）与 kè 声调不同，意思是学科、科目。", "个": "个（gè）与 kè 声母不同（g 与 k），是常用量词。", "咳": "咳（ké，第二声）与 kè（第四声）声调不同，意思是咳嗽。"}, "sentence_index": null, "correct_answer": "客"}, "level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房本来就在家里，不能说“家里来厨房了”。"}, {"text": "客", "is_correct": true, "explanation": "客指来家里做客的人，“家里来客了”符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮在天上，不会“来”到家里。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“家里来+名词”一般指人或具体事物到访，“空气”不这样搭配。"}], "explanations": {"厨房": "语义：厨房本来就在家里，不能说“家里来厨房了”。", "客": "客指来家里做客的人，“家里来客了”符合句意。", "月亮": "语义：月亮在天上，不会“来”到家里。", "空气": "搭配：“家里来+名词”一般指人或具体事物到访，“空气”不这样搭配。"}, "sentence_index": 0, "correct_answer": "客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我去医院做客，给生病的同学带了水果。", "explanation": "这里应该用〈探望〉。“做客”指到别人家中作客，去医院看病人不能用“做客”。"}, {"text": "我家的客是妈妈，她每天做饭打扫。", "explanation": "这里应该用〈主人〉。妈妈住在家里是主人，不能说是来家里的客。"}, {"text": "这个学校的客每天在教室里上课。", "explanation": "这里应该用〈老师〉。“客”指来访的人，在教室里上课的是老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92957, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "客", "is_correct": true, "explanation": "客（kè）指来访的人，是正确答案。"}, {"text": "可", "is_correct": false, "explanation": "可（kě，第三声）与 kè（第四声）声调不同，意思是“可以”。"}, {"text": "颗", "is_correct": false, "explanation": "颗（kē，第一声）与 kè 声调不同，是量词，用于小而圆的东西。"}, {"text": "壳", "is_correct": false, "explanation": "壳（ké，第二声）与 kè 声调不同，意思是外壳。"}, {"text": "贺", "is_correct": false, "explanation": "贺（hè）与 kè 声母不同（h 与 k），意思是祝贺。"}], "explanations": {"客": "客（kè）指来访的人，是正确答案。", "可": "可（kě，第三声）与 kè（第四声）声调不同，意思是“可以”。", "颗": "颗（kē，第一声）与 kè 声调不同，是量词，用于小而圆的东西。", "壳": "壳（ké，第二声）与 kè 声调不同，意思是外壳。", "贺": "贺（hè）与 kè 声母不同（h 与 k），意思是祝贺。"}, "sentence_index": null, "correct_answer": "客"}, "level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "语义：椅子是用来坐的，不会“坐了一会儿就走了”。"}, {"text": "客", "is_correct": true, "explanation": "客指来访的人，“坐了一会儿就走了”说的是客人。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能自己坐下，也不会离开，与句中动作不合。"}, {"text": "车", "is_correct": false, "explanation": "搭配：“坐”的主语应是人，说“车坐了”不搭配（“坐车”中车是宾语）。"}], "explanations": {"椅子": "语义：椅子是用来坐的，不会“坐了一会儿就走了”。", "客": "客指来访的人，“坐了一会儿就走了”说的是客人。", "书": "语义：书不能自己坐下，也不会离开，与句中动作不合。", "车": "搭配：“坐”的主语应是人，说“车坐了”不搭配（“坐车”中车是宾语）。"}, "sentence_index": 6, "correct_answer": "客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个家的客是妈妈。", "explanation": "这里应该用〈主人〉。“客”指来做客的人，妈妈住在这个家里，是主人，不能说是客。"}, {"text": "这套房子的客是我的叔叔。", "explanation": "这里应该用〈房东〉。房东是房子的所有者或出租人，不是来做客的人。"}, {"text": "今天的客是老李，他请大家吃饭。", "explanation": "这里应该用〈东道主〉。请客吃饭的是东道主，“客”指被招待的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92957, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末家里来了两只客，我们都很高兴。", "corrected_sentence": "周末家里来了两位客，我们都很高兴。", "error_description": "错误：“两只客”。量词“只”多用于动物，指人的客应用“位”或“个”，应说“两位客”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92957, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末我们一家人都去舅舅家的做客。", "corrected_sentence": "周末我们一家人都去舅舅家做客。", "error_description": "错误：“去舅舅家的做客”，正确：“去舅舅家做客”。“做客”是动宾式离合词，地点“舅舅家”直接放在“去”后面，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
