INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92958, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "客人；来访的人。", "primary_collocate": null, "pronunciation": "kè", "ipa": "kʰɤ˥˩", "syllable_count": 1, "sentences": [{"text": "门口有客，你去开门吧。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客不多，只有三位。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主人让客先坐下。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对客很热情。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位客等了很久。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是从远方来的客。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客要走了，主人送到门外。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，今天来的客是谁？", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司来客，先倒茶。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客喝完茶，就和主人聊天。", "target_word": "客", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "客人", "label": "复合"}], "register": "中性", "sense_fingerprint": "被主人接待的来访者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f02719e-3c90-40e7-bbaa-c6aefb6742c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92958, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "客", "is_correct": true, "explanation": "客（kè）指被接待的来访者，是正确答案。"}, {"text": "渴", "is_correct": false, "explanation": "渴（kě，第三声）与 kè（第四声）声调不同，意思是口渴。"}, {"text": "棵", "is_correct": false, "explanation": "棵（kē，第一声）与 kè 声调不同，是量词，用于树木。"}, {"text": "壳", "is_correct": false, "explanation": "壳（ké，第二声）与 kè 声调不同，意思是外壳。"}, {"text": "各", "is_correct": false, "explanation": "各（gè）与 kè 声母不同（g 与 k），意思是各自、每个。"}], "explanations": {"客": "客（kè）指被接待的来访者，是正确答案。", "渴": "渴（kě，第三声）与 kè（第四声）声调不同，意思是口渴。", "棵": "棵（kē，第一声）与 kè 声调不同，是量词，用于树木。", "壳": "壳（ké，第二声）与 kè 声调不同，意思是外壳。", "各": "各（gè）与 kè 声母不同（g 与 k），意思是各自、每个。"}, "sentence_index": null, "correct_answer": "客"}, "level_3": {"options": [{"text": "雨", "is_correct": false, "explanation": "语义：下雨不需要去开门，与“你去开门”的情境不合。"}, {"text": "客", "is_correct": true, "explanation": "客指来访的人，“门口有客”指有人来访，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“门口有”后接的是具体的人或物，“空气”不这样搭配。"}, {"text": "火", "is_correct": false, "explanation": "语义：门口有火与“你去开门”的情境不合，而且有危险。"}], "explanations": {"雨": "语义：下雨不需要去开门，与“你去开门”的情境不合。", "客": "客指来访的人，“门口有客”指有人来访，符合句意。", "空气": "搭配：“门口有”后接的是具体的人或物，“空气”不这样搭配。", "火": "语义：门口有火与“你去开门”的情境不合，而且有危险。"}, "sentence_index": 0, "correct_answer": "客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天坐车去工厂当客，负责修理机器。", "explanation": "这里应该用〈当工人〉。“客”指来访的人，在工厂工作的是工人，不能说“当客”。"}, {"text": "我下午在自己家做客，自己给自己做了一顿饭。", "explanation": "这里应该用〈待在家里〉。“做客”指到别人家中作客，在自己家里不能说“做客”。"}, {"text": "这间屋子的客是我，我来招待你们。", "explanation": "这里应该用〈主人〉。招待客人的是主人，“客”是被招待的人，不能说自己是客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92958, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "客", "is_correct": true, "explanation": "客（kè）指被接待的来访者，是正确答案。"}, {"text": "贺", "is_correct": false, "explanation": "贺（hè）与 kè 声母不同（h 与 k），意思是祝贺。"}, {"text": "可", "is_correct": false, "explanation": "可（kě，第三声）与 kè（第四声）声调不同，意思是“可以”。"}, {"text": "科", "is_correct": false, "explanation": "科（kē，第一声）与 kè 声调不同，意思是学科、科目。"}, {"text": "咳", "is_correct": false, "explanation": "咳（ké，第二声）与 kè（第四声）声调不同，意思是咳嗽。"}], "explanations": {"客": "客（kè）指被接待的来访者，是正确答案。", "贺": "贺（hè）与 kè 声母不同（h 与 k），意思是祝贺。", "可": "可（kě，第三声）与 kè（第四声）声调不同，意思是“可以”。", "科": "科（kē，第一声）与 kè 声调不同，意思是学科、科目。", "咳": "咳（ké，第二声）与 kè（第四声）声调不同，意思是咳嗽。"}, "sentence_index": null, "correct_answer": "客"}, "level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会“要走了”，与“主人送到门外”也不合。"}, {"text": "客", "is_correct": true, "explanation": "客指来访的人，“要走了”和“主人送到门外”说的都是客人。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会自己离开，与“要走了”的说法不合。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：“要走了”的主语应是能自行离开的人或物，墙不能说要走。"}], "explanations": {"桌子": "语义：桌子不会“要走了”，与“主人送到门外”也不合。", "客": "客指来访的人，“要走了”和“主人送到门外”说的都是客人。", "石头": "语义：石头不会自己离开，与“要走了”的说法不合。", "墙": "搭配：“要走了”的主语应是能自行离开的人或物，墙不能说要走。"}, "sentence_index": 6, "correct_answer": "客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在操场上做客，一起踢足球。", "explanation": "这里应该用〈玩〉。“做客”指到别人家中作客，操场不是别人家，不能说“做客”。"}, {"text": "我每天在厨房做客，自己炒菜煮饭。", "explanation": "这里应该用〈做饭〉。“做客”指到别人家中作客，在自家厨房不能说“做客”。"}, {"text": "院子里停着一辆车，车上的客装满了砖头。", "explanation": "这里应该用〈货〉。“客”指来访的人，不能指装在车上的货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末，客们陆续来了。", "corrected_sentence": "周末，客人们陆续来了。", "error_description": "错误：“客们”。“客”单用时不能直接加“们”，应说“客人们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天来了三条客，厨房都忙不过来了。", "corrected_sentence": "今天来了三位客，厨房都忙不过来了。", "error_description": "错误：“三条客”。“条”用于细长的东西，指人的客应用“位”或“个”，应说“三位客”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92959, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独立", "is_correct": true, "explanation": "正确。独立指不依附于别的，自己单独存在，与“附属”相反。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与“附属”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明形容头脑，与“附属”的这个义项无关。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚形容明白、不模糊，与“附属”的这个义项无关。"}], "correct_answer": "独立", "explanations": {"独立": "正确。独立指不依附于别的，自己单独存在，与“附属”相反。", "明亮": "明亮形容光线或颜色，与“附属”没有反义关系。", "聪明": "聪明形容头脑，与“附属”的这个义项无关。", "清楚": "清楚形容明白、不模糊，与“附属”的这个义项无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92959, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独立", "is_correct": true, "explanation": "正确。独立指不依附于别的，自己单独存在，与“附属”相反。"}, {"text": "活泼", "is_correct": false, "explanation": "活泼形容性格或动作，与“附属”没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "简单形容事情或结构容易，与“附属”的这个义项无关。"}, {"text": "温暖", "is_correct": false, "explanation": "温暖形容温度或感情，与“附属”的这个义项无关。"}], "correct_answer": "独立", "explanations": {"独立": "正确。独立指不依附于别的，自己单独存在，与“附属”相反。", "活泼": "活泼形容性格或动作，与“附属”没有反义关系。", "简单": "简单形容事情或结构容易，与“附属”的这个义项无关。", "温暖": "温暖形容温度或感情，与“附属”的这个义项无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92959, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "附属是跟着一个大东西，属于它的一部分。", "primary_collocate": null, "pronunciation": "fù shǔ", "ipa": "fu˥˩ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个附属房间很小，只能放杂物。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台相机的附属部件都放在盒子里。", "target_word": "附属", "complexity_tier": "T3", "furigana": "zhè tái xiàngjī de fùshǔ bùjiàn dōu fàng zài hézi lǐ", "sentence_source": "generated"}, {"text": "主楼旁边有一个附属建筑。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买电脑时，他还买了一些附属设备。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小花园是房子的附属部分。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的附属光盘在书后面的袋子里。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房旁边是一间附属的小仓库。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上画着大楼和它的附属小楼。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店的附属停车场很大。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子的附属抽屉可以放笔和本子。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "附属品", "label": "复合"}, {"form": "附属医院", "label": "复合"}], "register": "中性", "sense_fingerprint": "跟随主体、作为其一部分的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30465e8-a764-427e-9db7-903b0f509c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92959, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "附属", "is_correct": true, "explanation": "正确。附属 fù shǔ，指跟着一个大东西、属于它的一部分。"}, {"text": "复数", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）第二个音节声调不同，意思是复数。"}, {"text": "服输", "is_correct": false, "explanation": "fú shū（第二、第一声）与 fù shǔ（第四、第三声）两个音节声调都不同，意思是认输。"}, {"text": "部属", "is_correct": false, "explanation": "bù 与 fù 声母不同（b 与 f），意思是部下。"}], "explanations": {"附属": "正确。附属 fù shǔ，指跟着一个大东西、属于它的一部分。", "复数": "shù（第四声）与 shǔ（第三声）第二个音节声调不同，意思是复数。", "服输": "fú shū（第二、第一声）与 fù shǔ（第四、第三声）两个音节声调都不同，意思是认输。", "部属": "bù 与 fù 声母不同（b 与 f），意思是部下。"}, "sentence_index": null, "correct_answer": "附属"}, "level_3": {"options": [{"text": "附属", "is_correct": true, "explanation": "正确。“附属房间”指与主体相连、属于它的小房间，与“很小”“放杂物”相合。"}, {"text": "宽敞", "is_correct": false, "explanation": "语义：“宽敞”与后文“很小”矛盾。"}, {"text": "豪华", "is_correct": false, "explanation": "语义：豪华的房间不会只能放杂物。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”指高而大，与后文“很小”矛盾。"}], "explanations": {"附属": "正确。“附属房间”指与主体相连、属于它的小房间，与“很小”“放杂物”相合。", "宽敞": "语义：“宽敞”与后文“很小”矛盾。", "豪华": "语义：豪华的房间不会只能放杂物。", "高大": "语义：“高大”指高而大，与后文“很小”矛盾。"}, "sentence_index": 0, "correct_answer": "附属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑还要交一笔附属费。", "explanation": "这里应该用〈附加〉。附加表示额外增加的费用；附属指属于某主体的一部分，不能用来说费用。"}, {"text": "这封邮件里有一个附属。", "explanation": "这里应该用〈附件〉。附件指随正文一同发送的文件；附属是形容词，不能单独作名词指邮件里的附加文件。"}, {"text": "他在实验中是附属的主角。", "explanation": "这里应该用〈主要〉。主要指居于首位；附属指依附于主体，与“主角”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92959, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "附属", "is_correct": true, "explanation": "正确。“附属的小仓库”指与厨房相连、属于它的小仓库，与语境相合。"}, {"text": "空旷", "is_correct": false, "explanation": "语义：“空旷”指很大而没有东西，与后文“小”矛盾。"}, {"text": "繁华", "is_correct": false, "explanation": "搭配：“繁华”多形容街区、市场，不用来说仓库。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”多用来形容人，不用来形容仓库。"}], "explanations": {"附属": "正确。“附属的小仓库”指与厨房相连、属于它的小仓库，与语境相合。", "空旷": "语义：“空旷”指很大而没有东西，与后文“小”矛盾。", "繁华": "搭配：“繁华”多形容街区、市场，不用来说仓库。", "年轻": "搭配：“年轻”多用来形容人，不用来形容仓库。"}, "sentence_index": 6, "correct_answer": "附属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地震之后又出现了附属灾害。", "explanation": "这里应该用〈次生〉。次生灾害指由原生灾害引起的灾害；附属不能用来说灾害。"}, {"text": "这种病的附属症状很明显。", "explanation": "这里应该用〈伴随〉。伴随症状指与主病同时出现的症状；附属强调属于主体的一部分，不这样说。"}, {"text": "这只是附属原因。", "explanation": "这里应该用〈次要〉。次要表示不是主要的；附属强调依附于某主体，不用来说原因的主次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间附属了主楼。", "corrected_sentence": "这个房间附属于主楼。", "error_description": "漏“于”：“附属”后面要用“于”引出所属的主体，应说“附属于主楼”，不能说“附属了主楼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台游戏机的附属于配件都放在柜子里。", "corrected_sentence": "这台游戏机的附属配件都放在柜子里。", "error_description": "多出“于”：“附属”作定语修饰“配件”时后面不加“于”，应说“附属配件”；“附属于”只用于后面带所属主体的情况，不能直接修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
