INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92960, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "依附于某一主体或隶属于某一单位。", "primary_collocate": null, "pronunciation": "fù shǔ", "ipa": "fu˥˩ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在北京大学附属医院工作。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所附属中学离大学很近。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小公司附属于一家大企业。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我女儿在师范大学附属小学读书。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究所附属于国家科学院。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "附属学校的老师都是大学请来的。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院是大学的附属单位。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "附属医院的医生经验很丰富。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的工厂附属于总公司。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的孩子都在附属幼儿园上学。", "target_word": "附属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "附属品", "label": "复合"}, {"form": "附属医院", "label": "复合"}], "register": "中性", "sense_fingerprint": "隶属于某个单位或机构的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30465e8-a764-427e-9db7-903b0f509c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92960, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "附属", "is_correct": true, "explanation": "正确。附属 fù shǔ，指依附于某一主体或隶属于某一单位。"}, {"text": "负数", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）第二个音节声调不同，意思是负数。"}, {"text": "服输", "is_correct": false, "explanation": "fú shū（第二、第一声）与 fù shǔ（第四、第三声）两个音节声调都不同，意思是认输。"}, {"text": "部属", "is_correct": false, "explanation": "bù 与 fù 声母不同（b 与 f），意思是部下。"}], "explanations": {"附属": "正确。附属 fù shǔ，指依附于某一主体或隶属于某一单位。", "负数": "shù（第四声）与 shǔ（第三声）第二个音节声调不同，意思是负数。", "服输": "fú shū（第二、第一声）与 fù shǔ（第四、第三声）两个音节声调都不同，意思是认输。", "部属": "bù 与 fù 声母不同（b 与 f），意思是部下。"}, "sentence_index": null, "correct_answer": "附属"}, "level_3": {"options": [{"text": "附属", "is_correct": true, "explanation": "正确。“附属医院”指隶属于大学的医院，与“北京大学”和“工作”相合。"}, {"text": "愉快", "is_correct": false, "explanation": "搭配：“愉快”形容人的心情，不用来修饰医院。"}, {"text": "寒冷", "is_correct": false, "explanation": "搭配：“寒冷”形容天气或环境，不用来修饰医院。"}, {"text": "荒凉", "is_correct": false, "explanation": "语义：北京大学的医院不会荒凉，与语境不符。"}], "explanations": {"附属": "正确。“附属医院”指隶属于大学的医院，与“北京大学”和“工作”相合。", "愉快": "搭配：“愉快”形容人的心情，不用来修饰医院。", "寒冷": "搭配：“寒冷”形容天气或环境，不用来修饰医院。", "荒凉": "语义：北京大学的医院不会荒凉，与语境不符。"}, "sentence_index": 0, "correct_answer": "附属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是局长的附属领导。", "explanation": "这里应该用〈直属〉。直属指直接隶属于某上级，说领导要用直属；附属指依附于主体，不说领导。"}, {"text": "这套房子附属于车库。", "explanation": "这里应该用〈附有〉。附有表示带有某物；附属于指某物隶属于某主体，房子不能隶属于车库。"}, {"text": "北京是一个附属市。", "explanation": "这里应该用〈直辖〉。直辖市直接由中央管辖；附属指属于某主体，不能说“附属市”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "附属", "is_correct": true, "explanation": "正确。“附属单位”指隶属于大学的单位，与“大学的”相合。"}, {"text": "幸福", "is_correct": false, "explanation": "搭配：“幸福”形容人的感受，不用来形容单位。"}, {"text": "幽默", "is_correct": false, "explanation": "搭配：“幽默”形容人的说话方式，不用来修饰单位。"}, {"text": "凶猛", "is_correct": false, "explanation": "语义：医院或单位不用“凶猛”形容，与语境不合。"}], "explanations": {"附属": "正确。“附属单位”指隶属于大学的单位，与“大学的”相合。", "幸福": "搭配：“幸福”形容人的感受，不用来形容单位。", "幽默": "搭配：“幽默”形容人的说话方式，不用来修饰单位。", "凶猛": "语义：医院或单位不用“凶猛”形容，与语境不合。"}, "sentence_index": 6, "correct_answer": "附属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们公司附属的员工。", "explanation": "这里应该用〈所属〉。所属指属于某单位的成员；附属强调依附于主体的一部分，不能用来说员工。"}, {"text": "这家餐厅还收了一笔附属服务费。", "explanation": "这里应该用〈附加〉。附加表示另外增加的费用；附属不能用来说服务费。"}, {"text": "这名战士是我们师的附属战士。", "explanation": "这里应该用〈编入〉。编入指把人员纳入某单位；附属指依附于某主体，不能用来说“附属战士”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所小医院附属一家大学。", "corrected_sentence": "这所小医院附属于一家大学。", "error_description": "漏了“于”：表示隶属关系时，“附属”后面要加“于”再接单位，应说“附属于”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
