INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92963, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "雷达是能发出看不见的波，帮我们找到远处飞机的机器。", "primary_collocate": null, "pronunciation": "léi dá", "ipa": "leɪ˧˥ ta˧˥", "syllable_count": 2, "sentences": [{"text": "雷达能帮我们找到远处的飞机。", "target_word": "雷达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机场旁边有一台大雷达。", "target_word": "雷达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雷达会发出看不见的波。", "target_word": "雷达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里看不清飞机，我们可以用雷达。", "target_word": "雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那台雷达一直在转。", "target_word": "雷达", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雷达是一种机器，不是玩具。", "target_word": "雷达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明在书上看到了雷达的图片。", "target_word": "雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雷达坏了，飞机找不到路。", "target_word": "雷达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山顶上的雷达看得很远。", "target_word": "雷达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在修那台雷达。", "target_word": "雷达", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一部雷达", "label": "量词"}, {"form": "一台雷达", "label": "量词"}, {"form": "雷达站", "label": "复合"}, {"form": "雷達", "label": "繁体"}], "register": "中性", "sense_fingerprint": "能帮人找到远处飞机的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59765317-1277-4541-a33b-efb6288b49af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92963, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雷达", "is_correct": true, "explanation": "雷达：利用无线电波帮人找到远处的飞机，符合句意。"}, {"text": "收音机", "is_correct": false, "explanation": "语义：收音机接收广播声音，不能找到远处的飞机。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱用于冷藏，与找飞机无关。"}, {"text": "梳子", "is_correct": false, "explanation": "配价：找到要求有能力找的施事，梳子不能作主语。"}], "explanations": {"雷达": "雷达：利用无线电波帮人找到远处的飞机，符合句意。", "收音机": "语义：收音机接收广播声音，不能找到远处的飞机。", "冰箱": "语义：冰箱用于冷藏，与找飞机无关。", "梳子": "配价：找到要求有能力找的施事，梳子不能作主语。"}, "sentence_index": 0, "correct_answer": "雷达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用雷达量了我的体温。", "explanation": "这里应该用〈体温计〉。雷达用于探测远处物体，量体温要用体温计。"}, {"text": "机场旁边有一棵雷达。", "explanation": "这里的量词应用〈台〉。〈棵〉用于树木，不用于机器。"}, {"text": "他用雷达擦干净了窗户。", "explanation": "这里应该用〈抹布〉。雷达是探测设备，不能用来擦窗户。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92963, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雷达", "is_correct": true, "explanation": "雷达：小明在书上看到的是雷达的图片，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是感觉，没有可以看到的图片，不说“味道的图片”。"}, {"text": "道理", "is_correct": false, "explanation": "语义：道理是抽象的思想，没有图片可以看到。"}, {"text": "理由", "is_correct": false, "explanation": "语义：理由是抽象的说法，没有图片可以看到。"}], "explanations": {"雷达": "雷达：小明在书上看到的是雷达的图片，符合句意。", "味道": "语义：味道是感觉，没有可以看到的图片，不说“味道的图片”。", "道理": "语义：道理是抽象的思想，没有图片可以看到。", "理由": "语义：理由是抽象的说法，没有图片可以看到。"}, "sentence_index": 6, "correct_answer": "雷达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "渔船用雷达探测水下的鱼群。", "explanation": "这里应该用〈声呐〉。雷达依靠无线电波，无法有效穿透海水，水下探测鱼群要用声呐。"}, {"text": "他用雷达算出了账单的总额。", "explanation": "这里应该用〈计算器〉。雷达用于探测远处物体的位置和速度，不能用来计算金额。"}, {"text": "他用雷达看清了桌上的小字。", "explanation": "这里应该用〈放大镜〉。雷达探测的是远处物体的位置和速度，不能用来看清细小的字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在雷达找到了远处的飞机。", "corrected_sentence": "我们用雷达找到了远处的飞机。", "error_description": "错误：表示用什么工具时要用“用”，不能用“在”。“在雷达”应改为“用雷达”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程师把那只雷达搬进了机房。", "corrected_sentence": "工程师把那台雷达搬进了机房。", "error_description": "错误：量词“只”不能用于机器。雷达应用“台”，正确为“那台雷达”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
