INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92964, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "利用无线电波探测并测定远处物体位置、速度等的设备。", "primary_collocate": null, "pronunciation": "léi dá", "ipa": "leɪ˧˥ ta˧˥", "syllable_count": 2, "sentences": [{"text": "雷达可以测出飞机的位置。", "target_word": "雷达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这艘船上有一部新雷达。", "target_word": "雷达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雷达的屏幕上出现了一个小点。", "target_word": "雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察用雷达测汽车的速度。", "target_word": "雷达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雷达能探测到远处的大雨。", "target_word": "雷达", "complexity_tier": "T3", "furigana": "léi dá néng tàn cè dào yuǎn chù de dà yǔ", "sentence_source": "generated"}, {"text": "机场的雷达二十四小时开着。", "target_word": "雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雷达发现远处有一架飞机。", "target_word": "雷达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船上的雷达坏了，船长很着急。", "target_word": "雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雷达能测定远处物体的速度。", "target_word": "雷达", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军队在山上放了一台雷达。", "target_word": "雷达", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一部雷达", "label": "量词"}, {"form": "一台雷达", "label": "量词"}, {"form": "雷达站", "label": "复合"}, {"form": "雷達", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用无线电波探测物体位置和速度的设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59765317-1277-4541-a33b-efb6288b49af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92964, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雷达", "is_correct": true, "explanation": "雷达：利用无线电波探测远处飞机的位置，符合句意。"}, {"text": "温度计", "is_correct": false, "explanation": "语义：温度计只测温度，不能测出飞机的位置。"}, {"text": "天平", "is_correct": false, "explanation": "搭配：天平称重量，不与“位置”搭配。"}, {"text": "电饭煲", "is_correct": false, "explanation": "语义：电饭煲用于煮饭，与测定飞机位置无关。"}], "explanations": {"雷达": "雷达：利用无线电波探测远处飞机的位置，符合句意。", "温度计": "语义：温度计只测温度，不能测出飞机的位置。", "天平": "搭配：天平称重量，不与“位置”搭配。", "电饭煲": "语义：电饭煲用于煮饭，与测定飞机位置无关。"}, "sentence_index": 0, "correct_answer": "雷达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只雷达。", "explanation": "这里的量词应用〈台〉或〈部〉。雷达是机器，〈只〉多用于动物或成对的东西。"}, {"text": "他用雷达拍下了远处的飞机。", "explanation": "这里应该用〈摄像机〉。雷达用于探测物体位置和速度，不用于拍照。"}, {"text": "他用雷达照亮了黑暗的走廊。", "explanation": "这里应该用〈手电筒〉。雷达是探测设备，不能用来照明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92964, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雷达", "is_correct": true, "explanation": "雷达：利用无线电波发现远处的飞机，符合句意。"}, {"text": "温度计", "is_correct": false, "explanation": "语义：温度计不能发现远处的飞机。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱没有探测功能，不能发现远处的飞机。"}, {"text": "雨伞", "is_correct": false, "explanation": "配价：发现要求能感知的主体，雨伞不能作主语。"}], "explanations": {"雷达": "雷达：利用无线电波发现远处的飞机，符合句意。", "温度计": "语义：温度计不能发现远处的飞机。", "冰箱": "语义：冰箱没有探测功能，不能发现远处的飞机。", "雨伞": "配价：发现要求能感知的主体，雨伞不能作主语。"}, "sentence_index": 6, "correct_answer": "雷达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "潜艇用雷达探测水下的目标。", "explanation": "这里应该用〈声呐〉。雷达依靠无线电波，在海水中衰减很快，水下探测要用靠声波工作的声呐。"}, {"text": "他用雷达叫醒了自己。", "explanation": "这里应该用〈闹钟〉。雷达是探测远处物体位置和速度的设备，不能用来定时叫醒人。"}, {"text": "超市的收银员用雷达读取商品上的条形码。", "explanation": "这里应该用〈扫描仪〉。雷达用于探测远处物体，读取条形码要用扫描仪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "港口有一只雷达一直在工作。", "corrected_sentence": "港口有一台雷达一直在工作。", "error_description": "错误：量词“只”不能用于机器。雷达应用“台”，正确为“一台雷达”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把雷达修了好。", "corrected_sentence": "工人把雷达修好了。", "error_description": "错误：“了”放在了结果补语“好”之前，“修了好”不成立。“了”应放在补语之后、句末，正确为“把雷达修好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
