INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92975, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不加是不放进去，也不多放。", "primary_collocate": null, "pronunciation": "bù jiā", "ipa": "pu˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "我的咖啡不加糖。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗面不加辣椒。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一杯茶，不加牛奶。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做汤时不加盐。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝咖啡从来不加奶。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜不加葱，谢谢。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做蛋糕可以不加香草吗？", "target_word": "不加", "complexity_tier": "T3", "furigana": "zuò dàngāo kěyǐ bù jiā xiāngcǎo ma", "sentence_source": "generated"}, {"text": "老板，我的面条不加香菜。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喝豆浆一般不加糖。", "target_word": "不加", "complexity_tier": "T3", "furigana": "wǒ hē dòujiāng yìbān bù jiā táng", "sentence_source": "generated"}, {"text": "这杯果汁不加冰。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "做饮食时不放入某种东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5defac78-781a-4fa9-9921-04631e3ba9d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92975, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不加", "is_correct": true, "explanation": "正确：不加（bù jiā），意思是做饮食时不放入某种东西。"}, {"text": "附加", "is_correct": false, "explanation": "fù（第四声）与 bù（第四声）声母不同（f 与 b），意思是额外添上，与“不放入”不同。"}, {"text": "不假", "is_correct": false, "explanation": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是不是假的、真实的。"}, {"text": "补假", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）、jià（第四声）与 jiā（第一声）声调都不同，意思是补休的假期。"}], "explanations": {"不加": "正确：不加（bù jiā），意思是做饮食时不放入某种东西。", "附加": "fù（第四声）与 bù（第四声）声母不同（f 与 b），意思是额外添上，与“不放入”不同。", "不假": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是不是假的、真实的。", "补假": "bǔ（第三声）与 bù（第四声）、jià（第四声）与 jiā（第一声）声调都不同，意思是补休的假期。"}, "sentence_index": null, "correct_answer": "不加"}, "level_3": {"options": [{"text": "不加", "is_correct": true, "explanation": "正确。“我的咖啡不加糖”说的是咖啡里不放糖。"}, {"text": "不喝", "is_correct": false, "explanation": "搭配：咖啡是用来喝的，“喝糖”不能说，句子不通。"}, {"text": "不吃", "is_correct": false, "explanation": "语义：“吃”指吃固体食物，糖溶在咖啡里不能用“吃”。"}, {"text": "不切", "is_correct": false, "explanation": "搭配：“切”针对可以切开的固体，咖啡里的糖不能说“切”。"}], "explanations": {"不加": "正确。“我的咖啡不加糖”说的是咖啡里不放糖。", "不喝": "搭配：咖啡是用来喝的，“喝糖”不能说，句子不通。", "不吃": "语义：“吃”指吃固体食物，糖溶在咖啡里不能用“吃”。", "不切": "搭配：“切”针对可以切开的固体，咖啡里的糖不能说“切”。"}, "sentence_index": 0, "correct_answer": "不加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "衣柜里不加樟脑丸。", "explanation": "这里应该用〈放〉。“不加”只用于往食物或饮品里添入配料，把樟脑丸放进衣柜要用“放”。"}, {"text": "书包里不加饮料。", "explanation": "这里应该用〈放〉。“不加”指往食物或饮品里添入配料，往书包里装东西要用“放”。"}, {"text": "垃圾不加进垃圾桶里。", "explanation": "这里应该用〈扔〉。“不加进”指往食物或饮品里添入配料，把垃圾投进垃圾桶要用“扔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92975, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不加", "is_correct": true, "explanation": "正确：不加（bù jiā），意思是做饮食时不放入某种东西。"}, {"text": "富家", "is_correct": false, "explanation": "fù（第四声）与 bù（第四声）声母不同（f 与 b），意思是有钱人家。"}, {"text": "补价", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）、jià（第四声）与 jiā（第一声）声调都不同，意思是补偿的差价。"}, {"text": "布甲", "is_correct": false, "explanation": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是用布制成的护甲。"}], "explanations": {"不加": "正确：不加（bù jiā），意思是做饮食时不放入某种东西。", "富家": "fù（第四声）与 bù（第四声）声母不同（f 与 b），意思是有钱人家。", "补价": "bǔ（第三声）与 bù（第四声）、jià（第四声）与 jiā（第一声）声调都不同，意思是补偿的差价。", "布甲": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是用布制成的护甲。"}, "sentence_index": null, "correct_answer": "不加"}, "level_3": {"options": [{"text": "不加", "is_correct": true, "explanation": "正确。“做蛋糕可以不加香草吗”问的是能否不放香草。"}, {"text": "不啃", "is_correct": false, "explanation": "搭配：香草不是可以啃的东西，做蛋糕时不说“啃”香草。"}, {"text": "不吞", "is_correct": false, "explanation": "语义：“吞”指整个咽下，香草不会被吞进蛋糕里。"}, {"text": "不嚼", "is_correct": false, "explanation": "搭配：“嚼”针对在口中咀嚼的食物，做蛋糕时不说嚼香草。"}], "explanations": {"不加": "正确。“做蛋糕可以不加香草吗”问的是能否不放香草。", "不啃": "搭配：香草不是可以啃的东西，做蛋糕时不说“啃”香草。", "不吞": "语义：“吞”指整个咽下，香草不会被吞进蛋糕里。", "不嚼": "搭配：“嚼”针对在口中咀嚼的食物，做蛋糕时不说嚼香草。"}, "sentence_index": 6, "correct_answer": "不加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "米饭不加进碗里。", "explanation": "这里应该用〈盛〉。把米饭装进碗里要用“盛”，“不加”只指往食物或饮品里添入配料。"}, {"text": "这本书我不加在书架上。", "explanation": "这里应该用〈摆〉。把书放在书架上要用“摆”或“放”，“不加”只用于往食物或饮品里添加东西，不能表示摆放。"}, {"text": "我出门从来不加伞。", "explanation": "这里应该用〈带〉。出门随身带伞要用“带”，“不加”指往食物或饮品里放入东西，不能替代“带”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92975, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我现在的咖啡不加了糖。", "corrected_sentence": "我现在的咖啡不加糖了。", "error_description": "“了”的位置错误。“不加糖了”表示以后不再加糖，是正确说法；“不加了糖”中的“了”放错位置，不能这样说。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92975, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冰淇淋可以不加过糖吗？", "corrected_sentence": "冰淇淋可以不加糖吗？", "error_description": "“过”用错。“不加”后直接接宾语“糖”，不能再带“过”，应说“可以不加糖吗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92976, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92976, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92976, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不加以（后接双音节动词，表示不对其作某种处理）。", "primary_collocate": null, "pronunciation": "bù jiā", "ipa": "pu˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "他不加证实就把消息发了出去。", "target_word": "不加", "complexity_tier": "T3", "furigana": "tā bù jiā zhèngshí jiù bǎ xiāoxi fā le chūqù", "sentence_source": "generated"}, {"text": "不要不加选择地相信网上的消息。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不加掩饰地说出了想法。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对学生不加区别，一视同仁。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能不加考虑就做决定。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不加解释就走了。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些话他不加修饰地写了下来。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要不加分析地接受别人的意见。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不加犹豫地跳进水里。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这件事，大家不加评论。", "target_word": "不加", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "后接双音节动词，表示不对其作某种处理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5defac78-781a-4fa9-9921-04631e3ba9d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92976, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不加", "is_correct": true, "explanation": "正确：不加（bù jiā），意思是不做某种处理。"}, {"text": "附加", "is_correct": false, "explanation": "fù（第四声）与 bù（第四声）声母不同（f 与 b），意思是额外添上，与“不做处理”不同。"}, {"text": "不假", "is_correct": false, "explanation": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是不是假的、真实的。"}, {"text": "补假", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）、jià（第四声）与 jiā（第一声）声调都不同，意思是补休的假期。"}], "explanations": {"不加": "正确：不加（bù jiā），意思是不做某种处理。", "附加": "fù（第四声）与 bù（第四声）声母不同（f 与 b），意思是额外添上，与“不做处理”不同。", "不假": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是不是假的、真实的。", "补假": "bǔ（第三声）与 bù（第四声）、jià（第四声）与 jiā（第一声）声调都不同，意思是补休的假期。"}, "sentence_index": null, "correct_answer": "不加"}, "level_3": {"options": [{"text": "不加", "is_correct": true, "explanation": "正确。“不加证实”表示不经过核实就把消息发出去。"}, {"text": "不唱", "is_correct": false, "explanation": "语义：“唱”不能与“证实”搭配，句子不通。"}, {"text": "不吃", "is_correct": false, "explanation": "搭配：“吃”指进食，不能用于“证实”这种行为。"}, {"text": "不喝", "is_correct": false, "explanation": "搭配：“喝”针对饮品，“喝证实”不成立。"}], "explanations": {"不加": "正确。“不加证实”表示不经过核实就把消息发出去。", "不唱": "语义：“唱”不能与“证实”搭配，句子不通。", "不吃": "搭配：“吃”指进食，不能用于“证实”这种行为。", "不喝": "搭配：“喝”针对饮品，“喝证实”不成立。"}, "sentence_index": 0, "correct_answer": "不加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不加朋友的意见，一意孤行。", "explanation": "这里应该用〈不采纳〉。“不加”表示不做某种处理，后接动词；“意见”是名词，不能直接放在“不加”后面。"}, {"text": "他不加后果就冲了出去。", "explanation": "这里应该用〈不顾〉。“不加”后要接动词，表示不做某种处理；“后果”是名词，要说“不顾后果”。"}, {"text": "他不加时间地工作。", "explanation": "这里应该用〈不计〉。“不加”后要接动词，“时间”是名词，要说“不计时间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92976, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不加", "is_correct": true, "explanation": "正确：不加（bù jiā），意思是不做某种处理。"}, {"text": "富家", "is_correct": false, "explanation": "fù（第四声）与 bù（第四声）声母不同（f 与 b），意思是有钱人家。"}, {"text": "补价", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）、jià（第四声）与 jiā（第一声）声调都不同，意思是补偿的差价。"}, {"text": "布甲", "is_correct": false, "explanation": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是用布做的护甲。"}], "explanations": {"不加": "正确：不加（bù jiā），意思是不做某种处理。", "富家": "fù（第四声）与 bù（第四声）声母不同（f 与 b），意思是有钱人家。", "补价": "bǔ（第三声）与 bù（第四声）、jià（第四声）与 jiā（第一声）声调都不同，意思是补偿的差价。", "布甲": "jiǎ（第三声）与 jiā（第一声）声调不同，意思是用布做的护甲。"}, "sentence_index": null, "correct_answer": "不加"}, "level_3": {"options": [{"text": "不加", "is_correct": true, "explanation": "正确。“不加修饰”表示不经过修饰就写下来。"}, {"text": "不穿", "is_correct": false, "explanation": "语义：“穿”指穿戴衣物，“修饰”不能穿，句子不通。"}, {"text": "不擦", "is_correct": false, "explanation": "搭配：“擦”针对可以擦掉的东西，“擦修饰”不能说。"}, {"text": "不剪", "is_correct": false, "explanation": "搭配：“剪”针对可以剪断的东西，“修饰”不能剪。"}], "explanations": {"不加": "正确。“不加修饰”表示不经过修饰就写下来。", "不穿": "语义：“穿”指穿戴衣物，“修饰”不能穿，句子不通。", "不擦": "搭配：“擦”针对可以擦掉的东西，“擦修饰”不能说。", "不剪": "搭配：“剪”针对可以剪断的东西，“修饰”不能剪。"}, "sentence_index": 6, "correct_answer": "不加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不加允许就进了办公室。", "explanation": "这里应该用〈不经〉。“不加”后要接动词，不能接“允许”这样的名词，要说“不经允许”。"}, {"text": "老师不加学生的感受，一味批评。", "explanation": "这里应该用〈不理〉。“不加”表示不做某种处理，后接动词，不能接“学生的感受”。"}, {"text": "他对谁都不加彼此。", "explanation": "这里应该用〈不分〉。“不加”后要接动词，不能接“彼此”，要说“不分彼此”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不加了审查就把文件交了上去。", "corrected_sentence": "他不加审查就把文件交了上去。", "error_description": "“了”的位置错误。“不加”后接动词“审查”时不能带“了”，应说“不加审查”；“不加了审查”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不加核实过就把数据交了上去。", "corrected_sentence": "他不加核实就把数据交了上去。", "error_description": "“过”用错。“不加”后接动词“核实”时不能再带“过”，应说“他不加核实就把数据交了上去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
