INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92981, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心灵是人心里想的和感觉的地方。", "primary_collocate": null, "pronunciation": "xīn líng", "ipa": "ɕin˥ liŋ˧˥", "syllable_count": 2, "sentences": [{"text": "好的音乐能让心灵安静下来。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的心灵像一张白纸。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把心里话写下来，心灵轻松多了。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书走进了我的心灵。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的话温暖了我的心灵。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在山里住几天，心灵会变得很平静。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的心灵一直很害怕。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼睛是心灵的窗户。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到这幅画，我的心灵很受感动。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏消息伤了她的心灵。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "心灵深处", "label": "复合"}, {"form": "心灵手巧", "label": "复合"}, {"form": "心靈", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人心里想事情、感受事情的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f97b0b77-31da-4084-a328-b98e8987af04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92981, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心灵", "is_correct": true, "explanation": "心灵指人的内心，能够安静下来，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有感受，不能因音乐而安静下来。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有感受，不能因音乐而安静下来。"}, {"text": "牙齿", "is_correct": false, "explanation": "搭配：“安静”不用于形容牙齿。"}], "explanations": {"心灵": "心灵指人的内心，能够安静下来，符合句意。", "桌子": "语义：桌子没有感受，不能因音乐而安静下来。", "石头": "语义：石头没有感受，不能因音乐而安静下来。", "牙齿": "搭配：“安静”不用于形容牙齿。"}, "sentence_index": 0, "correct_answer": "心灵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的心灵跳得很快。", "explanation": "这里应该用〈心脏〉。心灵指人的内心和精神，不能说它跳动。"}, {"text": "他的心灵每天需要吃三顿饭。", "explanation": "这里应该用〈身体〉。心灵指内心和精神，不指需要吃饭的身体。"}, {"text": "这台心灵的内存很大。", "explanation": "这里应该用〈电脑〉。心灵指人的内心，不能指机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92981, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心灵", "is_correct": true, "explanation": "心灵指人的内心，可以有悲伤等感受，符合“深处一直很害怕”。"}, {"text": "头发", "is_correct": false, "explanation": "语义：头发没有情绪，不会害怕。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户没有情绪，不会害怕。"}, {"text": "手指", "is_correct": false, "explanation": "语义：手指没有情绪，不会害怕。"}], "explanations": {"心灵": "心灵指人的内心，可以有悲伤等感受，符合“深处一直很害怕”。", "头发": "语义：头发没有情绪，不会害怕。", "窗户": "语义：窗户没有情绪，不会害怕。", "手指": "语义：手指没有情绪，不会害怕。"}, "sentence_index": 6, "correct_answer": "心灵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "紫外线晒伤了她的心灵。", "explanation": "这里应该用〈皮肤〉。心灵指内心和精神，不会被晒伤。"}, {"text": "护士给病人抽了心灵。", "explanation": "这里应该用〈血〉。抽取的是血，心灵不能被抽取。"}, {"text": "工人修好了汽车的心灵。", "explanation": "这里应该用〈发动机〉。心灵指人的内心，不是汽车的部件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只纯洁的心灵。", "corrected_sentence": "这是一个纯洁的心灵。", "error_description": "错误形式是量词“只”，正确形式是“个”。“只”用于动物，心灵应用通用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多人的心灵们都很纯洁。", "corrected_sentence": "很多人的心灵都很纯洁。", "error_description": "错误形式是在“心灵”后加“们”，正确形式是“心灵”不加“们”。“们”只用于指人的复数，不能加在“心灵”后表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
