INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92982, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人的内心、精神和思想感情。", "primary_collocate": null, "pronunciation": "xīn líng", "ipa": "ɕin˥ liŋ˧˥", "syllable_count": 2, "sentences": [{"text": "她的心灵很美。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师很关心学生的心灵健康。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书可以让人的心灵更丰富。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争给孩子的心灵留下了伤痛。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一个心灵很纯洁的人。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家写出了普通人的心灵世界。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐可以安慰人的心灵。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的心灵受过很大的伤害。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要多读书，让心灵更干净。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影让很多人的心灵得到了安慰。", "target_word": "心灵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "心灵深处", "label": "复合"}, {"form": "心灵手巧", "label": "复合"}, {"form": "心靈", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人的内心、精神和思想感情的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f97b0b77-31da-4084-a328-b98e8987af04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心灵", "is_correct": true, "explanation": "心灵指人的内心和精神，可以用“美”来形容，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“美”不用来形容体重。"}, {"text": "血压", "is_correct": false, "explanation": "语义：血压是生理指标，没有美丑之分。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：成绩多说“好”，不说“美”。"}], "explanations": {"心灵": "心灵指人的内心和精神，可以用“美”来形容，符合句意。", "体重": "搭配：“美”不用来形容体重。", "血压": "语义：血压是生理指标，没有美丑之分。", "成绩": "搭配：成绩多说“好”，不说“美”。"}, "sentence_index": 0, "correct_answer": "心灵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃得太多让他的心灵长胖了。", "explanation": "这里应该用〈身体〉。长胖指身体，心灵指内心和精神，不能说长胖。"}, {"text": "理发师剪短了她的心灵。", "explanation": "这里应该用〈头发〉。被剪短的是头发，心灵不能被剪。"}, {"text": "他用心灵咬碎了饼干。", "explanation": "这里应该用〈牙齿〉。咬东西要用牙齿，心灵是内心，不能用来咬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心灵", "is_correct": true, "explanation": "心灵指人的内心和思想感情，音乐可以安慰它，符合句意。"}, {"text": "肚子", "is_correct": false, "explanation": "语义：肚子没有感情，不需要音乐的安慰。"}, {"text": "脚趾", "is_correct": false, "explanation": "语义：脚趾没有感受，不会因音乐得到安慰。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“安慰”的对象是人或情绪，不说安慰眼泪。"}], "explanations": {"心灵": "心灵指人的内心和思想感情，音乐可以安慰它，符合句意。", "肚子": "语义：肚子没有感情，不需要音乐的安慰。", "脚趾": "语义：脚趾没有感受，不会因音乐得到安慰。", "眼泪": "搭配：“安慰”的对象是人或情绪，不说安慰眼泪。"}, "sentence_index": 6, "correct_answer": "心灵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生切除了他的心灵。", "explanation": "这里应该用〈肾〉。切除的是器官，心灵是内心和精神，不能被切除。"}, {"text": "他把心灵剪短了。", "explanation": "这里应该用〈指甲〉。剪的是指甲，心灵不能被剪短。"}, {"text": "他给手机换了心灵。", "explanation": "这里应该用〈电池〉。换的是电池，心灵是人的内心，不能用于手机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人的心灵们很宁静。", "corrected_sentence": "这位老人的心灵很宁静。", "error_description": "错误形式是在“心灵”后加“们”，正确形式是“心灵”不加“们”。“心灵”不能通过加“们”表示复数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一把善良的心灵。", "corrected_sentence": "这是一颗善良的心灵。", "error_description": "错误形式是量词“把”，正确形式是“颗”。“把”用于有柄的器具，心灵应用“颗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
