INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92987, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "排是把人或东西一个挨着一个放好。", "primary_collocate": null, "pronunciation": "pái", "ipa": "pʰai˧˥", "syllable_count": 1, "sentences": [{"text": "请把桌子排成一行。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在门口排成一行。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把鞋子排在门口。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让大家排成两行。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把书一本一本排好了。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把砖排得很整齐。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把椅子排好。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们排成三行，走进教室。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把几个杯子排在桌子上。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把花盆排在窗边吧。", "target_word": "排", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排了", "label": "完成体"}, {"form": "排着", "label": "持续体"}, {"form": "排过", "label": "经历体"}, {"form": "排好", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "把人或东西一个挨着一个放成一行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f97b0b77-31da-4084-a328-b98e8987af04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92987, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "排", "is_correct": true, "explanation": "排 pái（第二声）是正确答案，意思是把人或东西挨着摆放。"}, {"text": "拍", "is_correct": false, "explanation": "拍 pāi（第一声）与 pái（第二声）声调不同，意思是拍打。"}, {"text": "怕", "is_correct": false, "explanation": "怕 pà（第四声）与 pái（第二声）声调不同，意思是害怕。"}, {"text": "派", "is_correct": false, "explanation": "派 pài（第四声）与 pái（第二声）声调不同，意思是派遣。"}, {"text": "盘", "is_correct": false, "explanation": "盘 pán 与 pái 韵母不同（an 与 ai），意思是盘子。"}, {"text": "白", "is_correct": false, "explanation": "白 bái 与 pái 声母不同（b 与 p），意思是白色。"}], "explanations": {"排": "排 pái（第二声）是正确答案，意思是把人或东西挨着摆放。", "拍": "拍 pāi（第一声）与 pái（第二声）声调不同，意思是拍打。", "怕": "怕 pà（第四声）与 pái（第二声）声调不同，意思是害怕。", "派": "派 pài（第四声）与 pái（第二声）声调不同，意思是派遣。", "盘": "盘 pán 与 pái 韵母不同（an 与 ai），意思是盘子。", "白": "白 bái 与 pái 声母不同（b 与 p），意思是白色。"}, "sentence_index": null, "correct_answer": "排"}, "level_3": {"options": [{"text": "排", "is_correct": true, "explanation": "排是把东西挨着摆成行列，“排成一行”正确，符合句意。"}, {"text": "画", "is_correct": false, "explanation": "语义：画指用笔描绘，不能让桌子变成一行。"}, {"text": "跑", "is_correct": false, "explanation": "配价：跑是不及物动词，不能带“桌子”作宾语，“把桌子跑”不成立。"}, {"text": "叠", "is_correct": false, "explanation": "搭配：叠指一层层堆起，不说“叠成一行”。"}], "explanations": {"排": "排是把东西挨着摆成行列，“排成一行”正确，符合句意。", "画": "语义：画指用笔描绘，不能让桌子变成一行。", "跑": "配价：跑是不及物动词，不能带“桌子”作宾语，“把桌子跑”不成立。", "叠": "搭配：叠指一层层堆起，不说“叠成一行”。"}, "sentence_index": 0, "correct_answer": "排"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把乱糟糟的房间排干净了。", "explanation": "这里应该用〈整理〉。排指把人或东西挨着摆成行列，不能用来收拾房间。"}, {"text": "他把垃圾排进了垃圾桶。", "explanation": "这里应该用〈扔〉。排指摆成行列，不表示把东西丢掉。"}, {"text": "他把文件排到了老板手里。", "explanation": "这里应该用〈交〉或〈递〉。排指按次序摆放，不表示把东西送到别人手里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92987, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "排", "is_correct": true, "explanation": "排 pái（第二声）是正确答案，意思是把人或东西挨着摆放。"}, {"text": "爬", "is_correct": false, "explanation": "爬 pá 与 pái 韵母不同（a 与 ai），意思是爬行。"}, {"text": "台", "is_correct": false, "explanation": "台 tái 与 pái 声母不同（t 与 p），意思是台子。"}, {"text": "埋", "is_correct": false, "explanation": "埋 mái 与 pái 声母不同（m 与 p），意思是埋藏。"}, {"text": "陪", "is_correct": false, "explanation": "陪 péi 与 pái 韵母不同（ei 与 ai），意思是陪伴。"}], "explanations": {"排": "排 pái（第二声）是正确答案，意思是把人或东西挨着摆放。", "爬": "爬 pá 与 pái 韵母不同（a 与 ai），意思是爬行。", "台": "台 tái 与 pái 声母不同（t 与 p），意思是台子。", "埋": "埋 mái 与 pái 声母不同（m 与 p），意思是埋藏。", "陪": "陪 péi 与 pái 韵母不同（ei 与 ai），意思是陪伴。"}, "sentence_index": null, "correct_answer": "排"}, "level_3": {"options": [{"text": "排", "is_correct": true, "explanation": "“排好”是把椅子按要求摆整齐，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：吃的宾语须是食物，不能说吃椅子。"}, {"text": "跳", "is_correct": false, "explanation": "配价：跳是不及物动词，不能带“椅子”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱指发声唱歌，与摆放椅子无关。"}], "explanations": {"排": "“排好”是把椅子按要求摆整齐，符合句意。", "吃": "搭配：吃的宾语须是食物，不能说吃椅子。", "跳": "配价：跳是不及物动词，不能带“椅子”作宾语。", "唱": "语义：唱指发声唱歌，与摆放椅子无关。"}, "sentence_index": 6, "correct_answer": "排"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把水排在了桌子上。", "explanation": "这里应该用〈倒〉。排用于一个挨着一个摆放的人或成件东西，液体不能这样排列。"}, {"text": "我把钥匙排进了口袋。", "explanation": "这里应该用〈放〉。排要求一个挨着一个摆成行列，单件东西放进口袋不能说排。"}, {"text": "我们把行李排上了车。", "explanation": "这里应该用〈装〉。排指摆成行列，不表示把行李搬上车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92987, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们把操场上排成两行。", "corrected_sentence": "同学们在操场上排成两行。", "error_description": "错误：“把”后面的场所“操场上”不能作受事，场所要用“在”引出。正确形式是“在操场上排成两行”。排的是人，场所不能作“把”的宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92987, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把鸡蛋一个一个排了好。", "corrected_sentence": "她把鸡蛋一个一个排好了。", "error_description": "错误形式是“排了好”，正确形式是“排好了”。结果补语“好”要紧跟在“排”后面，“了”放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
