INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92991, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "据说是听别人这样说，不一定亲眼看到。", "primary_collocate": null, "pronunciation": "jù shuō", "ipa": "tɕy˥˩ ʂwo˥", "syllable_count": 2, "sentences": [{"text": "据说那家店的面条很好吃。", "target_word": "据说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据说明天会下大雨，你带伞吧。", "target_word": "据说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据说他小时候住在北京，我没去过他家。", "target_word": "据说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据说这个城市以前很小，我没亲眼看过。", "target_word": "据说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据说老师下个月要去美国。", "target_word": "据说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据说这本书很有意思，但我还没看。", "target_word": "据说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据说那里的冬天特别冷，我没去过。", "target_word": "据说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据说他会说五种语言，我不太相信。", "target_word": "据说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据说新来的同事是上海人。", "target_word": "据说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据说昨天晚上这里来了很多人，可是我不在。", "target_word": "据说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "据说：转述听来的消息，自己没有亲眼看到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80dc076e-16c3-467f-b99b-92db9f5b2db7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92991, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "据说", "is_correct": true, "explanation": "“据说”指听别人这样说，不一定亲眼看到，即本词条。"}, {"text": "叙说", "is_correct": false, "explanation": "xù 与 jù 声母不同（x/j），意思是叙述、讲述。"}, {"text": "旧说", "is_correct": false, "explanation": "jiù 与 jù 韵母不同（多一个 i），意思是过去的说法。"}, {"text": "巨树", "is_correct": false, "explanation": "shù 与 shuō 的韵母和声调都不同，意思是高大的树。"}], "explanations": {"据说": "“据说”指听别人这样说，不一定亲眼看到，即本词条。", "叙说": "xù 与 jù 声母不同（x/j），意思是叙述、讲述。", "旧说": "jiù 与 jù 韵母不同（多一个 i），意思是过去的说法。", "巨树": "shù 与 shuō 的韵母和声调都不同，意思是高大的树。"}, "sentence_index": null, "correct_answer": "据说"}, "level_3": {"options": [{"text": "据说", "is_correct": true, "explanation": "“据说”表示听别人说的，与句中的转述语境相符。"}, {"text": "闻", "is_correct": false, "explanation": "搭配：“闻”感知的是气味，“很好吃”说的是味道，不能搭配。"}, {"text": "验证", "is_correct": false, "explanation": "语义：“验证”指查证事实，与“听别人说”的转述语境不符。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示反感，与“很好吃”的赞美语气相矛盾。"}], "explanations": {"据说": "“据说”表示听别人说的，与句中的转述语境相符。", "闻": "搭配：“闻”感知的是气味，“很好吃”说的是味道，不能搭配。", "验证": "语义：“验证”指查证事实，与“听别人说”的转述语境不符。", "讨厌": "语义：“讨厌”表示反感，与“很好吃”的赞美语气相矛盾。"}, "sentence_index": 0, "correct_answer": "据说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "据说我亲眼看见了那场比赛，当时就坐在第一排。", "explanation": "“据说”只用于转述听来的消息；自己亲眼看见的事应直接说“我亲眼看见”，不用〈据说〉。"}, {"text": "据说我已经决定明天去北京，这是我自己的计划。", "explanation": "“据说”用于转述别人的说法；自己做的决定应直接陈述，不用〈据说〉。"}, {"text": "据说我的名字叫王明，这是我从小就知道的。", "explanation": "“据说”表示听来的消息；本人从小就知道的事不能用它来转述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '974c070f-760d-4dc6-a020-4dcb3fc1bbd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92991, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "据说", "is_correct": true, "explanation": "“据说”指听别人这样说，不一定亲眼看到，即本词条。"}, {"text": "句数", "is_correct": false, "explanation": "shù 与 shuō 的韵母和声调不同，意思是句子的数量。"}, {"text": "就说", "is_correct": false, "explanation": "jiù 与 jù 韵母不同（多一个 i），意思是就这样说。"}, {"text": "絮说", "is_correct": false, "explanation": "xù 与 jù 声母不同（x/j），意思是啰嗦地说。"}], "explanations": {"据说": "“据说”指听别人这样说，不一定亲眼看到，即本词条。", "句数": "shù 与 shuō 的韵母和声调不同，意思是句子的数量。", "就说": "jiù 与 jù 韵母不同（多一个 i），意思是就这样说。", "絮说": "xù 与 jù 声母不同（x/j），意思是啰嗦地说。"}, "sentence_index": null, "correct_answer": "据说"}, "level_3": {"options": [{"text": "据说", "is_correct": true, "explanation": "“据说”表示听别人说的，与“我没去过”的语境相符。"}, {"text": "感受", "is_correct": false, "explanation": "语义：“感受”需要亲身经历，与“我没去过”矛盾。"}, {"text": "亲历", "is_correct": false, "explanation": "语域：“亲历”偏书面，与口语化的“我没去过”不协调。"}, {"text": "目睹", "is_correct": false, "explanation": "语义：“目睹”指亲眼看见，与“我没去过”矛盾。"}], "explanations": {"据说": "“据说”表示听别人说的，与“我没去过”的语境相符。", "感受": "语义：“感受”需要亲身经历，与“我没去过”矛盾。", "亲历": "语域：“亲历”偏书面，与口语化的“我没去过”不协调。", "目睹": "语义：“目睹”指亲眼看见，与“我没去过”矛盾。"}, "sentence_index": 6, "correct_answer": "据说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "据说这份报告的数据我们都核对过，销量增长了三成。", "explanation": "“据说”表示听别人说的；自己核对过的数据应直接陈述，不用〈据说〉。"}, {"text": "据说我的生日就在明天，我自己最清楚。", "explanation": "“据说”表示听别人说的；自己的生日应直接陈述，不用〈据说〉。"}, {"text": "据说我今天很开心，因为刚刚拿到了好成绩。", "explanation": "“据说”用于转述别人的话；自己的心情应直接说，不用〈据说〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '974c070f-760d-4dc6-a020-4dcb3fc1bbd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92991, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "据说了明天下午有会议，你准备一下吧。", "corrected_sentence": "据说明天下午有会议，你准备一下吧。", "error_description": "“据说”后面不能加“了”。正确的说法是“据说明天下午有会议”。“据说”是转述听来的消息，后面直接接所转述的内容。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '974c070f-760d-4dc6-a020-4dcb3fc1bbd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92991, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "据说的明天会有雨，记得带伞。", "corrected_sentence": "据说明天会有雨，记得带伞。", "error_description": "“据说”后面不能直接加“的”。正确的说法是“据说明天会有雨”。“据说”是转述词，后面直接接所转述的内容。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '974c070f-760d-4dc6-a020-4dcb3fc1bbd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
