INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93001, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "看见老朋友，我忍不住不禁伸手拥抱了他。", "corrected_sentence": "看见老朋友，我不禁伸手拥抱了他。", "error_description": "重复：“忍不住”与“不禁”意思相同，不能叠用，应只用“我不禁伸手拥抱了他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
