INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93002, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "抑制不住；情不自禁地。", "primary_collocate": null, "pronunciation": "bù jīn", "ipa": "pu˥˩ tɕin˥", "syllable_count": 2, "sentences": [{"text": "听到这个好消息，他不禁笑了起来。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着孩子的照片，妈妈不禁流下了眼泪。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在高山上，我不禁大声喊了起来。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到那首老歌，她不禁想起了小时候。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到老朋友，他不禁高兴地跳了起来。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走进这座老房子，我不禁想起了奶奶。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到他的样子，大家不禁笑出了声。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读着这封信，她不禁哭了。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对美丽的大海，他不禁赞叹起来。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回头看看走过的路，他不禁感慨万分。", "target_word": "不禁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "受到触动后，感情或反应抑制不住地出现，情不自禁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e983dcc6-3418-42fd-ac27-a2db7eba3cd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93002, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不禁", "is_correct": true, "explanation": "正确答案：不禁（bù jīn）。"}, {"text": "不仅", "is_correct": false, "explanation": "jǐn（第三声）与 jīn（第一声）声调不同，意思是不但。"}, {"text": "不尽", "is_correct": false, "explanation": "jìn（第四声）与 jīn（第一声）声调不同，意思是没有止境。"}, {"text": "不精", "is_correct": false, "explanation": "jīng 与 jīn 韵尾不同（ng 与 n），意思是不精细。"}], "explanations": {"不禁": "正确答案：不禁（bù jīn）。", "不仅": "jǐn（第三声）与 jīn（第一声）声调不同，意思是不但。", "不尽": "jìn（第四声）与 jīn（第一声）声调不同，意思是没有止境。", "不精": "jīng 与 jīn 韵尾不同（ng 与 n），意思是不精细。"}, "sentence_index": null, "correct_answer": "不禁"}, "level_3": {"options": [{"text": "不禁", "is_correct": true, "explanation": "正确答案：不禁，指抑制不住而出现反应。"}, {"text": "从来", "is_correct": false, "explanation": "语法：“从来”表示一向如此，不能用于已发生的一次性动作“笑了起来”。"}, {"text": "千万", "is_correct": false, "explanation": "语法：“千万”多用于祈使或否定句，不能用于陈述已发生的“笑了起来”。"}, {"text": "别", "is_correct": false, "explanation": "语法：“别”是否定祈使词，不能用于陈述句中的“笑了起来”。"}], "explanations": {"不禁": "正确答案：不禁，指抑制不住而出现反应。", "从来": "语法：“从来”表示一向如此，不能用于已发生的一次性动作“笑了起来”。", "千万": "语法：“千万”多用于祈使或否定句，不能用于陈述已发生的“笑了起来”。", "别": "语法：“别”是否定祈使词，不能用于陈述句中的“笑了起来”。"}, "sentence_index": 0, "correct_answer": "不禁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这样做不禁会出错。", "explanation": "这里应该用〈不免〉。不免表示难免会发生某种结果，不禁表示抑制不住的情绪或动作，不能用于推测结果。"}, {"text": "做错事，不禁要挨骂。", "explanation": "这里应该用〈免不了〉。免不了表示必然会发生，不禁表示抑制不住，不能表示必然。"}, {"text": "他不禁赢了这场比赛。", "explanation": "这里应该用〈竟然〉。竟然表示出乎意料，不禁只用于抑制不住的情绪或动作，不能说明比赛结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93002, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不禁", "is_correct": true, "explanation": "正确答案：不禁（bù jīn）。"}, {"text": "不尽", "is_correct": false, "explanation": "jìn（第四声）与 jīn（第一声）声调不同，意思是没有止境。"}, {"text": "步进", "is_correct": false, "explanation": "jìn（第四声）与 jīn（第一声）声调不同，意思是一步步向前推进。"}, {"text": "不经", "is_correct": false, "explanation": "jīng 与 jīn 韵尾不同（ng 与 n），意思是不经过、不合常理。"}], "explanations": {"不禁": "正确答案：不禁（bù jīn）。", "不尽": "jìn（第四声）与 jīn（第一声）声调不同，意思是没有止境。", "步进": "jìn（第四声）与 jīn（第一声）声调不同，意思是一步步向前推进。", "不经": "jīng 与 jīn 韵尾不同（ng 与 n），意思是不经过、不合常理。"}, "sentence_index": null, "correct_answer": "不禁"}, "level_3": {"options": [{"text": "不禁", "is_correct": true, "explanation": "正确答案：不禁，指抑制不住而出现反应。"}, {"text": "悄悄", "is_correct": false, "explanation": "语义：“悄悄”表示无声进行，与“笑出了声”相矛盾。"}, {"text": "大力", "is_correct": false, "explanation": "搭配：“大力”多修饰支持、推动，不修饰“笑”。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒然、没有所得，与此处的情绪反应不合。"}], "explanations": {"不禁": "正确答案：不禁，指抑制不住而出现反应。", "悄悄": "语义：“悄悄”表示无声进行，与“笑出了声”相矛盾。", "大力": "搭配：“大力”多修饰支持、推动，不修饰“笑”。", "白白": "语义：“白白”表示徒然、没有所得，与此处的情绪反应不合。"}, "sentence_index": 6, "correct_answer": "不禁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天不禁会下雨。", "explanation": "这里应该用〈可能〉。可能表示有这种可能，不禁表示抑制不住的情绪或反应，不能用于对将来的推测。"}, {"text": "请你不禁离开这里。", "explanation": "这里应该用〈请〉。请表示礼貌地提出要求，不禁表示抑制不住的情绪或动作，不能用于请求。"}, {"text": "为了省钱，他不禁坐了公交车。", "explanation": "这里应该用〈只好〉。只好表示迫不得已只能如此，不禁表示抑制不住、忍不住做出某个动作，与“为了省钱”这种迫不得已的选择不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "看到孩子的成绩，爸爸很不禁露出了笑容。", "corrected_sentence": "看到孩子的成绩，爸爸不禁露出了笑容。", "error_description": "程度副词错误：“不禁”是副词，不能被“很”修饰，应去掉“很”，即“爸爸不禁露出了笑容”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "看着这张老照片，她忍不住不禁红了眼眶。", "corrected_sentence": "看着这张老照片，她不禁红了眼眶。", "error_description": "重复：“忍不住”与“不禁”意思相同，不能叠用，应只用“她不禁红了眼眶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
