INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93003, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "杀害是把人弄死。", "primary_collocate": null, "pronunciation": "shā hài", "ipa": "ʂa˥ xai˥˩", "syllable_count": 2, "sentences": [{"text": "那个坏人杀害了一位老人。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说，他杀害了自己的邻居。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因杀害朋友而被捕。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人知道是谁杀害了他。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察已经抓住了杀害三个人的坏人。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在找杀害那位女士的人。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了钱杀害了自己的亲戚。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官说他杀害别人，必须受到处罚。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个坏人杀害了他的父亲。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁杀害了这位老师？警方仍在调查。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "杀害了", "label": "完成体"}, {"form": "杀害过", "label": "经历体"}, {"form": "杀害者", "label": "复合"}, {"form": "殺害", "label": "繁体"}], "register": "书面", "sense_fingerprint": "非法地把人弄死，对象是人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f97b0b77-31da-4084-a328-b98e8987af04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93003, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "杀害", "is_correct": true, "explanation": "正确：杀害指把人弄死，与“坏人”的语境相符。"}, {"text": "救助", "is_correct": false, "explanation": "语义：救助是帮助人，与“坏人”的身份矛盾。"}, {"text": "拯救", "is_correct": false, "explanation": "语义：拯救是使人脱离危险，与“坏人”的身份矛盾。"}, {"text": "赡养", "is_correct": false, "explanation": "搭配：赡养多指子女供养父母，不用于坏人对陌生老人的行为。"}], "explanations": {"杀害": "正确：杀害指把人弄死，与“坏人”的语境相符。", "救助": "语义：救助是帮助人，与“坏人”的身份矛盾。", "拯救": "语义：拯救是使人脱离危险，与“坏人”的身份矛盾。", "赡养": "搭配：赡养多指子女供养父母，不用于坏人对陌生老人的行为。"}, "sentence_index": 0, "correct_answer": "杀害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种烟会杀害你的身体。", "explanation": "这里应该用〈伤害〉。伤害可用于身体、感情，杀害只用于人的死亡。"}, {"text": "农民每天杀害一块豆腐准备午饭。", "explanation": "这里应该用〈切〉。杀害的对象须是有生命的个体，豆腐不能被杀害。"}, {"text": "这场地震杀害了很多房子。", "explanation": "这里应该用〈摧毁〉。摧毁可用于房屋、建筑，杀害只用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93003, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杀害", "is_correct": true, "explanation": "正确：杀害指把人弄死，“为了钱”的动机与犯罪行为相符。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：怀念是思念，与“为了钱”的动机不符。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：祝贺多用于喜事，不能接“为了钱”的动机。"}, {"text": "感激", "is_correct": false, "explanation": "语义：感激是感谢，与“为了钱”的动机矛盾。"}], "explanations": {"杀害": "正确：杀害指把人弄死，“为了钱”的动机与犯罪行为相符。", "怀念": "语义：怀念是思念，与“为了钱”的动机不符。", "祝贺": "搭配：祝贺多用于喜事，不能接“为了钱”的动机。", "感激": "语义：感激是感谢，与“为了钱”的动机矛盾。"}, "sentence_index": 6, "correct_answer": "杀害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "消防员杀害了一位落水的小孩。", "explanation": "这里应该用〈救助〉。救助是帮助人脱离危险，杀害是把人弄死。"}, {"text": "工人杀害了几张桌子。", "explanation": "这里应该用〈拆〉。杀害的对象须是有生命的个体，桌子不能被杀害。"}, {"text": "小偷杀害了老太太的钱包。", "explanation": "这里应该用〈抢劫〉。抢劫的对象是财物，杀害的对象只能是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93003, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个小偷杀害死了一个路人。", "corrected_sentence": "那个小偷杀害了一个路人。", "error_description": "错误：“杀害死”，“杀害”已含“死”的意思，又加补语“死”，重复。正确是“杀害了一个路人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93003, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "凶手把杀害了一名商人，然后逃走了。", "corrected_sentence": "凶手杀害了一名商人，然后逃走了。", "error_description": "错误：“把”后直接接动词“杀害了”，没有受事，结构不成立。删去“把”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
