INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93004, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使人死亡，致人于死。", "primary_collocate": null, "pronunciation": "shā hài", "ipa": "ʂa˥ xai˥˩", "syllable_count": 2, "sentences": [{"text": "昨天夜里，有人杀害了这家的主人。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他杀害过人，要坐很多年牢。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了抢钱，他杀害了出租车司机。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个坏人杀害了两个孩子的妈妈。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有杀害那个女人，是警察弄错了。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察找到了杀害老板的刀。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杀害别人的人，一定会受到处罚。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想杀害自己的对手，但是没有成功。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院说他杀害了朋友，是有罪的。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位记者在国外遇到了坏人，他们杀害了他。", "target_word": "杀害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "杀害了", "label": "完成体"}, {"form": "杀害过", "label": "经历体"}, {"form": "杀害者", "label": "复合"}, {"form": "殺害", "label": "繁体"}], "register": "书面", "sense_fingerprint": "使人死亡，致人于死，多用于案件和新闻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f97b0b77-31da-4084-a328-b98e8987af04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93004, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "杀害", "is_correct": true, "explanation": "正确：杀害指使人死亡，与“昨天夜里”的案件语境相符。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理的对象是器物，不能用于“这家的主人”。"}, {"text": "训练", "is_correct": false, "explanation": "搭配：训练多用于动物或学员，不说“训练主人”。"}, {"text": "驯服", "is_correct": false, "explanation": "语义：驯服的对象是动物，不用于人。"}], "explanations": {"杀害": "正确：杀害指使人死亡，与“昨天夜里”的案件语境相符。", "修理": "语义：修理的对象是器物，不能用于“这家的主人”。", "训练": "搭配：训练多用于动物或学员，不说“训练主人”。", "驯服": "语义：驯服的对象是动物，不用于人。"}, "sentence_index": 0, "correct_answer": "杀害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "熬夜会杀害你的身体。", "explanation": "这里应该用〈伤害〉。伤害可用于身体，杀害只用于人的死亡。"}, {"text": "渔民每天杀害一块咸鱼当午饭。", "explanation": "这里应该用〈切〉。杀害的对象须是有生命的个体，咸鱼已不是活物。"}, {"text": "台风杀害了很多房子。", "explanation": "这里应该用〈摧毁〉。摧毁可用于房屋，杀害只用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杀害", "is_correct": true, "explanation": "正确：杀害指致人于死，“杀害别人的人，一定会受到处罚”符合语境。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：帮助别人的人不会受到处罚，与句子语境矛盾。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”的对象是施惠的人，“感谢别人的人受到处罚”搭配不当。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：夸奖别人的人不会受到处罚，与句子语境矛盾。"}], "explanations": {"杀害": "正确：杀害指致人于死，“杀害别人的人，一定会受到处罚”符合语境。", "帮助": "语义：帮助别人的人不会受到处罚，与句子语境矛盾。", "感谢": "搭配：“感谢”的对象是施惠的人，“感谢别人的人受到处罚”搭配不当。", "夸奖": "语义：夸奖别人的人不会受到处罚，与句子语境矛盾。"}, "sentence_index": 6, "correct_answer": "杀害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他杀害了一栋老房子。", "explanation": "这里应该用〈拆〉。拆用于房屋，杀害只用于把人弄死。"}, {"text": "这个病毒杀害了我的电脑。", "explanation": "这里应该用〈破坏〉。破坏可用于电脑，杀害只用于把人弄死。"}, {"text": "这部电影杀害了很多观众。", "explanation": "这里应该用〈感动〉。感动指使人情绪触动，杀害是把人弄死。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "凶手杀害死了一名女护士。", "corrected_sentence": "凶手杀害了一名女护士。", "error_description": "错误：“杀害死”，“杀害”已含“死”的意思，又加补语“死”，重复。正确是“杀害了一名女护士”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这名护士被了凶手杀害了。", "corrected_sentence": "这名护士被凶手杀害了。", "error_description": "错误：“被”与施事“凶手”之间多出“了”，被字句应为“被＋施事＋杀害”。正确形式是“这名护士被凶手杀害了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1dac96-4cc0-4b5f-a29e-c5b04f68b884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
