INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93012, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "等级、程度处于中间的。", "primary_collocate": null, "pronunciation": "zhōng děng", "ipa": "ʈʂʊŋ˥ təŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这次考试，他的成绩是中等。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的发展水平属于中等。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我国是中等收入国家。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店的价格是中等水平。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区的学校质量处于中等。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语水平只有中等。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批苹果的质量是中等的。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们队这学期的排名属于中等。", "target_word": "中等", "complexity_tier": "T3", "furigana": "wǒ men duì zhè xué qī de pái míng shǔ yú zhōng děng。", "sentence_source": "generated"}, {"text": "她的收入在全市算中等。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布的等级是中等。", "target_word": "中等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中等教育", "label": "复合"}, {"form": "中等收入", "label": "复合"}], "register": "中性", "sense_fingerprint": "水平、等级、质量等在上等和下等之间，处于中间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e983dcc6-3418-42fd-ac27-a2db7eba3cd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中等", "is_correct": true, "explanation": "正确。“中等”表示成绩处于中间的等级，与“成绩”搭配。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人的头脑，不能说成绩聪明。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容身材或外形，与成绩的等级无关。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”指没有污垢、整洁，与成绩的好坏无关。"}], "explanations": {"中等": "正确。“中等”表示成绩处于中间的等级，与“成绩”搭配。", "聪明": "搭配：“聪明”形容人的头脑，不能说成绩聪明。", "高大": "语义：“高大”形容身材或外形，与成绩的等级无关。", "干净": "语义：“干净”指没有污垢、整洁，与成绩的好坏无关。"}, "sentence_index": 0, "correct_answer": "中等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我坐在教室的中等位置，离黑板很远。", "explanation": "这里应该用〈中间〉。“中等”说等级、程度，不能用来指座位在教室里的位置。"}, {"text": "这次比赛的成绩中等，我们以全场最高分夺冠。", "explanation": "这里应该用〈优秀〉。“中等”表示居中，与“全场最高分”相矛盾。"}, {"text": "这家饭馆的菜价中等，却是全城最贵的。", "explanation": "这里应该用〈高〉。“中等”表示居中，与“全城最贵”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中等", "is_correct": true, "explanation": "正确。“中等”说质量的等级，与“这批苹果的质量”搭配。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”说温度或态度，不能用来说苹果的质量等级。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说年龄，苹果没有年龄，不能说质量年轻。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容人的态度，不能用来形容苹果的质量。"}], "explanations": {"中等": "正确。“中等”说质量的等级，与“这批苹果的质量”搭配。", "冰冷": "语义：“冰冷”说温度或态度，不能用来说苹果的质量等级。", "年轻": "语义：“年轻”说年龄，苹果没有年龄，不能说质量年轻。", "热情": "搭配：“热情”形容人的态度，不能用来形容苹果的质量。"}, "sentence_index": 6, "correct_answer": "中等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章的水平中等，却被评为全校第一。", "explanation": "这里应该用〈优秀〉。“中等”表示居中，与“全校第一”相矛盾。"}, {"text": "这份工作的待遇中等，却是公司里最高的一档。", "explanation": "这里应该用〈高〉。“中等”表示居中，与“最高的一档”相矛盾。"}, {"text": "听到这个消息，她心里很中等。", "explanation": "这里应该用〈悲伤〉。“中等”用于等级、程度，不能用来形容人的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件衣服的质量是中等得。", "corrected_sentence": "这件衣服的质量是中等的。", "error_description": "“的”误写为“得”。“中等”作表语，其后的结构助词应为“的”，应说“是中等的”；“得”接在动词或形容词后补充程度或结果，不能接在“中等”后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的规模属于中等地。", "corrected_sentence": "这家公司的规模属于中等。", "error_description": "“中等”作谓语（属于…）时不加“地”；“地”用在状语后修饰动词。应为“属于中等”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
