INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93015, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "主播是对着镜头讲话，让很多人在手机上看的人。", "primary_collocate": null, "pronunciation": "zhǔ bō", "ipa": "tʂu˨˩ pwo˥", "syllable_count": 2, "sentences": [{"text": "这个主播每晚在手机上直播唱歌。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很喜欢看那位卖水果的主播。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主播对着镜头，给大家介绍新买的鞋。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做主播两年了，粉丝越来越多。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位主播一开播，很多人就进来了。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥想当游戏主播，妈妈不同意。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主播笑着跟网友打招呼。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚那个主播送了粉丝一个小礼物。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个做饭的主播，菜做得特别好。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我关注了好几个旅游主播。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "网络直播里对着镜头讲话的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e983dcc6-3418-42fd-ac27-a2db7eba3cd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93015, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主播", "is_correct": true, "explanation": "正确。“主播”指在网上对着镜头直播的人，与“直播唱歌”搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会在手机上直播唱歌。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸不能直播唱歌。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不会在手机上直播唱歌。"}], "explanations": {"主播": "正确。“主播”指在网上对着镜头直播的人，与“直播唱歌”搭配。", "石头": "语义：石头不会在手机上直播唱歌。", "报纸": "语义：报纸不能直播唱歌。", "冰箱": "语义：冰箱不会在手机上直播唱歌。"}, "sentence_index": 0, "correct_answer": "主播"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个主播每天下午在篮球场上教孩子打篮球。", "explanation": "这里应该用〈教练〉。“主播”指对着镜头直播讲话的人，不能用来指在球场上训练运动员的人。"}, {"text": "这盆花是学校的主播，每天都很漂亮。", "explanation": "这里应该用〈植物〉。“主播”指对着镜头直播讲话的人，不能用来指一盆花。"}, {"text": "这块石头是我们班的主播，每天都很温柔。", "explanation": "这里应该用〈老师〉。“主播”指对着镜头直播讲话的人，不能用来指一块石头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93015, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主播", "is_correct": true, "explanation": "正确。“主播”指会笑、会打招呼的人，与“跟网友打招呼”搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会笑，也不会跟网友打招呼。"}, {"text": "雨", "is_correct": false, "explanation": "配价：“打招呼”要求有生命、能说话的人作主语，“雨”不能。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会笑，也不能打招呼。"}], "explanations": {"主播": "正确。“主播”指会笑、会打招呼的人，与“跟网友打招呼”搭配。", "桌子": "语义：桌子不会笑，也不会跟网友打招呼。", "雨": "配价：“打招呼”要求有生命、能说话的人作主语，“雨”不能。", "窗户": "语义：窗户不会笑，也不能打招呼。"}, "sentence_index": 6, "correct_answer": "主播"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这架钢琴是音乐会上的主播，很有名。", "explanation": "这里应该用〈乐器〉。“主播”指对着镜头直播讲话的人，不能用来指一架钢琴。"}, {"text": "我的邻居是个主播，每天负责给花园浇水。", "explanation": "这里应该用〈园丁〉。“主播”指对着镜头直播讲话的人，不能用来指负责浇花的人。"}, {"text": "我关注了好几个旅游主播，他们每天在工地上搬砖。", "explanation": "这里应该用〈工人〉。“主播”指对着镜头直播讲话的人，不能用来指在工地搬砖的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93015, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一个网络主播的，粉丝很多。", "corrected_sentence": "她是一个网络主播，粉丝很多。", "error_description": "“主播”后多加了“的”。应为“她是一个网络主播”；这里“的”后面没有中心语，句子不通，应删去“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93015, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多主播们都很专业。", "corrected_sentence": "很多主播都很专业。", "error_description": "“很多”已经表示数量，后面不能再加表示复数的“们”。应为“很多主播”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
