INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93016, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在电视、广播或网络直播中担任主持和播报的人。", "primary_collocate": null, "pronunciation": "zhǔ bō", "ipa": "tʂu˨˩ pwo˥", "syllable_count": 2, "sentences": [{"text": "这位主播每天晚上七点播报新闻。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台新来了一位年轻的主播。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当了十年主播，声音很好听。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主播在镜头前介绍今天的天气。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广播里的主播正在读一封听众来信。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个主播说话清楚，大家都爱听。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想长大以后做新闻主播。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会的主播穿着一件红色的衣服。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们电台最有名的主播。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位主播采访过很多有名的人。", "target_word": "主播", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "中性", "sense_fingerprint": "电视广播中主持播报的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e983dcc6-3418-42fd-ac27-a2db7eba3cd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主播", "is_correct": true, "explanation": "正确。“主播”指播报新闻的人，与“播报新闻”搭配。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师做饭，不播报新闻。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机开车，与播报新闻无关。"}, {"text": "作者", "is_correct": false, "explanation": "搭配：“播报”要求由播报人来读，“作者”是写作的人，不能说播报新闻。"}], "explanations": {"主播": "正确。“主播”指播报新闻的人，与“播报新闻”搭配。", "厨师": "语义：厨师做饭，不播报新闻。", "司机": "语义：司机开车，与播报新闻无关。", "作者": "搭配：“播报”要求由播报人来读，“作者”是写作的人，不能说播报新闻。"}, "sentence_index": 0, "correct_answer": "主播"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的邻居是个主播，每天晚上在街上巡逻。", "explanation": "这里应该用〈警察〉。“主播”指播报或直播节目的人，不能用来指巡逻的人。"}, {"text": "这次比赛由市政府主播。", "explanation": "这里应该用〈主办〉。“主播”是播报节目的人，不能用来说组织活动。"}, {"text": "这盏台灯是我们班的主播，每天都很温柔。", "explanation": "这里应该用〈老师〉。“主播”指播报节目的人，不能用来指一盏台灯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主播", "is_correct": true, "explanation": "正确。“主播”是职业名称，与“做新闻”搭配。"}, {"text": "医生", "is_correct": false, "explanation": "语义：“新闻”与医生无关，“做新闻医生”不成立。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“做”后接的是职业，“面包”不是职业，不能搭配。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎不是职业，不能说“做新闻老虎”。"}], "explanations": {"主播": "正确。“主播”是职业名称，与“做新闻”搭配。", "医生": "语义：“新闻”与医生无关，“做新闻医生”不成立。", "面包": "搭配：“做”后接的是职业，“面包”不是职业，不能搭配。", "老虎": "语义：老虎不是职业，不能说“做新闻老虎”。"}, "sentence_index": 6, "correct_answer": "主播"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的主播每天负责打扫教室。", "explanation": "这里应该用〈值日生〉。“主播”指在电视、广播或网络直播中播报节目的人，不能用来指负责打扫教室的人。"}, {"text": "我的表姐是个主播，每天在工厂里焊接零件。", "explanation": "这里应该用〈工人〉。“主播”指播报或直播节目的人，不能用来指在工厂里做工的人。"}, {"text": "他在音乐会上主播钢琴。", "explanation": "这里应该用〈演奏〉。“主播”指播报节目的人，不能用来说演奏乐器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐毕业后当了一只电视台的主播。", "corrected_sentence": "我姐姐毕业后当了一位电视台的主播。", "error_description": "“主播”指人，量词要用“位”或“个”，不能用“只”（“只”多用于动物或小东西）。应为“一位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位新闻主播们很有名。", "corrected_sentence": "这位新闻主播很有名。", "error_description": "“这位”指一个人，后面不能再加表示复数的“们”。应为“这位新闻主播”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
