INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93018, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用仪器或工具量出物体的大小、长短等。", "primary_collocate": null, "pronunciation": "cè liáng", "ipa": "tsʰɤ˥˩ ljɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "工程师用仪器测量这座山有多高。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用激光仪器测量两座楼之间的距离。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用专门的工具测量了这块石头的大小。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用仪器测量这条路有多长。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用显微镜测量细胞的大小。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用游标卡尺测量小球有多大。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技术员正在用仪器测量这根钢管的长度。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师用工具测量过河水有多宽。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员把仪器放在桥上，测量桥的长度。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器可以精确测量零件的大小。", "target_word": "测量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "测量了", "label": "体标（了）"}, {"form": "测量过", "label": "体标（过）"}, {"form": "测量员", "label": "复合词"}, {"form": "测量仪", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用仪器工具量出物体大小长短", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c66390e-ca93-402b-af4c-cf18df80027a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "测量", "is_correct": true, "explanation": "正确：“测量”指用仪器量出高度，与“用仪器”和“有多高”相符。"}, {"text": "称重", "is_correct": false, "explanation": "搭配：“称重”只用于称轻重，不能称山“有多高”。"}, {"text": "设计", "is_correct": false, "explanation": "语义：“设计”指构思规划，与用仪器量高度无关。"}, {"text": "修建", "is_correct": false, "explanation": "语义：“修建”指建造房屋或道路，山不能被修建，也不是量高度。"}], "explanations": {"测量": "正确：“测量”指用仪器量出高度，与“用仪器”和“有多高”相符。", "称重": "搭配：“称重”只用于称轻重，不能称山“有多高”。", "设计": "语义：“设计”指构思规划，与用仪器量高度无关。", "修建": "语义：“修建”指建造房屋或道路，山不能被修建，也不是量高度。"}, "sentence_index": 0, "correct_answer": "测量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工作人员测量了全市的人口数量。", "explanation": "这里应该用〈统计〉。测量指用工具量取长短大小，人口数量要用统计。"}, {"text": "财务人员测量了这笔工程的成本。", "explanation": "这里应该用〈核算〉。测量用于可以量出的长短、大小，工程成本要用核算。"}, {"text": "气象员测量了去年下雨的天数。", "explanation": "这里应该用〈记录〉。测量用于量取长短、大小等，下雨的天数要用记录。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b48ec5-fac0-442a-8ea9-648a718647c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "测量", "is_correct": true, "explanation": "正确：“测量”指用仪器量出长度，与“用仪器”和“这根钢管的长度”相符。"}, {"text": "焊接", "is_correct": false, "explanation": "语义：“焊接”是把金属连接起来，与量长度无关。"}, {"text": "弯曲", "is_correct": false, "explanation": "语义：“弯曲”是改变形状，不是测量长度。"}, {"text": "称", "is_correct": false, "explanation": "搭配：“称”只用于称重量，不能称“长度”。"}], "explanations": {"测量": "正确：“测量”指用仪器量出长度，与“用仪器”和“这根钢管的长度”相符。", "焊接": "语义：“焊接”是把金属连接起来，与量长度无关。", "弯曲": "语义：“弯曲”是改变形状，不是测量长度。", "称": "搭配：“称”只用于称重量，不能称“长度”。"}, "sentence_index": 6, "correct_answer": "测量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会计测量了今年的利润。", "explanation": "这里应该用〈计算〉。测量指用工具量出长短、大小等，利润要用计算。"}, {"text": "专家测量了这座古城的历史价值。", "explanation": "这里应该用〈评估〉。测量用于可以量出的实物，历史价值要用评估。"}, {"text": "我们测量了这套房子的价格。", "explanation": "这里应该用〈估计〉。测量得出的是确定的数据，价格的推断要用估计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b48ec5-fac0-442a-8ea9-648a718647c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位工程师用仪器测量了过这条河的宽度。", "corrected_sentence": "这位工程师用仪器测量过这条河的宽度。", "error_description": "错误在“测量”后的体标。“测量过”已用“过”表示经历，不能再加“了”，应说“测量过”，不能说“测量了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b48ec5-fac0-442a-8ea9-648a718647c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员用激光测量了出这块玻璃的厚度。", "corrected_sentence": "研究人员用激光测量出了这块玻璃的厚度。", "error_description": "补语“出”应紧跟在“测量”后面，说“测量出了”，不能说“测量了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b48ec5-fac0-442a-8ea9-648a718647c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93021, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平静", "is_correct": true, "explanation": "正确。「平静」与「激动」构成反义，指心情没有起伏。"}, {"text": "寒冷", "is_correct": false, "explanation": "无关：「寒冷」形容温度，与「激动」的情绪没有反义关系。"}, {"text": "坚硬", "is_correct": false, "explanation": "无关：「坚硬」形容质地，与「激动」没有任何反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "无关：「整齐」形容排列或状态，与「激动」不构成反义。"}], "correct_answer": "平静", "explanations": {"平静": "正确。「平静」与「激动」构成反义，指心情没有起伏。", "寒冷": "无关：「寒冷」形容温度，与「激动」的情绪没有反义关系。", "坚硬": "无关：「坚硬」形容质地，与「激动」没有任何反义关系。", "整齐": "无关：「整齐」形容排列或状态，与「激动」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93021, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平静", "is_correct": true, "explanation": "正确。「平静」与「激动」构成反义，指心情没有起伏。"}, {"text": "粗糙", "is_correct": false, "explanation": "无关：「粗糙」形容表面质感，与「激动」没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：「明亮」形容光线或颜色，与「激动」不构成反义。"}, {"text": "狭窄", "is_correct": false, "explanation": "无关：「狭窄」形容空间大小，与「激动」没有反义关系。"}], "correct_answer": "平静", "explanations": {"平静": "正确。「平静」与「激动」构成反义，指心情没有起伏。", "粗糙": "无关：「粗糙」形容表面质感，与「激动」没有反义关系。", "明亮": "无关：「明亮」形容光线或颜色，与「激动」不构成反义。", "狭窄": "无关：「狭窄」形容空间大小，与「激动」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93021, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "激动是心里特别高兴，跳得很快。", "primary_collocate": null, "pronunciation": "jī dòng", "ipa": "tɕi˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "听到好消息，他激动得一晚上没睡着。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天就要见到妈妈了，我心跳得很快，特别激动。", "target_word": "激动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次坐飞机，孩子激动极了。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拿到录取通知书，激动得哭了。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛马上开始，大家都很激动。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他激动地对我说：“我们赢了！”", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "站在演唱会门口，我激动得手都在发抖。", "target_word": "激动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天要见偶像，从早上就很激动。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我太激动了，一个字也说不出来。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看着手里的新手机，弟弟高兴又激动。", "target_word": "激动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "激动了", "label": "体标"}, {"form": "激动人心", "label": "复合"}, {"form": "激動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "遇到特别高兴的事，心跳加快，兴奋得难以平静", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf42e3e0-3aa5-4213-89fd-9bc9b80dff5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93021, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "激动", "is_correct": true, "explanation": "正确。「激动」表示因好消息而心情强烈起伏，兴奋得睡不着。"}, {"text": "伤心", "is_correct": false, "explanation": "语义：「伤心」表示悲痛，与「听到好消息」的语境相反。"}, {"text": "平静", "is_correct": false, "explanation": "语义：「平静」指心情没有起伏，与因好消息而失眠的情形不符。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：「安静」多形容环境或状态，不能用来描述因消息而失眠的心情。"}], "explanations": {"激动": "正确。「激动」表示因好消息而心情强烈起伏，兴奋得睡不着。", "伤心": "语义：「伤心」表示悲痛，与「听到好消息」的语境相反。", "平静": "语义：「平静」指心情没有起伏，与因好消息而失眠的情形不符。", "安静": "搭配：「安静」多形容环境或状态，不能用来描述因消息而失眠的心情。"}, "sentence_index": 0, "correct_answer": "激动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在考场上激动地答完了所有的题，心情却很平静。", "explanation": "这里应该用「冷静」。「激动」指心里兴奋、高兴，与「心情却很平静」矛盾。"}, {"text": "妈妈看着菜单，激动得一口也不吃，只是平静地坐着。", "explanation": "这里应该用「镇定」。「激动」表示心里高兴、兴奋，与「平静地坐着」矛盾。"}, {"text": "葬礼上，大家都很激动，默默地站着。", "explanation": "这里应该用「悲伤」。「激动」指高兴、兴奋，葬礼上的悲痛心情不能用它来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93021, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激动", "is_correct": true, "explanation": "正确。「激动」表示兴奋得手都在发抖。"}, {"text": "镇定", "is_correct": false, "explanation": "语义：「镇定」表示沉着不慌，与「手都在发抖」矛盾。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：「轻松」表示心情放松，与「手都在发抖」不合。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：「热情」形容待人的态度，不能用来描述手发抖这样的身体状态。"}], "explanations": {"激动": "正确。「激动」表示兴奋得手都在发抖。", "镇定": "语义：「镇定」表示沉着不慌，与「手都在发抖」矛盾。", "轻松": "语义：「轻松」表示心情放松，与「手都在发抖」不合。", "热情": "搭配：「热情」形容待人的态度，不能用来描述手发抖这样的身体状态。"}, "sentence_index": 6, "correct_answer": "激动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他考了全班第一，走路很激动。", "explanation": "这里应该用「得意」。「激动」指心里兴奋、难以平静，因成功而自豪要用「得意」。"}, {"text": "他拿到奖学金后，激动地说：“我一点也不高兴。”", "explanation": "这里应该用「沮丧」。「激动」指兴奋高兴，与「一点也不高兴」矛盾。"}, {"text": "我们比赛失败了，大家都很激动，个个都愁眉苦脸。", "explanation": "这里应该用「沮丧」。「激动」指兴奋高兴，与「愁眉苦脸」的失落心情矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93021, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈见到我们，激动哭了。", "corrected_sentence": "妈妈见到我们，激动得哭了。", "error_description": "错误在于漏掉了补语前的「得」。「激动」后要用「得」引出补语，正确说法是「激动得哭了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93021, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他激动跑出了教室。", "corrected_sentence": "他激动地跑出了教室。", "error_description": "错误在于状语「激动」后漏掉了「地」。形容词作状语后要加「地」，正确说法是「他激动地跑出了教室」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
