INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93022, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "感情强烈冲动，不能平静。", "primary_collocate": null, "pronunciation": "jī dòng", "ipa": "tɕi˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你先别激动，坐下来慢慢说。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一听这话就激动起来，声音越来越大。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说病人不能太激动，要保持平静。", "target_word": "激动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他情绪很激动，一边说一边拍桌子。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了那些话，她激动得脸都红了，大声争吵。", "target_word": "激动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人激动地抓住我的手，半天说不出话。", "target_word": "激动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家情绪太激动，会议只好先停下来。", "target_word": "激动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他越说越激动，最后站了起来。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她激动的样子，让大家都有点害怕。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别让孩子太激动，不然他晚上睡不着。", "target_word": "激动", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "激动了", "label": "体标"}, {"form": "激動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "情绪强烈波动，一时无法冷静下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf42e3e0-3aa5-4213-89fd-9bc9b80dff5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93022, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "激动", "is_correct": true, "explanation": "正确。「别激动」指别情绪过于强烈，需要冷静下来。"}, {"text": "热情", "is_correct": false, "explanation": "语义：「热情」形容待人态度，与「先别……慢慢说」的冷静语境不合。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：「别」后不能接「安静」这类状态形容词来劝人控制情绪。"}, {"text": "寒冷", "is_correct": false, "explanation": "搭配：「寒冷」形容温度，不能用来劝人控制情绪。"}], "explanations": {"激动": "正确。「别激动」指别情绪过于强烈，需要冷静下来。", "热情": "语义：「热情」形容待人态度，与「先别……慢慢说」的冷静语境不合。", "安静": "搭配：「别」后不能接「安静」这类状态形容词来劝人控制情绪。", "寒冷": "搭配：「寒冷」形容温度，不能用来劝人控制情绪。"}, "sentence_index": 0, "correct_answer": "激动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们赢了比赛，大家都很激动，却安静地坐着。", "explanation": "这里应该用「镇定」。「激动」指情绪强烈、难以平静，与「安静地坐着」矛盾。"}, {"text": "他听完我的话，激动得一句话都没说，情绪却非常冷静。", "explanation": "「激动」表示情绪强烈，与「情绪却非常冷静」矛盾。"}, {"text": "听到敲门声，他激动地站在门口，情绪却非常平静。", "explanation": "「激动」表示情绪强烈，与「情绪却非常平静」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激动", "is_correct": true, "explanation": "正确。「情绪太激动」指情绪强烈、难以平静，导致会议无法继续。"}, {"text": "亲切", "is_correct": false, "explanation": "搭配：「亲切」形容态度，不能用来修饰「情绪」。"}, {"text": "清晰", "is_correct": false, "explanation": "搭配：「清晰」形容思路或声音，不能用来形容情绪。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：若情绪冷静，会议就没有停下来的必要，与语境的因果关系不合。"}], "explanations": {"激动": "正确。「情绪太激动」指情绪强烈、难以平静，导致会议无法继续。", "亲切": "搭配：「亲切」形容态度，不能用来修饰「情绪」。", "清晰": "搭配：「清晰」形容思路或声音，不能用来形容情绪。", "冷静": "语义：若情绪冷静，会议就没有停下来的必要，与语境的因果关系不合。"}, "sentence_index": 6, "correct_answer": "激动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师很激动，心里却一点波澜也没有，继续慢慢地讲课。", "explanation": "「激动」指情绪强烈，与「心里却一点波澜也没有」矛盾。"}, {"text": "他很激动地坐着，显得特别镇定。", "explanation": "这里应该用「镇定」。「激动」指情绪强烈、不能平静，与「显得特别镇定」矛盾。"}, {"text": "这次没赢，大家都很激动，情绪却很平静。", "explanation": "「激动」指情绪强烈，与「情绪却很平静」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你太激动的了，先喝口水吧。", "corrected_sentence": "你太激动了，先喝口水吧。", "error_description": "错误在于形容词「激动」后多加了「的」。「激动」作谓语后直接接「了」，不能加「的」，正确说法是「你太激动了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很太激动了，连话都说不清楚。", "corrected_sentence": "他太激动了，连话都说不清楚。", "error_description": "错误在于多加了「很」。「很」与「太」不能同时修饰同一个形容词，正确说法是「他太激动了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93035, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": true, "explanation": "正确。保护指使人免受伤害，与“侵害”意思相反，是反义词。"}, {"text": "观看", "is_correct": false, "explanation": "观看指用眼睛看，与“侵害”没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "参加指加入某项活动，与“侵害”没有反义关系。"}, {"text": "同意", "is_correct": false, "explanation": "同意指赞成或接受，与“侵害”没有反义关系。"}], "correct_answer": "保护", "explanations": {"保护": "正确。保护指使人免受伤害，与“侵害”意思相反，是反义词。", "观看": "观看指用眼睛看，与“侵害”没有反义关系。", "参加": "参加指加入某项活动，与“侵害”没有反义关系。", "同意": "同意指赞成或接受，与“侵害”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93035, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": true, "explanation": "正确。保护指使人免受伤害，与“侵害”意思相反，是反义词。"}, {"text": "修理", "is_correct": false, "explanation": "修理指使损坏的东西恢复原样，与“侵害”没有反义关系。"}, {"text": "计划", "is_correct": false, "explanation": "计划指事先安排，与“侵害”没有反义关系。"}, {"text": "协商", "is_correct": false, "explanation": "协商指共同商量，与“侵害”没有反义关系。"}], "correct_answer": "保护", "explanations": {"保护": "正确。保护指使人免受伤害，与“侵害”意思相反，是反义词。", "修理": "修理指使损坏的东西恢复原样，与“侵害”没有反义关系。", "计划": "计划指事先安排，与“侵害”没有反义关系。", "协商": "协商指共同商量，与“侵害”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93035, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "侵害是做坏事，让别人受伤或吃亏。", "primary_collocate": null, "pronunciation": "qīn hài", "ipa": "tɕʰin˥ xaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "有些人专门侵害弱小的人。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能侵害别人，也要保护自己。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事侵害了邻居的利益，大家都不喜欢他。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些坏人侵害过很多儿童。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师告诉孩子，不能侵害别人。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大公司侵害小商店的利益，让他们吃了亏。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了赚钱，侵害了很多人。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种坏事会侵害普通人的身体健康。", "target_word": "侵害", "complexity_tier": "T3", "furigana": "zhè zhǒng huàishì huì qīnhài pǔtōng rén de shēntǐ jiànkāng", "sentence_source": "generated"}, {"text": "他故意推倒路人，侵害了别人的人身安全。", "target_word": "侵害", "complexity_tier": "T3", "furigana": "tā gùyì tuīdǎo lùrén, qīnhài le biéren de rénshēn ānquán", "sentence_source": "generated"}, {"text": "警察抓住了侵害老人的坏人。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "侵害了", "label": "体标"}, {"form": "侵害过", "label": "体标"}], "register": "书面", "sense_fingerprint": "做坏事让别人受伤或吃亏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30465e8-a764-427e-9db7-903b0f509c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93035, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "侵害", "is_correct": true, "explanation": "正确。“有些人专门侵害弱小的人”指做坏事使弱小者受伤或吃亏，与语境相合。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”指交换意见，与“专门……弱小的人”的加害义不符。"}, {"text": "修建", "is_correct": false, "explanation": "语义：“修建”的对象是建筑或设施，不能用于弱小的人。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”针对书刊或作品，不用于人。"}], "explanations": {"侵害": "正确。“有些人专门侵害弱小的人”指做坏事使弱小者受伤或吃亏，与语境相合。", "讨论": "语义：“讨论”指交换意见，与“专门……弱小的人”的加害义不符。", "修建": "语义：“修建”的对象是建筑或设施，不能用于弱小的人。", "出版": "搭配：“出版”针对书刊或作品，不用于人。"}, "sentence_index": 0, "correct_answer": "侵害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的话侵害了我的感情。", "explanation": "这里应该用〈伤害〉。侵害多指对权益、利益的侵犯；感情要用伤害。"}, {"text": "这件事侵害了班级的和谐。", "explanation": "这里应该用〈破坏〉。和谐要用破坏，不说“侵害和谐”。"}, {"text": "这场灾难侵害了他们的希望。", "explanation": "这里应该用〈摧毁〉。希望要用摧毁，侵害不这样搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93035, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "侵害", "is_correct": true, "explanation": "正确。“他为了赚钱，侵害了很多人”指他为赚钱做坏事使人吃亏，与语境相合。"}, {"text": "捐", "is_correct": false, "explanation": "搭配：“捐”的对象是钱物，不能说“捐人”。"}, {"text": "宽慰", "is_correct": false, "explanation": "语义：“宽慰”是安慰，与“为了赚钱”的动机不符。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”不含伤害义，“为了赚钱，送了很多人”句意不通。"}], "explanations": {"侵害": "正确。“他为了赚钱，侵害了很多人”指他为赚钱做坏事使人吃亏，与语境相合。", "捐": "搭配：“捐”的对象是钱物，不能说“捐人”。", "宽慰": "语义：“宽慰”是安慰，与“为了赚钱”的动机不符。", "送": "语义：“送”不含伤害义，“为了赚钱，送了很多人”句意不通。"}, "sentence_index": 6, "correct_answer": "侵害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种天气侵害了我们的睡眠。", "explanation": "这里应该用〈影响〉。侵害指做坏事使人受伤或吃亏；睡眠要用影响，不说“侵害睡眠”。"}, {"text": "这种批评侵害了大家的积极性。", "explanation": "这里应该用〈打击〉。积极性是精神状态，要用打击；侵害不这样搭配。"}, {"text": "这种制度侵害了年轻人的创造力。", "explanation": "这里应该用〈扼杀〉。创造力要用扼杀，侵害不这样搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93035, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "几个孩子被他过侵害了。", "corrected_sentence": "几个孩子被他侵害了。", "error_description": "多余的“过”：“过”不能放在动词前，应去掉，说“被他侵害了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93035, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们被他侵害了过。", "corrected_sentence": "孩子们被他侵害过。", "error_description": "体标重复：“侵害”后不能同时用“了”和“过”，应只用“过”，说“孩子们被他侵害过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93036, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": true, "explanation": "正确。保护指维护他人的权益，与“侵害”意思相反，是反义词。"}, {"text": "观看", "is_correct": false, "explanation": "观看指用眼睛看，与“侵害”没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "参加指加入某项活动，与“侵害”没有反义关系。"}, {"text": "同意", "is_correct": false, "explanation": "同意指赞成或接受，与“侵害”没有反义关系。"}], "correct_answer": "保护", "explanations": {"保护": "正确。保护指维护他人的权益，与“侵害”意思相反，是反义词。", "观看": "观看指用眼睛看，与“侵害”没有反义关系。", "参加": "参加指加入某项活动，与“侵害”没有反义关系。", "同意": "同意指赞成或接受，与“侵害”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93036, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保护", "is_correct": true, "explanation": "正确。保护指维护他人的权益，与“侵害”意思相反，是反义词。"}, {"text": "修理", "is_correct": false, "explanation": "修理指使损坏的东西恢复原样，与“侵害”没有反义关系。"}, {"text": "计划", "is_correct": false, "explanation": "计划指事先安排，与“侵害”没有反义关系。"}, {"text": "协商", "is_correct": false, "explanation": "协商指共同商量，与“侵害”没有反义关系。"}], "correct_answer": "保护", "explanations": {"保护": "正确。保护指维护他人的权益，与“侵害”意思相反，是反义词。", "修理": "修理指使损坏的东西恢复原样，与“侵害”没有反义关系。", "计划": "计划指事先安排，与“侵害”没有反义关系。", "协商": "协商指共同商量，与“侵害”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93036, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "非法侵入并损害他人的权益或利益。", "primary_collocate": null, "pronunciation": "qīn hài", "ipa": "tɕʰin˥ xaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司侵害了顾客的权益。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律不允许任何人侵害他人的权利。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站公开她的照片，侵害了她的隐私。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章侵害了他的名誉。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂侵害工人的利益，法院罚了它的钱。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有同意就用别人的画，这是侵害版权。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不给加班费，侵害了员工的权益。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种做法侵害了消费者的权利。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人侵害你的权利，你可以找律师。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院认为他的行为侵害了公司的利益。", "target_word": "侵害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "侵害了", "label": "体标"}, {"form": "侵害过", "label": "体标"}], "register": "书面", "sense_fingerprint": "非法损害他人的权利或利益", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30465e8-a764-427e-9db7-903b0f509c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93036, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "侵害", "is_correct": true, "explanation": "正确。“侵害顾客的权益”指非法损害他人的权益，与语境相合。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”的对象是人或作品，不能用于“权益”。"}, {"text": "享受", "is_correct": false, "explanation": "语义：公司不能“享受”顾客的权益，与语境不符。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是事物或作品，不能用于“权益”。"}], "explanations": {"侵害": "正确。“侵害顾客的权益”指非法损害他人的权益，与语境相合。", "赞美": "搭配：“赞美”的对象是人或作品，不能用于“权益”。", "享受": "语义：公司不能“享受”顾客的权益，与语境不符。", "欣赏": "搭配：“欣赏”的对象是事物或作品，不能用于“权益”。"}, "sentence_index": 0, "correct_answer": "侵害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的朋友侵害了我的感情。", "explanation": "这里应该用〈伤害〉。侵害多指对权益、利益的侵犯；感情要用伤害。"}, {"text": "这种行为侵害了社会秩序。", "explanation": "这里应该用〈破坏〉。侵害针对权益；秩序要用破坏。"}, {"text": "这阵噪音侵害了我的心情。", "explanation": "这里应该用〈影响〉。侵害针对他人的权益或利益；心情要用影响，不说“侵害心情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "侵害", "is_correct": true, "explanation": "正确。“老板不给加班费，侵害了员工的权益”指老板非法损害员工的权益，与语境相合。"}, {"text": "珍惜", "is_correct": false, "explanation": "语义：不给加班费的老板不会“珍惜”员工的权益，与语境矛盾。"}, {"text": "捍卫", "is_correct": false, "explanation": "语义：“捍卫”是保卫，与不给加班费的做法矛盾。"}, {"text": "资助", "is_correct": false, "explanation": "搭配：“资助”针对人或项目的经济支持，不用来说权益。"}], "explanations": {"侵害": "正确。“老板不给加班费，侵害了员工的权益”指老板非法损害员工的权益，与语境相合。", "珍惜": "语义：不给加班费的老板不会“珍惜”员工的权益，与语境矛盾。", "捍卫": "语义：“捍卫”是保卫，与不给加班费的做法矛盾。", "资助": "搭配：“资助”针对人或项目的经济支持，不用来说权益。"}, "sentence_index": 6, "correct_answer": "侵害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些车辆侵害了交通。", "explanation": "这里应该用〈妨碍〉。侵害针对他人的权益；交通要用妨碍。"}, {"text": "这次失败侵害了他的信心。", "explanation": "这里应该用〈打击〉。侵害多指对权益或利益的侵犯；信心要用打击。"}, {"text": "战争侵害了他们的家园。", "explanation": "这里应该用〈摧毁〉。侵害指非法损害权益；家园被毁要用摧毁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家商场侵害了过顾客的权益。", "corrected_sentence": "这家商场侵害过顾客的权益。", "error_description": "体标重复：“侵害”后只用“过”，不能再加“了”，应说“侵害过顾客的权益”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
