INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93038, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "眼前是眼睛前面的位置，即面前。", "primary_collocate": null, "pronunciation": "yǎn qián", "ipa": "jɛn˨˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "一座高山出现在我眼前。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼前的路很窄，我们走得很慢。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书就放在你眼前，你怎么没看见？", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着眼前的大海，他很高兴。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手举到眼前，仔细地看了看。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把东西放在眼前，会挡住视线。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们眼前摆着一大盘水果。", "target_word": "眼前", "complexity_tier": "T3", "furigana": "hái zi men yǎn qián bǎi zhe yí dà pán shuǐ guǒ。", "sentence_source": "generated"}, {"text": "一只小鸟飞到了我的眼前。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一辆红色的车从我眼前开过去了。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大了，我眼前什么都看不清。", "target_word": "眼前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "眼前：眼睛前面的位置，面前的空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c66390e-ca93-402b-af4c-cf18df80027a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93038, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼前", "is_correct": true, "explanation": "「眼前」指眼睛前面，与“出现在……”搭配，符合句意。"}, {"text": "以后", "is_correct": false, "explanation": "语义：「以后」表示时间，不能指空间位置，“出现在我以后”不成立。"}, {"text": "历史", "is_correct": false, "explanation": "语义：「历史」指过去的事，不指空间位置，“出现在我历史”不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」不指空间位置，“一座高山出现在我价格”说不通。"}], "explanations": {"眼前": "「眼前」指眼睛前面，与“出现在……”搭配，符合句意。", "以后": "语义：「以后」表示时间，不能指空间位置，“出现在我以后”不成立。", "历史": "语义：「历史」指过去的事，不指空间位置，“出现在我历史”不通。", "价格": "语义：「价格」不指空间位置，“一座高山出现在我价格”说不通。"}, "sentence_index": 0, "correct_answer": "眼前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他眼前来过北京。", "explanation": "这里应该用〈以前〉。眼前指眼睛前面的位置，不指时间，不能用来说过去的经历。"}, {"text": "他用眼前看东西。", "explanation": "这里说的是器官“眼睛”，但眼前只指眼睛前面的空间，不指器官本身。"}, {"text": "他明天眼前去北京。", "explanation": "这里应该用〈以后〉。眼前指眼睛前面的位置，不指时间，不能用来说将来的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b48ec5-fac0-442a-8ea9-648a718647c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼前", "is_correct": true, "explanation": "「眼前」指眼睛前面，“摆着”表示物体所在的处所，符合句意。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：「摆着」要接具体处所或物品，「脾气」不是处所，不能作“摆”的地点。"}, {"text": "学问", "is_correct": false, "explanation": "语义：「学问」指知识，不指空间位置，“孩子们学问摆着”不通。"}, {"text": "身份", "is_correct": false, "explanation": "语义：「身份」指社会地位，不表示位置，句意不通。"}], "explanations": {"眼前": "「眼前」指眼睛前面，“摆着”表示物体所在的处所，符合句意。", "脾气": "搭配：「摆着」要接具体处所或物品，「脾气」不是处所，不能作“摆”的地点。", "学问": "语义：「学问」指知识，不指空间位置，“孩子们学问摆着”不通。", "身份": "语义：「身份」指社会地位，不表示位置，句意不通。"}, "sentence_index": 6, "correct_answer": "眼前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的眼前越来越差，看书要戴眼镜。", "explanation": "这里说的是视力，但眼前只指眼睛前面的位置，不指视力本身。"}, {"text": "他哭得眼前都肿了。", "explanation": "这里说的是眼皮，但眼前不指眼皮，眼前只指眼睛前面的空间。"}, {"text": "他上周眼前去了一趟北京。", "explanation": "这里应删去〈眼前〉，改为「上周去了一趟北京」。眼前指眼睛前面的位置，不表示时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b48ec5-fac0-442a-8ea9-648a718647c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他站我眼前，笑着说话。", "corrected_sentence": "他站在我眼前，笑着说话。", "error_description": "「站」表示处于某处时，处所前要加“在”，应说「站在我眼前」，不能省略「在」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b48ec5-fac0-442a-8ea9-648a718647c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他眼前的很忙，没时间休息。", "corrected_sentence": "他眼前很忙，没时间休息。", "error_description": "「眼前」作状语修饰“很忙”时，后面不加「的」，应说「眼前很忙」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b48ec5-fac0-442a-8ea9-648a718647c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
