INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93053, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "总裁是一个大公司里最大的头头。", "primary_collocate": null, "pronunciation": "zǒng cái", "ipa": "tsʊŋ˨˩ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "在我们公司，决定大事的人是总裁。", "target_word": "总裁", "complexity_tier": "T3", "furigana": "zǒngcái", "sentence_source": "generated"}, {"text": "总裁坐在最大的办公室里。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理做不了决定，要问总裁。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总裁很忙，我们很少见到他。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位总裁每天早上七点就到公司。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爸爸是一家大公司的总裁。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总裁住在公司旁边的大房子里。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "员工们都有点怕总裁。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总裁今天穿了一件黑色的西装。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李想当公司的总裁。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副总裁", "label": "复合"}, {"form": "集团总裁", "label": "复合"}], "register": "中性", "sense_fingerprint": "总裁：大公司里最大的头头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80dc076e-16c3-467f-b99b-92db9f5b2db7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93053, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "秘书", "is_correct": false, "explanation": "语义：秘书负责辅助工作，不决定公司的大事。"}, {"text": "总裁", "is_correct": true, "explanation": "总裁是大公司里最大的头头，决定大事，与句子相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师负责做饭，与决定公司的大事无关。"}, {"text": "皇上", "is_correct": false, "explanation": "语域：皇上是古代的称呼，不用于现代公司。"}], "explanations": {"秘书": "语义：秘书负责辅助工作，不决定公司的大事。", "总裁": "总裁是大公司里最大的头头，决定大事，与句子相符。", "厨师": "语义：厨师负责做饭，与决定公司的大事无关。", "皇上": "语域：皇上是古代的称呼，不用于现代公司。"}, "sentence_index": 0, "correct_answer": "总裁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们办公室的总裁今天请假了。", "explanation": "这里应该用〈主任〉。总裁是大公司里最大的头头，办公室的负责人要说主任。"}, {"text": "这家小店的总裁每天早上开门。", "explanation": "这里应该用〈老板〉。总裁只用于大公司，小店的负责人要说老板。"}, {"text": "我们组的总裁每天检查质量。", "explanation": "这里应该用〈组长〉。总裁是大公司里最大的头头，小组的负责人要说组长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '974c070f-760d-4dc6-a020-4dcb3fc1bbd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93053, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乞丐", "is_correct": false, "explanation": "语义：乞丐没有钱住大房子，与「大房子」相矛盾。"}, {"text": "总裁", "is_correct": true, "explanation": "总裁是大公司里最大的头头，住得起公司旁边的大房子，与句子相符。"}, {"text": "王爷", "is_correct": false, "explanation": "语域：王爷是古代的封号，不用于现代人。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠不住人的大房子，句子说不通。"}], "explanations": {"乞丐": "语义：乞丐没有钱住大房子，与「大房子」相矛盾。", "总裁": "总裁是大公司里最大的头头，住得起公司旁边的大房子，与句子相符。", "王爷": "语域：王爷是古代的封号，不用于现代人。", "老鼠": "语义：老鼠不住人的大房子，句子说不通。"}, "sentence_index": 6, "correct_answer": "总裁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这艘渔船的总裁每天凌晨出海。", "explanation": "这里应该用〈船长〉。总裁是大公司里最大的头头，驾船出海的人要说船长。"}, {"text": "我们班的总裁每周找家长谈话。", "explanation": "这里应该用〈班主任〉。总裁只管大公司，班级的负责人要说班主任。"}, {"text": "这支足球队的总裁每天带队训练。", "explanation": "这里应该用〈教练〉。总裁指大公司里最大的头头，带队训练的人要说教练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '974c070f-760d-4dc6-a020-4dcb3fc1bbd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93053, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只总裁昨天来过我们公司。", "corrected_sentence": "一位总裁昨天来过我们公司。", "error_description": "量词错误：指人的总裁要用「位」，「只」用于动物。错误句中的「一只」应改为「一位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '974c070f-760d-4dc6-a020-4dcb3fc1bbd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93053, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是这家公司的一条总裁。", "corrected_sentence": "他是这家公司的一位总裁。", "error_description": "量词错误：「条」用于细长的东西，指人的总裁要用「位」，错误句中的「一条」应改为「一位」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '974c070f-760d-4dc6-a020-4dcb3fc1bbd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
