INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93057, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "联络是主动和别人取得联系，把消息告诉对方。", "primary_collocate": null, "pronunciation": "lián luò", "ipa": "ljɛn˧˥ lwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "到了那里，请你打电话联络我。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有事的话，你可以打电话联络我。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我明天用微信联络你，好吗？", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走了以后，一直没有联络我们。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会的时间，老师会联络大家。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你到家后，请联络一下妈妈。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的电话号码我不知道，没法联络他。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找不到我，可以联络我朋友。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理想联络那家公司的人。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先联络一下，再决定去哪儿。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "联络了", "label": "完成体"}, {"form": "联络过", "label": "经历体"}, {"form": "联络联络", "label": "重叠"}, {"form": "联络人", "label": "复合词"}], "register": "中性", "sense_fingerprint": "主动去找某人，告诉对方消息，让对方知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80dc076e-16c3-467f-b99b-92db9f5b2db7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93057, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：「打电话」后面不能接「吃」来带「我」这样的宾语，句子不通。"}, {"text": "搬", "is_correct": false, "explanation": "语义：「搬」是搬动物品的意思，不能用来指打电话去找我。"}, {"text": "联络", "is_correct": true, "explanation": "联络：主动和人取得联系，告诉对方消息，与「打电话」相符。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：冷落是怠慢、不理睬，不是打电话要做的事。"}], "explanations": {"吃": "搭配：「打电话」后面不能接「吃」来带「我」这样的宾语，句子不通。", "搬": "语义：「搬」是搬动物品的意思，不能用来指打电话去找我。", "联络": "联络：主动和人取得联系，告诉对方消息，与「打电话」相符。", "冷落": "语义：冷落是怠慢、不理睬，不是打电话要做的事。"}, "sentence_index": 0, "correct_answer": "联络"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每个星期六都在公园联络。", "explanation": "这里应该用〈见面〉。联络指通过电话、消息等与人取得联系，当面见人要说见面。"}, {"text": "这两条河在这里联络。", "explanation": "这里应该用〈汇合〉。联络用于人与人之间取得联系，两条河相会要说汇合。"}, {"text": "我们昨天联络了这个问题。", "explanation": "这里应该用〈讨论〉。联络的对象是人，讨论的对象是问题，要说讨论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '974c070f-760d-4dc6-a020-4dcb3fc1bbd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93057, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拥抱", "is_correct": false, "explanation": "语义：拥抱需要见面，与「不知道电话号码」无关，句子不通。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」的对象是物品，不能用来对人。"}, {"text": "联络", "is_correct": true, "explanation": "联络：主动和人取得联系，与「没有电话号码」的语境相符。"}, {"text": "测量", "is_correct": false, "explanation": "语义：测量是测定数据，与找人联系无关。"}], "explanations": {"拥抱": "语义：拥抱需要见面，与「不知道电话号码」无关，句子不通。", "修理": "搭配：「修理」的对象是物品，不能用来对人。", "联络": "联络：主动和人取得联系，与「没有电话号码」的语境相符。", "测量": "语义：测量是测定数据，与找人联系无关。"}, "sentence_index": 6, "correct_answer": "联络"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天在商店联络了一双鞋。", "explanation": "这里应该用〈购买〉。联络用于和人取得联系，买东西要说购买。"}, {"text": "妈妈在菜市场联络了几个西瓜。", "explanation": "这里应该用〈挑选〉。联络指和人取得联系，挑西瓜要说挑选。"}, {"text": "我每天早上联络房间。", "explanation": "这里应该用〈打扫〉。联络的对象是人，房间要说打扫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '974c070f-760d-4dc6-a020-4dcb3fc1bbd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93057, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "有问题可以随时联络了我。", "corrected_sentence": "有问题可以随时联络我。", "error_description": "「了」错用：「可以随时」表示可能或将来，句中动词后的「了」表示动作已完成，二者矛盾，应去掉「了」，说「可以随时联络我」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '974c070f-760d-4dc6-a020-4dcb3fc1bbd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93057, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们经常很联络，关系一直很好。", "corrected_sentence": "我们经常联络，关系一直很好。", "error_description": "副词错误：「很」一般修饰形容词或少数心理动词，不能修饰动作动词「联络」，应去掉「很」，说「经常联络」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '974c070f-760d-4dc6-a020-4dcb3fc1bbd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
