INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93059, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "兴建是开始盖新房子或新桥。", "primary_collocate": null, "pronunciation": "xīng jiàn", "ipa": "ɕiŋ˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "政府打算在河上兴建一座新桥。", "target_word": "兴建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里要兴建几十间新房子。", "target_word": "兴建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在山脚下兴建了一座小桥。", "target_word": "兴建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司准备在这里兴建新住宅。", "target_word": "兴建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年镇上兴建了一批新房子。", "target_word": "兴建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了方便过河，村民决定兴建一座桥。", "target_word": "兴建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市正在兴建很多新楼房。", "target_word": "兴建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在老家兴建一栋新房子。", "target_word": "兴建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们想在河边兴建一座漂亮的小桥。", "target_word": "兴建", "complexity_tier": "T3", "furigana": "cūnmen xiǎng zài hébiān xīngjiàn yí zuò piàoliang de xiǎoqiáo", "sentence_source": "generated"}, {"text": "市里早就兴建过一座大桥。", "target_word": "兴建", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兴建了", "label": "体标（了）"}, {"form": "兴建过", "label": "体标（过）"}, {"form": "兴建着", "label": "体标（着）"}], "register": "书面", "sense_fingerprint": "开始盖新房子或新桥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c66390e-ca93-402b-af4c-cf18df80027a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93059, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兴建", "is_correct": true, "explanation": "正确：“兴建”指开始盖新桥，与“在河上”和“一座新桥”相符。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”是拆掉已有的建筑，与句中要盖“新桥”相反。"}, {"text": "维修", "is_correct": false, "explanation": "搭配：“维修”针对已有的旧东西，不能维修“新桥”。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”用于车、船、飞机等，不能驾驶“桥”。"}], "explanations": {"兴建": "正确：“兴建”指开始盖新桥，与“在河上”和“一座新桥”相符。", "拆除": "语义：“拆除”是拆掉已有的建筑，与句中要盖“新桥”相反。", "维修": "搭配：“维修”针对已有的旧东西，不能维修“新桥”。", "驾驶": "搭配：“驾驶”用于车、船、飞机等，不能驾驶“桥”。"}, "sentence_index": 0, "correct_answer": "兴建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他兴建了一双新鞋。", "explanation": "这里应该用〈制作〉。兴建用于房屋、桥梁等建筑，做鞋要用制作。"}, {"text": "工人兴建了这座旧桥。", "explanation": "这里应该用〈维修〉。兴建是开始建造新的建筑，修补旧桥要用维修。"}, {"text": "工人兴建了一台机器。", "explanation": "这里应该用〈制造〉。兴建指开始盖新房子或新桥，机器的生产要用制造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b48ec5-fac0-442a-8ea9-648a718647c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93059, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兴建", "is_correct": true, "explanation": "正确：“兴建”指建造大量新楼房，与“这座城市正在”和“新楼房”相符。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”是赶走，与“新楼房”无关。"}, {"text": "采摘", "is_correct": false, "explanation": "搭配：“采摘”用于果实、花草，不能说采摘楼房。"}, {"text": "挖掘", "is_correct": false, "explanation": "语义：“挖掘”指挖出地下的东西，与盖楼房的意思不符。"}], "explanations": {"兴建": "正确：“兴建”指建造大量新楼房，与“这座城市正在”和“新楼房”相符。", "驱赶": "语义：“驱赶”是赶走，与“新楼房”无关。", "采摘": "搭配：“采摘”用于果实、花草，不能说采摘楼房。", "挖掘": "语义：“挖掘”指挖出地下的东西，与盖楼房的意思不符。"}, "sentence_index": 6, "correct_answer": "兴建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们把客厅兴建了一番。", "explanation": "这里应该用〈装饰〉。兴建指建造房屋或工程，给客厅布置美化要用装饰。"}, {"text": "工人兴建了屋顶上的漏洞。", "explanation": "这里应该用〈修补〉。兴建是建造新的建筑，堵住漏洞要用修补。"}, {"text": "妈妈兴建了我破旧的衣服。", "explanation": "这里应该用〈缝补〉。兴建用于房屋、桥梁等建筑，破衣服的修补要用缝补。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b48ec5-fac0-442a-8ea9-648a718647c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93059, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在村口兴建了了一座石桥。", "corrected_sentence": "他们在村口兴建了一座石桥。", "error_description": "错误在“兴建”后的体标“了”。“兴建了”后面已有一个“了”，不能重复，应说“兴建了”，不能说“兴建了了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b48ec5-fac0-442a-8ea9-648a718647c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93059, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程队正在兴建了一座小桥。", "corrected_sentence": "工程队正在兴建一座小桥。", "error_description": "“正在”表示动作进行中，不能和表示完成的“了”同用，应说“正在兴建”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b48ec5-fac0-442a-8ea9-648a718647c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
