INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93071, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93071, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "前生是人们说的，这辈子以前的那一辈子。", "primary_collocate": null, "pronunciation": "qián shēng", "ipa": "tɕʰjɛn˧˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "人们说，前生的事谁也记不得。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明问奶奶：“我的前生是谁？”", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说自己前生是一只猫。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人说这辈子遇到的人，前生就认识。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外婆常说前生做好事，这辈子就有福。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是一对夫妻的前生故事。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她梦见了自己的前生。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友开玩笑说，我前生一定是个厨师。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你相信有前生吗？", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，他们俩前生是好朋友。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人们说的这辈子以前的一辈子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e983dcc6-3418-42fd-ac27-a2db7eba3cd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93071, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前生", "is_correct": true, "explanation": "正确。“人们说，前生的事谁也记不得”中，“前生”指这辈子以前的那一辈子。"}, {"text": "前途", "is_correct": false, "explanation": "搭配：“前途”常说“有前途”“前途光明”，不能修饰“事”，也与“记不得”的过去义不合。"}, {"text": "前景", "is_correct": false, "explanation": "语义：“前景”指将来的状况，无法“记不得”，与“前生的事”的过去义矛盾。"}, {"text": "前奏", "is_correct": false, "explanation": "语义：“前奏”指音乐或事情的开头部分，与“人们说……”所指的前世义不合。"}], "explanations": {"前生": "正确。“人们说，前生的事谁也记不得”中，“前生”指这辈子以前的那一辈子。", "前途": "搭配：“前途”常说“有前途”“前途光明”，不能修饰“事”，也与“记不得”的过去义不合。", "前景": "语义：“前景”指将来的状况，无法“记不得”，与“前生的事”的过去义矛盾。", "前奏": "语义：“前奏”指音乐或事情的开头部分，与“人们说……”所指的前世义不合。"}, "sentence_index": 0, "correct_answer": "前生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店前生是一家饭馆。", "explanation": "这里应该用〈以前〉。“前生”只指人在这辈子以前的一辈子，不能指店铺。"}, {"text": "明年我前生要去国外读书。", "explanation": "这里误用了将来的意思。“前生”指这辈子以前的一辈子，不能用于将来；说以后要用〈以后〉。"}, {"text": "这台电脑的前生型号很便宜。", "explanation": "这里应该用〈前代〉。“前生”只用于人，不用于产品，电脑的前一代型号要说“前代”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93071, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前生", "is_correct": true, "explanation": "正确。“她梦见了自己的前生”中，“前生”指这辈子以前的那一辈子。"}, {"text": "前言", "is_correct": false, "explanation": "语义：“前言”指书籍的序言，不能被“梦见”，与人的前世义不合。"}, {"text": "前提", "is_correct": false, "explanation": "搭配：“前提”多用于“以……为前提”，不能说“梦见了自己的前提”。"}, {"text": "前沿", "is_correct": false, "explanation": "语义：“前沿”指事物发展的最前端，与“自己的”人生经历义不合。"}], "explanations": {"前生": "正确。“她梦见了自己的前生”中，“前生”指这辈子以前的那一辈子。", "前言": "语义：“前言”指书籍的序言，不能被“梦见”，与人的前世义不合。", "前提": "搭配：“前提”多用于“以……为前提”，不能说“梦见了自己的前提”。", "前沿": "语义：“前沿”指事物发展的最前端，与“自己的”人生经历义不合。"}, "sentence_index": 6, "correct_answer": "前生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把前生的作业交给了老师。", "explanation": "这里应该用〈旧〉。“前生”只指人这辈子以前的一辈子，不能修饰作业；说以前布置的作业要用“旧”。"}, {"text": "这对夫妻有好几个前生。", "explanation": "这里应该用〈世〉。“前生”按“世”计数，说“好几世前生”，不用“个”。"}, {"text": "这个行业的前生很好。", "explanation": "这里应该用〈前景〉。“前生”只指人此生以前的一辈子，不能用于行业，行业的发展要说“前景”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93071, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我前生过是个老师。", "corrected_sentence": "我前生是个老师。", "error_description": "错误在于“前生”后面加了“过”。“前生”是名词，不能带动态助词“过”，应改为“我前生是个老师。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93071, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们俩有两个前生，关系很好。", "corrected_sentence": "他们俩有两世前生，关系很好。", "error_description": "错误在于量词。“前生”应按“世”计数，不用“个”，应改为“他们俩有两世前生，关系很好。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
