INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93072, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "迷信或宗教中指人在此生之前的一世。", "primary_collocate": null, "pronunciation": "qián shēng", "ipa": "tɕʰjɛn˧˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "老人相信自己前生是一个和尚。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，这辈子的苦是前生欠下的。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们说两个人前生就有缘分。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得自己前生一定见过这个人。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里讲了一个人前生和今生的故事。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "佛教认为人有前生，也有来世。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "算命先生说我前生是个读书人。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈常说，这是前生注定的事。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他相信前生做了好事，今生才幸福。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老和尚说，每个人的前生都不一样。", "target_word": "前生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "宗教迷信中人此生之前的一世", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e983dcc6-3418-42fd-ac27-a2db7eba3cd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93072, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前生", "is_correct": true, "explanation": "正确。“前生”指迷信中此生之前的一世，与“老人相信自己……是一个和尚”的语境相符。"}, {"text": "前年", "is_correct": false, "explanation": "语义：“前年”是时间词，不能指身份，“相信自己前年是一个和尚”说不通。"}, {"text": "前妻", "is_correct": false, "explanation": "语义：“前妻”指离婚的前任配偶，不能作为“和尚”这一身份的说法。"}, {"text": "前科", "is_correct": false, "explanation": "搭配：“前科”指以前的违法记录，不能与“是一个和尚”这种身份说法搭配。"}], "explanations": {"前生": "正确。“前生”指迷信中此生之前的一世，与“老人相信自己……是一个和尚”的语境相符。", "前年": "语义：“前年”是时间词，不能指身份，“相信自己前年是一个和尚”说不通。", "前妻": "语义：“前妻”指离婚的前任配偶，不能作为“和尚”这一身份的说法。", "前科": "搭配：“前科”指以前的违法记录，不能与“是一个和尚”这种身份说法搭配。"}, "sentence_index": 0, "correct_answer": "前生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我上个星期前生搬过家。", "explanation": "这里应该用〈以前〉。“前生”指此生之前的那一世，不能指这辈子不久前的时间。"}, {"text": "他相信前生会变成富人。", "explanation": "这里误用了将来的意思。“前生”只指此生之前的一世，说将来的情况要用〈来生〉。"}, {"text": "这家公司的前生是一个小工厂。", "explanation": "这里应该用〈前身〉。“前生”只用于人，指此生之前的一世；公司、建筑的以前形态要用“前身”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前生", "is_correct": true, "explanation": "正确。“算命先生说我前生是个读书人”中，“前生”指此生之前的一世。"}, {"text": "前面", "is_correct": false, "explanation": "语义：“前面”指方位，不能指一种身份，“算命先生说我前面是个读书人”说不通。"}, {"text": "前途", "is_correct": false, "explanation": "搭配：“前途”指将来的发展，常说“前途光明”，不能说“是个读书人”。"}, {"text": "前锋", "is_correct": false, "explanation": "语义：“前锋”指体育运动中的位置或军队的先头部队，与“读书人”的身份不合。"}], "explanations": {"前生": "正确。“算命先生说我前生是个读书人”中，“前生”指此生之前的一世。", "前面": "语义：“前面”指方位，不能指一种身份，“算命先生说我前面是个读书人”说不通。", "前途": "搭配：“前途”指将来的发展，常说“前途光明”，不能说“是个读书人”。", "前锋": "语义：“前锋”指体育运动中的位置或军队的先头部队，与“读书人”的身份不合。"}, "sentence_index": 6, "correct_answer": "前生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说自己有三个前生，都是和尚。", "explanation": "这里应该用〈世〉。“前生”按“世”计数，说“三世前生”，不用“个”。"}, {"text": "我把前生的文件都整理好了。", "explanation": "这里应该用〈旧〉。“前生”指迷信中人此生之前的一世，不能修饰文件；说旧文件要用“旧”。"}, {"text": "我的前生队长下周就要退休了。", "explanation": "这里应该用〈前任〉。“前生”只指迷信中此生之前的一世，不能用来修饰职务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说自己前生了是个木匠。", "corrected_sentence": "他说自己前生是个木匠。", "error_description": "错误在于“前生”后面加了“了”。“前生”是名词，不能带动态助词“了”，应改为“他说自己前生是个木匠。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书上说人有好几个前生。", "corrected_sentence": "书上说人有好几世前生。", "error_description": "错误在于量词。“前生”应按“世”计数，不用“个”，应改为“书上说人有好几世前生。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
