INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93080, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体最高的部分。", "primary_collocate": null, "pronunciation": "dǐng", "ipa": "tiŋ˨˩", "syllable_count": 1, "sentences": [{"text": "这座塔很高，我们爬了很久才到顶。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树的顶有一个鸟窝。", "target_word": "顶", "complexity_tier": "T3", "furigana": "shù de dǐng yǒu yí ge niǎo wō", "sentence_source": "generated"}, {"text": "这棵树太高了，我看不到它的顶。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梯子的顶碰到了天花板。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帽子的顶是红色的。", "target_word": "顶", "complexity_tier": "T3", "furigana": "mào zi de dǐng shì hóng sè de", "sentence_source": "generated"}, {"text": "路很陡，他爬到顶就累坏了。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从瓶子的底到顶都擦干净了。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小旗一直挂在旗杆的顶。", "target_word": "顶", "complexity_tier": "T3", "furigana": "xiǎo qí yì zhí guà zài qí gān de dǐng", "sentence_source": "generated"}, {"text": "这座楼的顶是平的，可以看星星。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪人的顶放着一个红桶。", "target_word": "顶", "complexity_tier": "T3", "furigana": "xuě rén de dǐng fàng zhe yí ge hóng tǒng", "sentence_source": "generated"}], "morphological_forms": [{"form": "山顶", "label": "复合词"}, {"form": "屋顶", "label": "复合词"}, {"form": "头顶", "label": "复合词"}, {"form": "顶部", "label": "复合词"}], "register": "中性", "sense_fingerprint": "物体本身最高的那一部分，如塔、树、帽子的顶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80dc076e-16c3-467f-b99b-92db9f5b2db7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93080, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "顶", "is_correct": true, "explanation": "顶：dǐng（第三声），指物体最高的部分。"}, {"text": "定", "is_correct": false, "explanation": "dìng（第四声）与 dǐng（第三声）声调不同，意思是“确定”。"}, {"text": "挺", "is_correct": false, "explanation": "tǐng 与 dǐng 声母不同（t／d），意思是“挺”。"}, {"text": "等", "is_correct": false, "explanation": "děng 与 dǐng 韵母不同（eng／ing），意思是“等”。"}, {"text": "钉", "is_correct": false, "explanation": "dīng（第一声）与 dǐng（第三声）声调不同，意思是“钉子”。"}], "explanations": {"顶": "顶：dǐng（第三声），指物体最高的部分。", "定": "dìng（第四声）与 dǐng（第三声）声调不同，意思是“确定”。", "挺": "tǐng 与 dǐng 声母不同（t／d），意思是“挺”。", "等": "děng 与 dǐng 韵母不同（eng／ing），意思是“等”。", "钉": "dīng（第一声）与 dǐng（第三声）声调不同，意思是“钉子”。"}, "sentence_index": null, "correct_answer": "顶"}, "level_3": {"options": [{"text": "顶", "is_correct": true, "explanation": "顶：指物体最高的部分，与“爬了很久”“这座塔很高”相合。"}, {"text": "水", "is_correct": false, "explanation": "语义：爬塔的终点应是高处，“水”不能作这里的到达点。"}, {"text": "海", "is_correct": false, "explanation": "语义：“海”在地面，与“这座塔很高”和“爬”的动作不合。"}, {"text": "课本", "is_correct": false, "explanation": "配价：“到”要求处所，“课本”是物品，不能作“到”的终点。"}], "explanations": {"顶": "顶：指物体最高的部分，与“爬了很久”“这座塔很高”相合。", "水": "语义：爬塔的终点应是高处，“水”不能作这里的到达点。", "海": "语义：“海”在地面，与“这座塔很高”和“爬”的动作不合。", "课本": "配价：“到”要求处所，“课本”是物品，不能作“到”的终点。"}, "sentence_index": 0, "correct_answer": "顶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只鞋的顶破了，要扔掉。", "explanation": "这里应该用〈面〉。鞋子的上半部分叫“鞋面”，“顶”不用来指鞋子。"}, {"text": "这朵玫瑰的顶很扎手。", "explanation": "这里应该用〈刺〉。扎手说的是玫瑰的刺，“顶”指最上面的部分，不能指刺。"}, {"text": "这条路的顶有一片湖。", "explanation": "这里应该用〈尽头〉。路的末端要说“尽头”，“顶”指最上面，不能说路的顶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '974c070f-760d-4dc6-a020-4dcb3fc1bbd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93080, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "顶", "is_correct": true, "explanation": "顶：dǐng（第三声），指物体最高的部分。"}, {"text": "订", "is_correct": false, "explanation": "dìng（第四声）与 dǐng（第三声）声调不同，意思是“订”。"}, {"text": "盯", "is_correct": false, "explanation": "dīng（第一声）与 dǐng（第三声）声调不同，意思是“盯着”。"}, {"text": "挡", "is_correct": false, "explanation": "dǎng 与 dǐng 韵母不同（ang／ing），意思是“挡”。"}, {"text": "党", "is_correct": false, "explanation": "dǎng 与 dǐng 韵母不同（ang／ing），意思是“政党”。"}], "explanations": {"顶": "顶：dǐng（第三声），指物体最高的部分。", "订": "dìng（第四声）与 dǐng（第三声）声调不同，意思是“订”。", "盯": "dīng（第一声）与 dǐng（第三声）声调不同，意思是“盯着”。", "挡": "dǎng 与 dǐng 韵母不同（ang／ing），意思是“挡”。", "党": "dǎng 与 dǐng 韵母不同（ang／ing），意思是“政党”。"}, "sentence_index": null, "correct_answer": "顶"}, "level_3": {"options": [{"text": "顶", "is_correct": true, "explanation": "顶：与“从瓶子的底到”构成相对的一端，指最高处。"}, {"text": "手", "is_correct": false, "explanation": "语义：“手”不是瓶子的一部分，“从瓶子的底到手”说不通。"}, {"text": "书", "is_correct": false, "explanation": "配价：“到”后要求位置，“书”是物品，不能作擦拭的终点。"}, {"text": "花", "is_correct": false, "explanation": "语义：瓶子上没有“花”这一部分，与“从底到”不合。"}], "explanations": {"顶": "顶：与“从瓶子的底到”构成相对的一端，指最高处。", "手": "语义：“手”不是瓶子的一部分，“从瓶子的底到手”说不通。", "书": "配价：“到”后要求位置，“书”是物品，不能作擦拭的终点。", "花": "语义：瓶子上没有“花”这一部分，与“从底到”不合。"}, "sentence_index": 6, "correct_answer": "顶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在店里买了一顶手套。", "explanation": "这里应该用〈副〉。量词“顶”用于帽子、蚊帐，手套要用“副”，不能说一顶手套。"}, {"text": "这条河的顶很宽。", "explanation": "这里应该用〈河面〉。河没有“顶”，说河的宽度要用“河面”。"}, {"text": "他的顶很高，走路很显眼。", "explanation": "这里应该用〈个子〉。说人的高矮要用“个子”，“顶”指最上面的部分，不能说人的顶很高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '974c070f-760d-4dc6-a020-4dcb3fc1bbd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们一直往上走，终于在顶了。", "corrected_sentence": "他们一直往上走，终于到顶了。", "error_description": "“到顶”不能说成“在顶”。表示走到最高处要用“到”作补语，应说“到顶了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '974c070f-760d-4dc6-a020-4dcb3fc1bbd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个衣柜很高，我站在地上看不到顶的它。", "corrected_sentence": "这个衣柜很高，我站在地上看不到它的顶。", "error_description": "“它的顶”不能倒成“顶的它”。“它”修饰“顶”，中间要用“的”，应说“它的顶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '974c070f-760d-4dc6-a020-4dcb3fc1bbd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93089, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93089, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93089, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "象棋中黑方最小的棋子，过河前只能向前走，过河后也可以左右走。", "primary_collocate": null, "pronunciation": "zú", "ipa": "tsu˧˥", "syllable_count": 1, "sentences": [{"text": "象棋里红方有兵，黑方有卒。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑方还没过河的卒只能向前走。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卒过了河，就可以左右走。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一个卒吃掉了对方的马。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盘棋里，我只剩下一个卒。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在象棋里，卒是最小的兵。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卒虽然小，走到底线也有用。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先把卒向前走了一步。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方的卒挡住了我的车。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，下棋时别小看一个卒。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小卒", "label": "复合"}, {"form": "兵卒", "label": "复合"}], "register": "中性", "sense_fingerprint": "象棋里黑方最小的棋子，过河前只能向前走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823c9f7d-00cb-41f2-a06b-9f6f2f7e63e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93089, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "卒", "is_correct": true, "explanation": "正确答案：卒（zú），即听到的读音。"}, {"text": "竹", "is_correct": false, "explanation": "zhú（第二声）与 zú 的声母不同（zh/z），意思是竹子。"}, {"text": "组", "is_correct": false, "explanation": "zǔ（第三声）与 zú 声调不同，意思是组织。"}, {"text": "祖", "is_correct": false, "explanation": "zǔ（第三声）与 zú 声调不同，意思是祖先。"}, {"text": "烛", "is_correct": false, "explanation": "zhú（第二声）与 zú 声母不同（zh/z），意思是蜡烛。"}], "explanations": {"卒": "正确答案：卒（zú），即听到的读音。", "竹": "zhú（第二声）与 zú 的声母不同（zh/z），意思是竹子。", "组": "zǔ（第三声）与 zú 声调不同，意思是组织。", "祖": "zǔ（第三声）与 zú 声调不同，意思是祖先。", "烛": "zhú（第二声）与 zú 声母不同（zh/z），意思是蜡烛。"}, "sentence_index": null, "correct_answer": "卒"}, "level_3": {"options": [{"text": "卒", "is_correct": true, "explanation": "卒：象棋中黑方最小的棋子，与“黑方有”的所指相符。"}, {"text": "士兵", "is_correct": false, "explanation": "语义：“士兵”指军人，不是象棋中的棋子，与“象棋里……有”的语境不符。"}, {"text": "棋盘", "is_correct": false, "explanation": "语义：“棋盘”是棋具的底板，不是棋子，不能说“黑方有棋盘”作为棋子。"}, {"text": "将士", "is_correct": false, "explanation": "语域：“将士”是书面词，指一群军人，与口语化的棋局叙述不搭。"}], "explanations": {"卒": "卒：象棋中黑方最小的棋子，与“黑方有”的所指相符。", "士兵": "语义：“士兵”指军人，不是象棋中的棋子，与“象棋里……有”的语境不符。", "棋盘": "语义：“棋盘”是棋具的底板，不是棋子，不能说“黑方有棋盘”作为棋子。", "将士": "语域：“将士”是书面词，指一群军人，与口语化的棋局叙述不搭。"}, "sentence_index": 0, "correct_answer": "卒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "卒可以走日字。", "explanation": "这里应该用〈马〉。马走日字，卒只能向前走，过河后才能横走，不走日字。"}, {"text": "卒只能走田字。", "explanation": "这里应该用〈象〉。象走田字，卒过河前只能向前，不走田字。"}, {"text": "棋盘上还剩一匹卒。", "explanation": "这里应该用〈个〉。卒是棋子，应配“个”；“匹”是马等牲畜的量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93089, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "卒", "is_correct": true, "explanation": "正确答案：卒（zú），即听到的读音。"}, {"text": "租", "is_correct": false, "explanation": "zū（第一声）与 zú 声调不同，意思是租用。"}, {"text": "逐", "is_correct": false, "explanation": "zhú（第二声）与 zú 声母不同（zh/z），意思是追赶。"}, {"text": "粗", "is_correct": false, "explanation": "cū（第一声）与 zú 声母不同（c/z）、声调也不同，意思是粗糙。"}], "explanations": {"卒": "正确答案：卒（zú），即听到的读音。", "租": "zū（第一声）与 zú 声调不同，意思是租用。", "逐": "zhú（第二声）与 zú 声母不同（zh/z），意思是追赶。", "粗": "cū（第一声）与 zú 声母不同（c/z）、声调也不同，意思是粗糙。"}, "sentence_index": null, "correct_answer": "卒"}, "level_3": {"options": [{"text": "卒", "is_correct": true, "explanation": "卒：最小的棋子，能过河后左右走，与“虽然小，走到底线也有用”相符。"}, {"text": "山", "is_correct": false, "explanation": "体貌：“山”体积庞大，与“虽然小”的描写正相反。"}, {"text": "脚", "is_correct": false, "explanation": "语义：“脚”是身体部位，不能“走到底线”作为棋子。"}, {"text": "草", "is_correct": false, "explanation": "语义：“草”是植物，不能“走到底线”，也不是棋子。"}], "explanations": {"卒": "卒：最小的棋子，能过河后左右走，与“虽然小，走到底线也有用”相符。", "山": "体貌：“山”体积庞大，与“虽然小”的描写正相反。", "脚": "语义：“脚”是身体部位，不能“走到底线”作为棋子。", "草": "语义：“草”是植物，不能“走到底线”，也不是棋子。"}, "sentence_index": 6, "correct_answer": "卒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "黑方的卒守住了宫。", "explanation": "这里应该用〈士〉。守宫的是士，卒不能进入九宫。"}, {"text": "卒要隔一个子才能吃子。", "explanation": "这里应该用〈炮〉。炮要隔一个子才能吃子；卒只能向前走一步吃子，不能隔子。"}, {"text": "我的卒是一位将军。", "explanation": "这里应该用〈帅〉。卒是最小的兵，不是统帅一方的帅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93089, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "棋盘上黑方还剩两只卒。", "corrected_sentence": "棋盘上黑方还剩两个卒。", "error_description": "错误：量词“只”多用于动物，卒作为棋子应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93089, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我先把卒的往前推了一步。", "corrected_sentence": "我先把卒往前推了一步。", "error_description": "错误：“卒”与动词之间多加了“的”。“往前”作状语，直接放在动词前，不加“的”，应说「我先把卒往前推了一步」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
