INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93100, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "首次建立；开创成立。", "primary_collocate": null, "pronunciation": "chuàng lì", "ipa": "ʈʂʰu̯ɑŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "他创立了一种新的学说。", "target_word": "创立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位医生创立了新的教学方法。", "target_word": "创立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想创立一个新的音乐节。", "target_word": "创立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孙中山创立了中国同盟会。", "target_word": "创立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的新制度是他创立的。", "target_word": "创立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她创立了一个专门研究古诗的小组。", "target_word": "创立", "complexity_tier": "T3", "furigana": "tā chuàng lì le yí gè zhuān mén yán jiū gǔ shī de xiǎo zǔ", "sentence_source": "generated"}, {"text": "她创立过一个帮助孩子的基金会。", "target_word": "创立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日是他们创立的。", "target_word": "创立", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司创立以后，生意一直很好。", "target_word": "创立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想创立一个属于自己的品牌。", "target_word": "创立", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "创立了", "label": "体标（了）"}, {"form": "创立过", "label": "体标（过）"}, {"form": "创立者", "label": "复合词"}, {"form": "创立人", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "首次开创并建立学说、制度、组织等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a27985d7-ed1e-45a0-89a0-5af58ad339f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93100, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "创立", "is_correct": true, "explanation": "正确：“创立”指首次建立学说，与“一种新的学说”搭配。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象应是食物，学说不能被煮。"}, {"text": "骑", "is_correct": false, "explanation": "语义：“骑”的对象是马、自行车等，学说不能被骑。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”搭配车辆或船只，不说驾驶学说。"}], "explanations": {"创立": "正确：“创立”指首次建立学说，与“一种新的学说”搭配。", "煮": "语义：“煮”的对象应是食物，学说不能被煮。", "骑": "语义：“骑”的对象是马、自行车等，学说不能被骑。", "驾驶": "搭配：“驾驶”搭配车辆或船只，不说驾驶学说。"}, "sentence_index": 0, "correct_answer": "创立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他创立了一篇新论文。", "explanation": "这里应该用〈发表〉。创立用于学说、制度、组织，论文要用发表。"}, {"text": "她创立了一首新歌。", "explanation": "这里应该用〈创作〉。创立用于学说、制度、组织，作品要用创作。"}, {"text": "这位设计师创立了一座新房子。", "explanation": "这里应该用〈建造〉。创立不用于房屋等建筑，房子要用建造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93100, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "创立", "is_correct": true, "explanation": "正确：“创立”指首次建立基金会，与“帮助孩子的基金会”语境吻合。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”的对象是可切分的食物或物体，不能切基金会。"}, {"text": "训练", "is_correct": false, "explanation": "语义：“训练”针对人或动物的技能，基金会不能被训练。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“基金会”作宾语。"}], "explanations": {"创立": "正确：“创立”指首次建立基金会，与“帮助孩子的基金会”语境吻合。", "切": "搭配：“切”的对象是可切分的食物或物体，不能切基金会。", "训练": "语义：“训练”针对人或动物的技能，基金会不能被训练。", "睡": "配价：“睡”是不及物动词，不能带“基金会”作宾语。"}, "sentence_index": 6, "correct_answer": "创立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她创立了一幅新画。", "explanation": "这里应该用〈绘制〉。创立用于学说、制度、组织，画作要用绘制。"}, {"text": "他创立了一顿晚饭。", "explanation": "这里应该用〈准备〉。创立用于学说、制度、组织，饭菜要用准备。"}, {"text": "这位工人创立了一条新公路。", "explanation": "这里应该用〈修建〉。创立不用于道路等建筑，公路要用修建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位学者创立着一个新的学派。", "corrected_sentence": "这位学者创立了一个新的学派。", "error_description": "“着”错误：“创立”表示一次完成的动作，不能用“着”表示持续状态，应把“创立着”改为“创立了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93100, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个品牌是他三年前了创立的。", "corrected_sentence": "这个品牌是他三年前创立的。", "error_description": "“了”位置错误：“了”不能插在“创立”之前。“是……的”句式中的动词后不加“了”，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
