INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93107, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "园区是一大片地方，里面有好多楼和公司。", "primary_collocate": null, "pronunciation": "yuán qū", "ipa": "ɥɛn˧˥ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "这个园区很大，里面有二十多栋楼和几十家公司。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在科技园区的一家公司上班。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "园区里有餐厅，中午很多人去吃饭。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司就在东边的园区里。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "园区门口有保安，陌生人不能随便进。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐班车去园区上班。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个园区新开了一家咖啡店。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "园区里种着很多树，空气很好。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带我在园区里走了一圈。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "园区内每天早上有免费班车。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "園區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有很多楼和公司的一大片地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e983dcc6-3418-42fd-ac27-a2db7eba3cd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93107, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "园区", "is_correct": true, "explanation": "正确。“这个园区很大，里面有二十多栋楼和几十家公司”中，“园区”指一大片有很多楼和公司的地方。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园里不会有几十家公司，与“园区”的企业义不合。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“花园”不与“里面有二十多栋楼”搭配，楼群的说法不自然。"}, {"text": "墓园", "is_correct": false, "explanation": "语义：墓园是埋葬死者的地方，不会有二十多栋楼。"}], "explanations": {"园区": "正确。“这个园区很大，里面有二十多栋楼和几十家公司”中，“园区”指一大片有很多楼和公司的地方。", "公园": "语义：公园里不会有几十家公司，与“园区”的企业义不合。", "花园": "搭配：“花园”不与“里面有二十多栋楼”搭配，楼群的说法不自然。", "墓园": "语义：墓园是埋葬死者的地方，不会有二十多栋楼。"}, "sentence_index": 0, "correct_answer": "园区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我带孩子去园区玩滑梯。", "explanation": "这里应该用〈公园〉。“园区”指有很多楼和公司的一大片地方，不是供人游玩的公园；带孩子玩滑梯要去公园。"}, {"text": "我们公司在一栋园区里。", "explanation": "这里应该用〈个〉。“园区”是地方，用“个”计量，不用“栋”。"}, {"text": "这个园区很高，我们在门口仰头看了很久。", "explanation": "这里应该用〈大〉。“园区”指占地大、楼宇多的一片地方，不能用“高”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93107, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "园区", "is_correct": true, "explanation": "正确。“这个园区新开了一家咖啡店”中，“园区”指集中设置商业和企业的区域。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不能“新开了一家咖啡店”，与“新开”的商业义不合。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能开咖啡店，与“新开了一家咖啡店”的语义冲突。"}, {"text": "病房", "is_correct": false, "explanation": "搭配：“病房”一般不说“新开了一家咖啡店”，两者搭配不当。"}], "explanations": {"园区": "正确。“这个园区新开了一家咖啡店”中，“园区”指集中设置商业和企业的区域。", "教室": "语义：教室不能“新开了一家咖啡店”，与“新开”的商业义不合。", "河流": "语义：河流不能开咖啡店，与“新开了一家咖啡店”的语义冲突。", "病房": "搭配：“病房”一般不说“新开了一家咖啡店”，两者搭配不当。"}, "sentence_index": 6, "correct_answer": "园区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们门口新建了一条园区。", "explanation": "这里应该用〈个〉。“园区”是地方，用“个”计量，不用“条”。"}, {"text": "他躺在园区上睡觉。", "explanation": "这里应该用〈床〉。“园区”是划定的大片区域，不能当作床来躺。"}, {"text": "我每天骑着园区去上班。", "explanation": "这里应该用〈自行车〉。“园区”是划定的大片区域，不是交通工具，不能用“骑”；骑车上班要说“骑自行车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93107, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司搬进了一栋园区。", "corrected_sentence": "我们公司搬进了一个园区。", "error_description": "错误在于量词。“园区”是地方，应用“个”计量，不用“栋”，应改为“我们公司搬进了一个园区。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93107, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他园区上班。", "corrected_sentence": "他在园区上班。", "error_description": "错误在于漏掉了介词“在”。表示上班地点的“园区”前要加“在”，应改为“他在园区上班。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
