INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93108, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "划定的、集中设置企业、学校等的区域。", "primary_collocate": null, "pronunciation": "yuán qū", "ipa": "ɥɛn˧˥ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "市政府划出一块地，建了新的工业园区。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个园区里有很多外国企业。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学城园区集中了五所学校。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "园区为小公司提供便宜的办公室。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新园区明年开始招商。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司搬进了开发区的软件园区。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个产业园区有一百多家企业。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想把工厂都放到园区里。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "园区的建设让这个城市发展得更快。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校搬到了新建的教育园区。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "園區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "划定的集中设置企业学校的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e983dcc6-3418-42fd-ac27-a2db7eba3cd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "园区", "is_correct": true, "explanation": "正确。“市政府划出一块地，建了新的工业园区”中，“园区”指划定的集中设置企业的区域。"}, {"text": "赛车场", "is_correct": false, "explanation": "语义：赛车场是供赛车比赛的场地，不是集中设置企业的区域，“建了新的工业……”说不通。"}, {"text": "墓园", "is_correct": false, "explanation": "语义：墓园是埋葬死者的地方，不是工业用地，与“建了新的工业……”不合。"}, {"text": "游乐园", "is_correct": false, "explanation": "语义：游乐园是娱乐场所，不是工业用地，与“建了新的工业……”不合。"}], "explanations": {"园区": "正确。“市政府划出一块地，建了新的工业园区”中，“园区”指划定的集中设置企业的区域。", "赛车场": "语义：赛车场是供赛车比赛的场地，不是集中设置企业的区域，“建了新的工业……”说不通。", "墓园": "语义：墓园是埋葬死者的地方，不是工业用地，与“建了新的工业……”不合。", "游乐园": "语义：游乐园是娱乐场所，不是工业用地，与“建了新的工业……”不合。"}, "sentence_index": 0, "correct_answer": "园区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校为新生提供便宜的园区。", "explanation": "这里应该用〈宿舍〉。“园区”是划定的区域，不能作为给新生住的房间。"}, {"text": "市里新建了一栋园区。", "explanation": "这里应该用〈个〉。“园区”用“个”计量，不用“栋”。"}, {"text": "园区为病人检查身体。", "explanation": "这里应该用〈医生〉。“园区”是区域，不能为病人检查身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "园区", "is_correct": true, "explanation": "正确。“这个产业园区有一百多家企业”中，“园区”指集中设置企业的区域。"}, {"text": "博物馆", "is_correct": false, "explanation": "语义：博物馆陈列文物，不会有一百多家企业，与“企业”的语义冲突。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园饲养动物，不是企业聚集的地方，与“一百多家企业”不合。"}, {"text": "医院", "is_correct": false, "explanation": "搭配：“产业”与“医院”搭配不当，医院一般不说“有一百多家企业”。"}], "explanations": {"园区": "正确。“这个产业园区有一百多家企业”中，“园区”指集中设置企业的区域。", "博物馆": "语义：博物馆陈列文物，不会有一百多家企业，与“企业”的语义冲突。", "动物园": "语义：动物园饲养动物，不是企业聚集的地方，与“一百多家企业”不合。", "医院": "搭配：“产业”与“医院”搭配不当，医院一般不说“有一百多家企业”。"}, "sentence_index": 6, "correct_answer": "园区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把作业交给了新园区。", "explanation": "这里应该用〈老师〉。“园区”是划定的大片区域，不是人，不能接收作业；交作业要交给老师。"}, {"text": "我每天坐新园区去上班。", "explanation": "这里应该用〈地铁〉。“园区”是划定的大片区域，不是交通工具，不能用“坐”；坐着去上班要说“坐地铁”。"}, {"text": "我把书放进了新园区。", "explanation": "这里应该用〈书包〉。“园区”是划定的大片区域，不能用来装书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政府划出一块地，建了一栋新的工业园区。", "corrected_sentence": "市政府划出一块地，建了一个新的工业园区。", "error_description": "错误在于量词。“园区”是地方，应用“个”计量，不用“栋”，应改为“建了一个新的工业园区。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她园区里工作，每天很忙。", "corrected_sentence": "她在园区里工作，每天很忙。", "error_description": "错误在于漏掉了介词“在”。表示工作地点的“园区里”前要加“在”，应改为“她在园区里工作，每天很忙。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f22bb91-bffd-42cd-bd14-359eae75a4fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93116, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小类", "is_correct": true, "explanation": "正确。“小类”是把大类再细分后的较小类别，与“大类”构成层级上的反义。"}, {"text": "桌子", "is_correct": false, "explanation": "“桌子”是家具，与“大类”的类别无关，不构成反义。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”是地理事物，与“大类”不构成反义关系。"}, {"text": "数量", "is_correct": false, "explanation": "“数量”指多少，与大类的类别层级无关，不是反义词。"}], "correct_answer": "小类", "explanations": {"小类": "正确。“小类”是把大类再细分后的较小类别，与“大类”构成层级上的反义。", "桌子": "“桌子”是家具，与“大类”的类别无关，不构成反义。", "河流": "“河流”是地理事物，与“大类”不构成反义关系。", "数量": "“数量”指多少，与大类的类别层级无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93116, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小类", "is_correct": true, "explanation": "正确。“小类”是把大类再细分后的较小类别，与“大类”构成层级上的反义。"}, {"text": "窗户", "is_correct": false, "explanation": "“窗户”是建筑部件，与“大类”不构成反义关系。"}, {"text": "海洋", "is_correct": false, "explanation": "“海洋”是地理事物，与“大类”的类别无关，不构成反义。"}, {"text": "方法", "is_correct": false, "explanation": "“方法”指做事的途径，与大类的类别层级无关，不是反义词。"}], "correct_answer": "小类", "explanations": {"小类": "正确。“小类”是把大类再细分后的较小类别，与“大类”构成层级上的反义。", "窗户": "“窗户”是建筑部件，与“大类”不构成反义关系。", "海洋": "“海洋”是地理事物，与“大类”的类别无关，不构成反义。", "方法": "“方法”指做事的途径，与大类的类别层级无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93116, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "按性质划分的较大的类别。", "primary_collocate": null, "pronunciation": "dà lèi", "ipa": "ta˥˩ lei˥˩", "syllable_count": 2, "sentences": [{"text": "动物可以分成两个大类。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本词典把词分成几个大类。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物属于生物的一个大类。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的课程分为文科和理科两大类。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把病人的问题分成了几个大类。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个大类是按性质划分的，分得很清楚。", "target_word": "大类", "complexity_tier": "T3", "furigana": "dà lèi", "sentence_source": "generated"}, {"text": "老师说，这些商品属于同一个大类。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里的书先按大类摆好。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把工作分成三个大类来做。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告里分出了五个大类。", "target_word": "大类", "complexity_tier": "T3", "furigana": "dà lèi", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个大类", "label": "量词"}], "register": "书面语", "sense_fingerprint": "按性质划分出来的范围较大的类别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad589025-ca3e-4551-a9f9-01f0e0f0297e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大类", "is_correct": true, "explanation": "正确。“动物可以分成两个大类”指按性质划分出的较大类别。"}, {"text": "大厅", "is_correct": false, "explanation": "语义：“大厅”是房间，动物不能分成两个大厅。"}, {"text": "大学", "is_correct": false, "explanation": "语义：“大学”是高等学校，不能用来说动物的分类。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“大海”要用“片”计量，不说“两个大海”。"}], "explanations": {"大类": "正确。“动物可以分成两个大类”指按性质划分出的较大类别。", "大厅": "语义：“大厅”是房间，动物不能分成两个大厅。", "大学": "语义：“大学”是高等学校，不能用来说动物的分类。", "大海": "搭配：“大海”要用“片”计量，不说“两个大海”。"}, "sentence_index": 0, "correct_answer": "大类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个大类的教室里坐着五十个学生。", "explanation": "这里应该用〈大班〉。“大类”指类别，不指班级。"}, {"text": "学校的图书馆一下子来了大类的人。", "explanation": "这里应该用〈大批〉。“大类”指类别，不表示人数多。"}, {"text": "学校的大类每天都来上课。", "explanation": "这里应该用〈老师〉。“大类”指类别，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大类", "is_correct": true, "explanation": "正确。“属于同一个大类”指商品被归入同一个较大的类别。"}, {"text": "大脑", "is_correct": false, "explanation": "语义：“大脑”是器官，商品不能属于同一个大脑。"}, {"text": "大洲", "is_correct": false, "explanation": "语义：“大洲”是地理区域，商品不能按大洲归入同一类。"}, {"text": "大树", "is_correct": false, "explanation": "搭配：“树”用“棵”计量，不说“同一个大树”。"}], "explanations": {"大类": "正确。“属于同一个大类”指商品被归入同一个较大的类别。", "大脑": "语义：“大脑”是器官，商品不能属于同一个大脑。", "大洲": "语义：“大洲”是地理区域，商品不能按大洲归入同一类。", "大树": "搭配：“树”用“棵”计量，不说“同一个大树”。"}, "sentence_index": 6, "correct_answer": "大类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件毛衣太小了，我想换个大类的。", "explanation": "这里应该用〈大号〉。“大类”指类别，不指衣服的尺码。"}, {"text": "他一口气吃了一大类饭。", "explanation": "这里应该用〈大份〉。“大类”指类别，不指食物的份量。"}, {"text": "大类都很喜欢这份报告。", "explanation": "这里应该用〈大家〉。“大类”指类别，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校把课程分成了两本大类。", "corrected_sentence": "学校把课程分成了两个大类。", "error_description": "量词错误：“大类”的量词应为“个”，“本”只用于书籍，不能用于大类。正确：“学校把课程分成了两个大类。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这大类的商品都放在柜台上。", "corrected_sentence": "这个大类的商品都放在柜台上。", "error_description": "量词缺失：“大类”前用“这”指代时要加“个”，应说“这个大类”，不说“这大类”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
