INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93118, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "很不容易；费了很大力气才（做成）。", "primary_collocate": null, "pronunciation": "hǎo róng yì", "ipa": "xaʊ̯˨˩˦ ɻʊŋ˧˥ i˥˩", "syllable_count": 3, "sentences": [{"text": "好容易才买到票，我们赶紧上了车。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他好容易才找到那家小店。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题很难，我好容易才做出来。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排了两个小时队，好容易才轮到我。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈好容易把孩子哄睡了。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我好容易借到一本书，你可别弄丢了。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了很大的雪，他好容易才走到家。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好容易找到停车的地方，已经晚了。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她好容易才学会骑自行车。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车，我们好容易才到公司。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "费了很大力气才做成某事，常与“才”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad589025-ca3e-4551-a9f9-01f0e0f0297e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93118, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好容易", "is_correct": true, "explanation": "“好容易”表示费了很大力气才做成，与“才”和“买到票”的语义相合。"}, {"text": "果然", "is_correct": false, "explanation": "语义：“果然”表示与预料相符，与“才”所表示的费力后才达成不合。"}, {"text": "轻易", "is_correct": false, "explanation": "语义：“轻易”表示不费力，与“才”所表示的费了很大力气后才买到相矛盾。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续不断，不能与表示费力后才达成的“才”搭配。"}], "explanations": {"好容易": "“好容易”表示费了很大力气才做成，与“才”和“买到票”的语义相合。", "果然": "语义：“果然”表示与预料相符，与“才”所表示的费力后才达成不合。", "轻易": "语义：“轻易”表示不费力，与“才”所表示的费了很大力气后才买到相矛盾。", "一直": "搭配：“一直”表示持续不断，不能与表示费力后才达成的“才”搭配。"}, "sentence_index": 0, "correct_answer": "好容易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我好容易才一分钟就做完了这道题。", "explanation": "这里应该用〈很快〉。好容易表示费了很大力气才做成，与“一分钟就做完”所说的迅速相矛盾。"}, {"text": "他好容易就考上了大学。", "explanation": "好容易强调费力才做成，与“就”表示轻松的语气矛盾。这里应该用〈轻易〉。"}, {"text": "他好容易只用了一天就找到了那份工作。", "explanation": "这里应该用〈轻易〉。好容易强调费力才做成，与“只用了一天”所说的轻快相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93118, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好容易", "is_correct": true, "explanation": "“好容易”表示费了很大力气才走到，与“下了很大的雪”的语境相合。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立即，与“下了很大的雪”后艰难走回家的过程不合。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示经常性，与这一次具体的经历不合。"}, {"text": "丝毫", "is_correct": false, "explanation": "语域：“丝毫”属书面语，多用于否定句，与这句口语叙述不合。"}], "explanations": {"好容易": "“好容易”表示费了很大力气才走到，与“下了很大的雪”的语境相合。", "马上": "语义：“马上”表示立即，与“下了很大的雪”后艰难走回家的过程不合。", "总是": "语义：“总是”表示经常性，与这一次具体的经历不合。", "丝毫": "语域：“丝毫”属书面语，多用于否定句，与这句口语叙述不合。"}, "sentence_index": 6, "correct_answer": "好容易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路上很通畅，我们好容易到了公司。", "explanation": "这里应该用〈轻易〉。好容易表示费了很大力气才做成，与“路上很通畅”所说的顺利、不费力相矛盾。"}, {"text": "路上堵车，我们好容易才一会儿就到了公司。", "explanation": "这里应该用〈很快〉。好容易表示费了很大力气，与“一会儿就到”所说的迅速相矛盾。"}, {"text": "路上堵车，我们好容易轻松地到了公司。", "explanation": "这里的“好容易”含有费了很大力气的意思，与“轻松地”所说的毫不费力相反；表示不费力应用〈轻易〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
