INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93127, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "孕妇是肚子里有小宝宝的妈妈。", "primary_collocate": null, "pronunciation": "yùn fù", "ipa": "yn˥˩ fu˥˩", "syllable_count": 2, "sentences": [{"text": "这位孕妇走得很慢。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交车上，我给孕妇让了座。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孕妇每天都要多吃蔬菜和水果。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生告诉孕妇要早点休息。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位孕妇正在医院等着检查。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孕妇不能提很重的东西。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站有给孕妇用的电梯。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孕妇的肚子一天比一天大。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐是孕妇，她最近很爱吃酸的。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孕妇在家听着音乐，等着小宝宝出生。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "孕妇装", "label": "复合"}], "register": "中性", "sense_fingerprint": "肚子里有小宝宝、还没生孩子的妈妈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823c9f7d-00cb-41f2-a06b-9f6f2f7e63e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93127, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "孕妇", "is_correct": true, "explanation": "孕妇：怀孕的妇女，可以用“这位”称呼，走得慢也合理。"}, {"text": "冠军", "is_correct": false, "explanation": "语义：冠军多以跑得快著称，与“走得很慢”相矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会走路，与“走得很慢”不搭。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿还不能正常走路，与“走得很慢”不符；“这位”也不用于婴儿。"}], "explanations": {"孕妇": "孕妇：怀孕的妇女，可以用“这位”称呼，走得慢也合理。", "冠军": "语义：冠军多以跑得快著称，与“走得很慢”相矛盾。", "石头": "语义：石头不会走路，与“走得很慢”不搭。", "婴儿": "语义：婴儿还不能正常走路，与“走得很慢”不符；“这位”也不用于婴儿。"}, "sentence_index": 0, "correct_answer": "孕妇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孕妇刚出院，抱着刚满月的宝宝回家了。", "explanation": "这里应该用〈产妇〉。抱着刚满月的宝宝回家的是刚生完孩子的妈妈；孕妇还没生，不能这样说。"}, {"text": "孕妇在肚子里一天天长大。", "explanation": "这里应该用〈胎儿〉。孕妇是怀孕的妈妈，在肚子里一天天长大的是胎儿。"}, {"text": "孕妇刚出生时只有三斤重。", "explanation": "这里应该用〈婴儿〉。刚出生、只有三斤重的是婴儿；孕妇是怀孕的妈妈，不能说“刚出生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93127, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "孕妇", "is_correct": true, "explanation": "孕妇：怀孕的妇女，地铁站的专用电梯是为她们准备的。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不乘坐电梯，与“给……用的电梯”的使用者不符。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能乘坐电梯，与“给……用的电梯”的使用者不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是乘坐电梯的对象，这里的“用”指人乘坐。"}], "explanations": {"孕妇": "孕妇：怀孕的妇女，地铁站的专用电梯是为她们准备的。", "石头": "语义：石头不乘坐电梯，与“给……用的电梯”的使用者不符。", "书": "语义：书不能乘坐电梯，与“给……用的电梯”的使用者不符。", "冰箱": "语义：冰箱不是乘坐电梯的对象，这里的“用”指人乘坐。"}, "sentence_index": 6, "correct_answer": "孕妇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在公园里看到一只孕妇。", "explanation": "这里应该用〈位〉或〈个〉。量词“只”多用于动物，指人不用“只”。"}, {"text": "车站门口走来一头孕妇。", "explanation": "这里应该用〈位〉或〈个〉。“头”多用于大型牲畜，不能用来数孕妇。"}, {"text": "超市门口站着一条孕妇。", "explanation": "这里应该用〈位〉或〈个〉。“条”多用于细长的东西，不能用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93127, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这三位孕妇们走得很慢。", "corrected_sentence": "这三位孕妇走得很慢。", "error_description": "错误：数量词“这三位”后又加了“们”，写成“孕妇们”。正确：“这三位孕妇”。有数量词时，名词后不再加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93127, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地铁站旁边有给一只孕妇用的电梯。", "corrected_sentence": "地铁站旁边有给孕妇用的电梯。", "error_description": "错误：量词“只”不能用于指人，“一只孕妇”有误。正确：直接说“给孕妇用的电梯”，或改用“一位孕妇”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
