INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93131, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "客运是用车、船、飞机来送人。", "primary_collocate": null, "pronunciation": "kè yùn", "ipa": "kʰɤ˥˩ yn˥˩", "syllable_count": 2, "sentences": [{"text": "这辆大车只做客运，不拉货。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河上的客运很方便，天天有船。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机客运比火车客运快。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司做客运，也做货运。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，火车客运特别忙。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的客运只有一辆小巴。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的客运很发达，地铁和公交都很方便。", "target_word": "客运", "complexity_tier": "T3", "furigana": "zhè zuò chéng shì de kèyùn hěn fādá, dìtiě hé gōngjiāo dōu hěn fāngbiàn。", "sentence_source": "generated"}, {"text": "海上客运今天因为大风停了。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车以前运货，现在改做客运了。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小岛上的客运靠一条小船。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "客運", "label": "繁体"}, {"form": "客运站", "label": "复合"}], "register": "中性", "sense_fingerprint": "用车、船、飞机运送乘客这件事，与货运相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823c9f7d-00cb-41f2-a06b-9f6f2f7e63e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93131, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客运", "is_correct": true, "explanation": "客运：运送乘客的运输业务，与“不拉货”不矛盾。"}, {"text": "货运", "is_correct": false, "explanation": "语义：货运就是拉货，与“不拉货”正好相反。"}, {"text": "快递", "is_correct": false, "explanation": "语义：快递是运送货物，与“不拉货”相矛盾。"}, {"text": "广告", "is_correct": false, "explanation": "搭配：大车“只做”的应是运输业务，不宜说“只做广告”。"}], "explanations": {"客运": "客运：运送乘客的运输业务，与“不拉货”不矛盾。", "货运": "语义：货运就是拉货，与“不拉货”正好相反。", "快递": "语义：快递是运送货物，与“不拉货”相矛盾。", "广告": "搭配：大车“只做”的应是运输业务，不宜说“只做广告”。"}, "sentence_index": 0, "correct_answer": "客运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车上的客运很多，大家都挤不动。", "explanation": "这里应该用〈旅客〉。客运是运输业务，不指乘车的人。"}, {"text": "这家公司的客运连货物也运，很划算。", "explanation": "这里应该用〈运输〉。客运专指运送旅客的业务，连货物也运要说〈运输〉，不能用“客运”。"}, {"text": "这家公司今天来了很多客运，大家都在招待。", "explanation": "这里应该用〈客人〉。客运是运输业务，不指来访的人，不能说“来了很多客运”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93131, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客运", "is_correct": true, "explanation": "客运：运送旅客的运输业务，这里指城市的客运业务很发达。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不能用“发达”来形容，与句意不合。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠与地铁、公交的方便程度无关，句意不通。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：“发达”一般不修饰雨水，且与地铁和公交的便利无关。"}], "explanations": {"客运": "客运：运送旅客的运输业务，这里指城市的客运业务很发达。", "海洋": "语义：海洋不能用“发达”来形容，与句意不合。", "沙漠": "语义：沙漠与地铁、公交的方便程度无关，句意不通。", "雨水": "搭配：“发达”一般不修饰雨水，且与地铁和公交的便利无关。"}, "sentence_index": 6, "correct_answer": "客运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "岸边停着一张客运。", "explanation": "这里应该用〈班〉。“张”用于平面的东西，不能用来数客运。"}, {"text": "码头上来了一块客运。", "explanation": "这里应该用〈班〉。“块”用于块状的东西，不能用来数客运。"}, {"text": "港口每天有一只客运。", "explanation": "这里应该用〈班〉。“只”多用于动物，不能用来数客运。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93131, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司地客运业务发展得很快。", "corrected_sentence": "这家公司的客运业务发展得很快。", "error_description": "错误：修饰名词“客运业务”应用“的”，不用“地”。正确：「这家公司的客运业务发展得很快。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93131, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条线路上还有一只客运。", "corrected_sentence": "这条线路上还有一班客运。", "error_description": "错误：量词“只”。正确：“班”，用于定时开行的客运班次。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
