INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93132, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "运载旅客的运输业务。", "primary_collocate": null, "pronunciation": "kè yùn", "ipa": "kʰɤ˥˩ yn˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司的客运业务做得很好。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节期间，全国铁路客运非常繁忙。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在客运行业工作了十年。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的公共客运越来越方便。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想提高航空客运的服务质量。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情期间，客运受到了很大影响。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客运和货运是运输业的两大部分。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的客运收入比货运高。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的客运规定下个月开始实施。", "target_word": "客运", "complexity_tier": "T3", "furigana": "xīn de kèyùn guīdìng xià gè yuè kāishǐ shíshī。", "sentence_source": "generated"}, {"text": "长途客运的票价这个月降了。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "客運", "label": "繁体"}, {"form": "客运量", "label": "复合"}], "register": "中性", "sense_fingerprint": "运载旅客的运输业务或行业，常与货运并称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823c9f7d-00cb-41f2-a06b-9f6f2f7e63e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93132, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客运", "is_correct": true, "explanation": "客运：运送旅客的运输业务，与“业务做得很好”相符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不是公司的业务，句意不通。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不是公司的业务，句意不通。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期是时间单位，不是公司的业务，句意不通。"}], "explanations": {"客运": "客运：运送旅客的运输业务，与“业务做得很好”相符。", "月亮": "语义：月亮是天体，不是公司的业务，句意不通。", "星星": "语义：星星不是公司的业务，句意不通。", "星期": "语义：星期是时间单位，不是公司的业务，句意不通。"}, "sentence_index": 0, "correct_answer": "客运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车上的客运坐满了，连过道都站满了人。", "explanation": "这里应该用〈旅客〉。坐满、站满的是人，应说“旅客”；客运是业务。"}, {"text": "这个城市的公共客运只拉货，不接送人。", "explanation": "这里应该用〈货运〉。客运专指运送旅客；只拉货、不接人的应说〈货运〉。"}, {"text": "这个车站今天来了很多客运，大家都在招待。", "explanation": "这里应该用〈客人〉。客运是运输业务，不指来访的人，不能说“来了很多客运”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客运", "is_correct": true, "explanation": "客运：运送旅客的运输业务，与“货运”并列，是运输业的一部分。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不是运输业的一部分，与句意相矛盾。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不属于运输业，与“货运”并列不合理。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“A和货运”并列需要同类概念，钢琴与货运不能并列。"}], "explanations": {"客运": "客运：运送旅客的运输业务，与“货运”并列，是运输业的一部分。", "水果": "语义：水果不是运输业的一部分，与句意相矛盾。", "医院": "语义：医院不属于运输业，与“货运”并列不合理。", "钢琴": "搭配：“A和货运”并列需要同类概念，钢琴与货运不能并列。"}, "sentence_index": 6, "correct_answer": "客运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上挂着一幅客运。", "explanation": "这里应该用〈班〉。“幅”用于画、布等平面的东西，不能用来数客运。"}, {"text": "书架上放着一本客运。", "explanation": "这里应该用〈班〉。“本”用于书册，不能用来数客运。"}, {"text": "码头边停着一只客运。", "explanation": "这里应该用〈班〉。“只”多用于动物，不能用来数客运。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司地客运业务发展得很好。", "corrected_sentence": "这家公司的客运业务发展得很好。", "error_description": "错误：修饰名词“客运业务”应用“的”，不用“地”。正确：「这家公司的客运业务发展得很好。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们镇上新开了一只客运。", "corrected_sentence": "我们镇上新开了一班客运。", "error_description": "错误：量词“只”。正确：“班”，用于定时开行的客运班次。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
